export default [{"id":99,"question":"يا سماحة الشيخ، اعتمرتُ مع والدي، ولكنه لم يستطع إكمال السَّعي بين الصفا والمروة بسبب ألمٍ شديدٍ أصاب ركبته، وقد أكملتُ عنه ثلاثة أشواط، فهل يُجزئ ذلك؟ علمًا بأنه قد قال عند الميقات: فإن حبسني حابسٌ فمحلِّي حيث حبستني، أفيدوني جزاكم الله خيرًا","title":"حكم إنابة من طرأ له عذر في إكمال العمرة","answer":"الجواب:\n\nلا، ما يُجزئ هذا، وعليه أن يسعى ولو محمولًا، ما تنوب عنه أنت، فعليه أن يُعيد السَّعي الآن بنية العمرة السَّابقة، ويُعيد التقصير من رأسه، أو الحلق، وإن أتى زوجته فعليه شاة في العمرة، وعليه أن يُعيد العمرة أيضًا، إن كان قد أتى زوجته فجامعها.\n\nفالعمرة فسدت، وعليه أن يُكملها بالسَّعي ولو محمولًا، وإن كان قد شُفِيَ فالحمد لله، يمشي ويُعيد التَّقصير أو الحلق، ثم يُعيد العمرة كلها من الميقات الذي أحرم بالعمرة الأولى منه؛ لأنَّ العمرة إذا جامع فيها قبل حلّها فسدت، قبل أن يُكمل السعي.\n\nفيُكملها بالسَّعي، ويُعيد التقصير والحلق وتمَّت والحمد لله، وليس عليه شيء، إلا إذا كان قد جامع زوجته بعد هذا؛ فعليه أن يُعيد العمرة مرة أخرى، مع شاةٍ تُذْبَح في مكة للفقراء عن وطئه لها قبل كمال العمرة.\n\nوأما أن تكون أنت قد كمَّلْتَ عنه فلا؛ لأنه وجب عليه هو الطَّواف ولو محمولًا على عربةٍ، يقول الله جلَّ وعلا: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196].\n\nولو كان عاجزًا لا يستطيع أن يصل إلى مكة، ولا يستطيع أن يطوف أو يسعى؛ يُحَجُّ عنه، أما الذي وصل وعرض له عارضٌ في رجله أو في ركبته فهذا يُحْمَل.","link":"https://binbaz.org.sa/fatwas/3128/حكم-انابة-من-طرا-له-عذر-في-اكمال-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0079.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":378,"question":"بعض الحجاج يذهبون إلى الحجِّ والتجارة معًا، وبعضهم يعمل في بعض الأعمال في مكة أثناء حجِّهم، حتى في مناسك الحج، فهل هذا يجوز لهم أم لا؟","title":"حكم الجمع بين الحج والتجارة في مكة","answer":"الجواب:\nلا بأس بذلك، لا بأس أن يجمع الحاجُّ بين هذا وهذا، له أن يحج ويتَّجِر ويعمل في مكة الأعمال المباحة الشرعية، لا بأس بذلك، قال جلَّ وعلا: وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَى وَاتَّقُونِ يَا أُولِي الْأَلْبَابِ [البقرة:197]، ثم قال: لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلًا مِنْ رَبِّكُمْ [البقرة:198] يعني: في مواسم الحج، كما قال ابنُ عباس، فلا بأس أن يحجَّ المؤمنُ ومع ذلك عنده نيَّة أن يتَّجر في مكة، وأن يبيع كذا، أو يشتري كذا، ولا بأس أن يعمل دلَّالًا في كذا، أو بنَّاء، أو غير ذلك، يجمع بين الأمرين، لكن مَن جاء لله خالصًا لا يحمله ولا يدفعه إلا الحجّ؛ يكون أكمل.","link":"https://binbaz.org.sa/fatwas/4698/حكم-الجمع-بين-الحج-والتجارة-في-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0434.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":399,"question":"عندما كان النبي ﷺ في مكة هل كان يقصر الصلاة ويجمع أو يقصر بدون جمعٍ؟","title":"حكم الجمع والقصر في الحج","answer":"الجواب: المعروف عنه ﷺ أنه كان يقصر بدون جمعٍ، وهكذا في منًى، قال العلماء: وهذا هو الأفضل إذا كان المسافر مقيمًا، فالأفضل له أن يقصر بدون جمعٍ، إلا إذا كانت هناك حاجةٌ: كقلة الماء أو أشباه ذلك من الحاجات، فلا مانع من الجمع، ولهذا جمع في تبوك عليه الصلاة والسلام، وتبوك كانت قبل حجة الوداع، ثبت عنه في \"صحيح مسلم\" أنه صلَّى وهو مقيمٌ جمعًا وقصرًا في تبوك عليه الصلاة والسلام.\nوكذلك جمعه ﷺ في عرفة، هو مقيمٌ في عرفة ومع هذا جمع لمصلحة النُّسك؛ حتى يتسع الوقتُ للحُجَّاج بالدعاء والضَّراعة إلى الله ، مع أنه نزل بها قبل الظهر، ولكنه جمع فيها وهو مقيمٌ للمصلحة الظاهرة، وهكذا لو كان الناسُ عليهم مشقَّة مثل: الشتاء والبرد وهم مُسافرون، ورأى أن يجمع بهم دفعًا للمشقَّة التي تحصل بالبرد أو بالرياح الشديدة أو بقلَّة الماء أو ما أشبه ذلك مما يراه رئيسُ الجيش أو كبيرُ القافلة.","link":"https://binbaz.org.sa/fatwas/4794/حكم-الجمع-والقصر-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0456.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":406,"question":"سؤالي سماحتكم عن كيفية الأعمال التي أقوم بها بعد عودتي من مُزدلفة بالترتيب؟","title":"ما الأعمال الواجبة بعد العودة من مزدلفة؟","answer":"الجواب: أولًا تبدأ بالرمي، ثم بالنحر، ثم بالحلق أو التقصير، والحلق أفضل، ثم الطواف، ثم السعي إن كان عليك سعيٌ، هذا هو الترتيب الذي فعله النبيُّ صلى الله عليه وسلم، فإنه رمى يوم النحر، ثم أتى المنحر فنحر هديه، ثم حلق رأسه ووزّع شعره بين الصَّحابة، ثم تطيَّب وتحلّل، وهذا هو التَّحلل الأول، يُباح به لبس المخيط، والتَّطيب، وتغطية الرأس، وقصّ الأظافر والشعر، ونحو ذلك، ويبقى عليه تحريم النِّساء، فلما طاف حلَّ له كل شيء.\nهذا هو الترتيب الذي شرعه الله: رمي، ثم نحر، وحلق أو تقصير، والحلق أفضل، ثم الطواف والسعي للمتمتع، وهكذا للقارن، والحاج المفرد إذا كان ما سعى مع طواف القدوم يسعى مع طواف الإفاضة، وبهذا يحصل التَّحلل الكامل، فيُباح له النساء، والطيب، ولبس المخيط، وتغطية الرأس إذا كان رجلًا، والمرأة كذلك يُباح لها الطيب، ولبس القفازين، ولبس البرقع، وقص الشعر والأظافر، وحلّ زوجها لها، ونحو ذلك مما حرَّم الله على المحرم.\nأما إذا كان إنما رمى فقط فإنه يحلّ له التَّحلل الأول فقط، وهو لبس المخيط والطيب وتغطية الرأس ونحو ذلك، ولا يُباح له النساء.\nواختلف العلماء: هل لا بدّ من ضمِّ الحلق أو التقصير إلى الرمي أم لا؟ على قولين، والأحوط أنه لا يحلّ حتى يضم الحلق أو التقصير إلى الرمي، فلا يعجل حتى يحلق أو يُقصّر، ثم يلبس ملابسه، هذا هو الأحوط له، ومَن لبسها قبل ذلك فلا حرج عليه إن شاء الله، ولا فدية، ولكن ترك الاحتياط؛ لأن الخلاف قويٌّ في هذا، فالعمدة على الرمي، إذا كان رمى الجمرة فإنه العمدة في التَّحلل الأول، وإذا أضاف إلى الرمي الحلق أو التقصير؛ كان ذلك أكمل وأحوط، ثم يبقى عليه بعد ذلك الطواف والسَّعي وتحريم النِّساء، فإذا طاف وسعى حلَّ له كلُّ شيءٍ حرم عليه بالإحرام.","link":"https://binbaz.org.sa/fatwas/4819/ما-الاعمال-الواجبة-بعد-العودة-من-مزدلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0464.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":647,"question":"استدبار الكعبة هل فيه محذور شرعي؟","title":"ما حكم استدبار الكعبة؟","answer":"الجواب: لا، النبي عليه الصلاة والسلام استدبرها وكلم الناس.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6677/ما-حكم-استدبار-الكعبة","audio":"https://files.zadapps.info/binbaz.org.sa/maram215 - 03 - .mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":649,"question":"التعلق بأستار الكعبة؟","title":"ما حكم التعلق بأستار الكعبة؟","answer":"الجواب: ما له أصل، ما ينبغي.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6679/ما-حكم-التعلق-باستار-الكعبة","audio":"https://files.zadapps.info/binbaz.org.sa/maram217 - 03 - .mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":663,"question":"متى تنقطع التلبية هل عند أول حصاة يرميها؟","title":"متى ينقطع وقت التلبية في الحج؟","answer":"الجواب: هذا الأفضل؛ أن يشتغل بالتكبير.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6694/متى-ينقطع-وقت-التلبية-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/maram231 - 03 - .mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":671,"question":"بالنسبة لخطبة يوم النحر تدخل في خطبة العيد؟ ومتى يكون وقتها؟","title":"متى وقت خطبة يوم النحر؟","answer":"الجواب: النبي ﷺ خطبهم يوم النحر بعد الجمرة بعد رمي الجمرة يوم العيد ووقف للناس وخطبهم وذكَّرهم عليه الصلاة والسلام، وفي عرفة خطبهم قبل أن يصلوا الظهر بعد الزوال، قبل أن يؤذن خطب وذكَّر الناس، أو أذن ثم خطب الناس ثم أمر بالإقامة فصلى الظهر، ثم أمر بالإقامة فصلى العصر.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6709/متى-وقت-خطبة-يوم-النحر","audio":"https://files.zadapps.info/binbaz.org.sa/maram239 - 01 -  Start.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":896,"question":"هل يصحّ للمُقيم في مكة المكرمة إذا أحرم بالحج مفردًا أن يقصر الصلاة في منى قبل الذهاب إلى عرفات في يومين؟ أفتونا مأجورين جزاكم الله خيرًا.","title":"هل يقصر الصلاة الحاجُّ المُفْرِدُ المقيمُ بمكة؟","answer":"الجواب: النبي ﷺ قدم صبيحة رابعة من ذي الحجة ولم يزل يقصر الصلاة هو وأصحابه حتى رجع إلى المدينة، فمَن قدم في اليوم الرابع وما بعده يجوز أن يقصر الصلاة، كما فعل النبي ﷺ ويقصر أيضًا في المشاعر: في منى، وعرفات، ومزدلفة، كما فعل النبي عليه الصلاة والسلام.\nومَن كان قبل ذلك بأن قدم في أول ذي الحجة أو قبل ذلك فالذي عليه جمهور أهل العلم أنه يُتم؛ لأن الأصل في حقِّ المقيمين هو الإتمام، هذا هو الأصل، وإنما ترك ذلك على حسب ما ورد عنه عليه الصلاة والسلام، فما كان مثل ما ورد عنه ﷺ قصر فيه الحاجُّ والمسافر، وما زاد على ذلك فالأصل فيه الإتمام في حقِّ المقيمين، فإن المسلم بين ظعنٍ وإقامةٍ، فالمسافر هو الظَّاعن، والمقيم هو الذي يُتم الصلاة.\nوالمقصود أنه إذا كانت الإقامةُ أكثر من أربعةٍ -عزم على الإقامة أكثر من أربعة أيام- قبل الحج فإنه يُتم، وهكذا في كل سفرٍ إذا أقام إقامةً قد عزم عليها أكثر من أربعة أيام أتمَّ، هذا هو رأي أكثر أهل العلم؛ أخذًا من حجة الوداع، أما إذا كانت إقامته ليس فيها عزمٌ على أيامٍ معلومةٍ: قد لا يدري يرتحل اليوم، أو غدًا، أو بعد غدٍ، إنما قدم البلد لحاجةٍ لا يدري متى تنقضي؛ فهذا يقصر مدة إقامته ولو طالت؛ لأنه ليس له إقامة معينة في أي بلدٍ كان، أما الذي أتى الحجَّ قبل يوم الرابع فهذا عند أكثر أهل العلم يُتمّ، وإن كان أتى في اليوم الرابع فما بعده فإنه يقصر كما قصر النبيُّ ﷺ، وبعد ذلك إن سافر بعد الحج فهو على قصره وسفره، وإن نوى إقامة أكثر من أربعة أيام بعد ذلك أتمَّ.","link":"https://binbaz.org.sa/fatwas/20930/هل-يقصر-الصلاة-الحاج-المفرد-المقيم-بمكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0726هل يصح للمقيم بمكة إذا أحرم بالحج مفرداً أن يقصر الصلاة بمنى قبل الذهاب إلى عرفات بومين؟ابن باز.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":1223,"question":"تفضلتم جزاكم الله خيرًا في حديثكم أنَّ من أعظم مقاصد الحج: التَّوجه لله وحده، هل يعني هذا أنَّ مَن أراد الحجَّ والعمل معًا أو التِّجارة بالبيع والشِّراء في المشاعر المُقدَّسة أنَّ حجَّه باطلٌ؟","title":"هل تؤثر التجارة على النية والقصد في الحج؟","answer":"الجواب:\nلا، لا يُقصد هذا، المقصود أنه يحجّ لله، ليس قصده أن الحج للرياء والسّمعة، أو غرض الدنيا، وإذا صار مع حجّه تَكَسّب فلا بأس، كما قال تعالى: لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلًا مِنْ رَبِّكُمْ [البقرة:198]، قال ابنُ عباس: نزلت في التِّجارة في الحج، وأنه لا حرج عليهم في ذلك، وهذا من فضل الله جلَّ وعلا، يحجّ ويتَّجر، أو يكون أجيرًا، أو مُؤجرًا لسيارته، أو نحو ذلك، لكن يكون حجُّه لله، لا لقصد الرياء والسُّمعة، أو لقصد غرضٍ آخر.","link":"https://binbaz.org.sa/fatwas/21289/هل-توثر-التجارة-على-النية-والقصد-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1032من أعظم مقاصد الحج التوجه لله وجده هل يعني هذا أن من أراد الحج والتجارة في المشاعر حجه باطل؟.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":1251,"question":"أهل مكة إذا حجُّوا هل يُتمُّون الصلاة أو يقصرونها في مِنى وعرفة ومُزدلفة؟","title":"هل يَقْصُر أهل مكة الصلاة في مشاعر الحج؟","answer":"الجواب:\nاختلف العلماءُ في حقِّهم: فقال قومٌ: إنَّ أهل مكة لا يقصرون ولا يجمعون؛ لأنهم قريبون من المشاعر، ولا يُسمَّى ذهابهم: سفرًا. وقال آخرون: يجمعون ولا يقصرون؛ لأنَّ الرسول أقرَّهم، جمعوا معه في مُزدلفة وعرفات، والأصل في القصر إنما هو للمُسافر، وليسوا مسافرين، والجمع يكون للحاجة: كالمريض والمطر.\nوفي قولٍ ثالثٍ -وهو الأرجح- أنهم يقصرون مع الحجاج ويجمعون، لا بأس؛ لأنَّ أهل مكة حجُّوا مع النبي ﷺ وقصروا وجمعوا، ولم يُنكر عليهم، جمعوا معه في عرفات ومُزدلفة ولم يُنكر عليهم، وقصروا، والصواب أنَّ هذا شيءٌ خاصٌّ من أجل الحجِّ، لا من أجل السَّفر.","link":"https://binbaz.org.sa/fatwas/21303/هل-يقصر-اهل-مكة-الصلاة-في-مشاعر-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1046أهل مكة إذا حجوا هل يتمون الصلاة أو يقصرونها في منى وعرفه ومزدلفة؟ ابن باز.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":1296,"question":"امرأة عجوز حجَّت هذا العام، وفي أثناء العودة من عرفات إلى مُزدلفة مرضت وأدخلت المُستشفى في نفس الليلة، وبقيت في المستشفى حتى توفَّاها الله، وهي لم تُؤدِّ من الحج إلا الوقوف فقط ومبيت بعض الليل في مُزدلفة، هل يلزم ورثتَها شيءٌ، أن يُتمُّوا لها حجَّها؟","title":"ما حكم مَن مات قبل إكمال مناسك حجه؟","answer":"الجواب:\nلا يلزمهم شيءٌ؛ لأن الرسول ﷺ لما مات الرجلُ الذي وقصته راحلته في عرفات قال: اغسلوه بماءٍ وسدرٍ، وكفِّنوه في ثوبيه، ولم يأمر بتكميل ما فات عليه.\nالمقصود أنَّ المرأة هذه لا يلزم ورثتها شيءٌ، لا يطوفون عنها، ولا يرمون عنها، تُبعث يوم القيامة مُلبيةً؛ لأنَّ الرسول قال في حقِّ مَن وقصته راحلته: اغسلوه وكفِّنوه في ثوبيه، ولا تُخمِّروا رأسه ولا وجهه، فإنه يُبعث يوم القيامة مُلبيًا، دلَّ على أنه يبقى على إحرامه.","link":"https://binbaz.org.sa/fatwas/21373/ما-حكم-من-مات-قبل-اكمال-مناسك-حجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1116عجوز أثناء ذهابها من عرفات إلى مزدلفة مرضت وماتت فهل يلزم على الورثة شيء؟.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":1371,"question":"بعد أداء السُّنة عند مقام إبراهيم في العمرة هل له أن ينزل إلى بئر زمزم أو يشرب من \"الترمس\"؟","title":"هل يلزم الشرب من بئر\"زمزم\" في العُمرة؟","answer":"الجواب:\nما تيسر، الحمد لله، يشرب من الماء الموجود ولا يتكلَّف، الأمر واسع.","link":"https://binbaz.org.sa/fatwas/21464/هل-يلزم-الشرب-من-بىرزمزم-في-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في ماء زمزم.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":1624,"question":"بعد الصلاة وراء المقام هل من السنة أن يذهب إلى زمزم ثم يستلم الحجر الأسود، أو يذهب إلى الحجر الأسود ثم يذهب إلى الصفا؟","title":"ما السُّنة بعد الصلاة خلف مقام إبراهيم؟","answer":"الجواب:\nهذا في طواف الإفاضة، أما في طواف القدوم فبعد الطواف يذهب إلى السعي.\nس: ما يذهب.....؟\nج: لا، هذا بعد طواف الإفاضة الذي ما فيه سعي، أما إذا كان فيه سعي فيبدأ بالسعي.\nس: قبل زمزم؟\nج: قبل كل شيء.","link":"https://binbaz.org.sa/fatwas/21729/ما-السنة-بعد-الصلاة-خلف-مقام-ابراهيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماذا يصنع من انتهى من الصلاة وراء المقام.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":1728,"question":"رجلٌ اشترى من صاحب أرضٍ أرضًا، فعندما قبضها المُشتري وجد في باطنها رِكازًا، فهل هي للمُشتري أم لصاحب الأرض؟","title":"حكم مَن وجد ركازًا في أرض اشتراها","answer":"الجواب:\nالرِّكاز لمن وجده.\nس: إذن للمُشتري؟\nج: نعم.\nس: في الرِّكاز الخمس على كل حال؟\nج: نعم.","link":"https://binbaz.org.sa/fatwas/21835/حكم-من-وجد-ركازا-في-ارض-اشتراها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الركاز.mp3","categories":["مسائل متفرقة في الصيام","مسائل متفرقة في الزكاة","مسائل متفرقة في الحج والعمرة"]},{"id":1730,"question":"أحرم من السَّيل، ثم ذهب إلى مكة ولم يُؤَدِّ العمرة، ثم اتَّجه إلى جدة، ثم عاد إلى مكة مرةً ثانيةً، خروجه من مكة بدون ..؟","title":"حكم من أحرم ووصل مكة وخرج دون عمرة","answer":"الجواب:\nالذي قصد الحج والعمرة وله حاجة يُحرم ويبدأ عمرته، ولا يذهب إلى جدة بإحرامه ثم يعود إلى مكة.\nس: ما عليه شيء؟\nج: أنت إذا مررتَ على الميقات على بيت الأولاد تُقابلهم تُحرم من الميقات، ثم تقابل أهلك وأنت محرم، ثم تطوف وتسعى بعد ذلك، فإذا لم يتيسر لك أن تبدأ بالعمرة فالإحرام يكون من الميقات.","link":"https://binbaz.org.sa/fatwas/21837/حكم-من-احرم-ووصل-مكة-وخرج-دون-عمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أحرم ووصل مكة ولم يعتمر وخرج منها.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":1736,"question":"هل يُشرع للنساء رفع الصَّوت بالتلبية؟","title":"ما حكم رفع الصوت بالتلبية للنساء؟","answer":"الجواب:\nبينهنَّ، كل واحدةٍ ترفع صوتها بقدر ما تُسْمِع مَن حولها من نسائها.","link":"https://binbaz.org.sa/fatwas/21843/ما-حكم-رفع-الصوت-بالتلبية-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع الصوت بالتلبية للنساء.mp3","categories":["مسائل متفرقة في الحج والعمرة","الحيض والنفاس","قضايا المرأة"]},{"id":2003,"question":"دفع الضرائب بدل الزكاة؟","title":"هل تقوم الضرائب مقام الزكاة","answer":"الجواب:\nلا، ما يجزئ الزكاة في حالها والضرائب غرم مفعول الزكاة لا الزكاة على حالها وإذا تيسر الهروب بدون ضرر على حاله، أما إذا كان هروب يضر أحدًا لا.","link":"https://binbaz.org.sa/fatwas/22119/هل-تقوم-الضراىب-مقام-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تقوم الضرائب مقام الزكاة.mp3","categories":["مسائل متفرقة في الصيام","مسائل متفرقة في الزكاة","مسائل متفرقة في الحج والعمرة"]},{"id":2259,"question":"يريد أداء الزكاة في بلدٍ خارج الرياض، ولا بد لإيصال الزكاة هذه من مالٍ يُدفع أجرةً للتَّحويل، فيقول: هل يجوز لي أن أجعل من الزكاة هذا المال الذي هو قيمة التَّحويل أم لا؟","title":"هل يجوز خصم أجرة التحويل من مال الزكاة؟","answer":"الجواب:\nلا، الأموال التي أعطاها المحوِّل ليست من الزكاة، فهذه أجرة، والزكاة غيرها.\nس: تُدفَع كاملةً؟\nج: نعم.","link":"https://binbaz.org.sa/fatwas/22382/هل-يجوز-خصم-اجرة-التحويل-من-مال-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يتم خصم أجرة تحويل مال الزكاة من المال.mp3","categories":["مسائل متفرقة في الصيام","مسائل متفرقة في الزكاة","مسائل متفرقة في الحج والعمرة"]},{"id":2294,"question":"رجلٌ في أشهر الحج اعتمر، ثم رجع إلى بلده، ثم ذهب إلى الحج مرةً أخرى، فيقول: هل عليَّ هَدْيٌ أم لا؛ لأني سافرتُ سفرين؟","title":"حكم مَن اعتمر ورجع لبلده ثم أراد الحج؟","answer":"الجواب:\nالمعروف عند العلماء أنه لا هديَ عليه إذا رجع لأهله، وإن فَدَى احتياطًا على ظاهر كلام ابن عباس فلا بأس.\nس: هل لا يزال متمتعًا؟\nج: ما دام قد رجع إلى أهله فإنه يصير مُفردًا إذا رجع بحجٍّ.\nس: وما الصواب؟\nج: الأحوط له أنه يفدي؛ خروجًا من الخلاف، وهذا طيب.","link":"https://binbaz.org.sa/fatwas/22417/حكم-من-اعتمر-ورجع-لبلده-ثم-اراد-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اعتمر في أشهر الحج ثم رجع إلى بلده فما الحكم.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":2354,"question":"سائلٌ يقول: هل يجوز لي أن أقوم بأداء العمرة لوالدي المتوفى في هذه الأيام، وهذه الأيام أشهر الحج، وإذا نويتُ أداء فريضة الحج بعد ذلك، هل يكون الحجُّ مفردًا أم تمتُّعًا؟","title":"حكم مَن اعتمر عن أبيه المتوفى ثم أراد الحج","answer":"الجواب:\nالاعتمار عن أبيك والحجّ عنه من البِرِّ له، وأنت مأجورٌ، وإذا اعتمرتَ هذه الأيام ثم رجعتَ إلى أهلك، ثم رجعتَ بحجٍّ مُفْرَدٍ فهو حجٌّ مُفْرَدٌ، أمَّا إذا لم ترجع إلى أهلك، بل ذهبتَ إلى جهاتٍ أخرى، ثم رجعتَ بحجَّةٍ؛ تكون مُتَمَتِّعًا وعليك دمٌ.","link":"https://binbaz.org.sa/fatwas/22479/حكم-من-اعتمر-عن-ابيه-المتوفى-ثم-اراد-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اعتمر عن والده المتوفى في أشهر الحج ثم نوى أداء فريضة الحج.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":2626,"question":"تارك الزكاة كافر؟","title":"هل تارك الزكاة كافر أم عاصٍ؟","answer":"الجواب: ما هو كافر، لا، عاصٍ، يُجبر عليها ويُلزم بها، ولهذا يوم القيامة يُؤتى بتارك الزكاة، إنْ كان إبل أو بقر أو غنم جيء بها تطؤه -نسأل الله العافية- تطؤه الإبل بأخفافها وتعضه بأفواهها وتطؤه البقر والغنم بأظلافها وتنطحه بقرونها، في يوم كان مقداره خمسين ألف سنة، ثم يرى سبيله إما إلى الجنة، إما إلى النار، وهكذا يُحمى على ذهبه وفضته ويُكوى به -نسأل الله العافية-. فالمقصود أن ترك الزكاة كبيرة من الكبائر العظيمة يستحق صاحبها العذاب والعقوبة في الدنيا، إلا إذا جحد وجوبها كفر، نسأل الله العافية، أو قاتل دونها كفر.\nس: قتال أبي بكر لهم؟\nالشيخ: كفرهم لما قاتلوا دونها؛ لأن من قاتل دونها فقد جحدها، لما قاتلوا عُوقبوا، أما من لم يجحد يُعاقب إنا آخذوها وشَطْرَ ماله يُعاقب ولا يَكْفُر.\nس: كيف يوجه قول أبي بكر (لو منعوني عِقالا)؟\nالشيخ: (لقاتلتهم على منعه) إذا امتنعوا يُقاتلون، لكن لا يَكْفُرون بالمنع إلا إذا قاتلوا دونها فقتالهم دونها علامة على جَحْدها، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22761/هل-تارك-الزكاة-كافر-ام-عاص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تارك الزكاة.mp3","categories":["مسائل متفرقة في الصيام","مسائل متفرقة في الزكاة","مسائل متفرقة في الحج والعمرة"]},{"id":2632,"question":"من قال مِن مانعي الزكاة أن الزكاة لا تؤدى إلا لرسول ﷺ ما يكون متأوِّلا؟","title":"حكم زَعْم أن الزكاة لا تؤدى إلا للنبيّ ﷺ","answer":"يُعَلَّم، فإن أصر يُقاتل، وإن هداه الله؛ تُؤخذ منه الزكاة غصبًا عليه ويُعَزَّر بالمال، كما في حديث بهز بن حكيم: وإنَّا آخذوها وشَطرَ مالِه عَزَمةً من عزَماتِ ربِّنا، لكن إذا قاتل يُقاتل كما فعل أهل الردة، إذا قاتلوا، قاتلهم الصديق، أما إذا لم يقاتل وكان مقدورًا عليه يُلزم.","link":"https://binbaz.org.sa/fatwas/22767/حكم-زعم-ان-الزكاة-لا-تودى-الا-للنبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من قال متأولا من مانعي الزكاة أن الزكاة لا تؤدى إلى إلا الرسول.mp3","categories":["مسائل متفرقة في الصيام","مسائل متفرقة في الزكاة","مسائل متفرقة في الحج والعمرة"]},{"id":2637,"question":"مانع الزكاة يُعَذَّب قبل أن يحاسب؟","title":"هل يُعَذَّب مانعُ الزكاة قبل أن يُحاسب؟","answer":"الجواب: يُعَذَّب قبل النار، عذاب يوم القيامة، نسأل الله العافية.\nس: اللي ما يطلع زكاته كاملة يستحق نفس العذاب؟\nالشيخ: على قدر ما بخل به ناله نصيبه، على قدر ما بخل به.\nس: بعضهم يخرج زكاة رمضان السابق واللاحق.\nالشيخ: إذا عَجَّل التي ما بَعْد حلّت.\nس: لكنه يؤخّرها.\nالشيخ: لا يجوز له التأخير، يجب عليه إذا كانت حلّت يخرجها، لا يؤخر.\nس: يقول هذه عادتي؟\nالشيخ: ولو عادته، عادته السيئة تُترك.","link":"https://binbaz.org.sa/fatwas/22772/هل-يعذب-مانع-الزكاة-قبل-ان-يحاسب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعذب مانع الزكاة قبل أن يحاسب.mp3","categories":["مسائل متفرقة في الصيام","مسائل متفرقة في الزكاة","مسائل متفرقة في الحج والعمرة"]},{"id":2798,"question":"هل المُنكرات مُضاعفة في الحج، مثل حلق اللحية والشرب والغيبة والنميمة؟","title":"هل تضاعف المُنكرات في الحج؟","answer":"الجواب: السيئة ما تُضاعف، السيئات لا تضاعف من جهة العدد، ولكن تضاعف من جهة الكيفية وشدة الإثم، وإلا السيئة مثل ما قال الله السيئة بواحدة مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا وَمَنْ جَاءَ بِالسَّيِّئَةِ فَلَا يُجْزَى إِلَّا مِثْلَهَا [الأنعام:160] في أي مكان لا يُجزى إلا مثلها، لكن سيئة في الحرم أعظم وأكبر وأشد إثمًا من سيئة في غير الحرم كالطائف وجدة ونحو ذلك، كما أن السيئة في رمضان أشد إثمًا من السيئة في شعبان وشوال، وهكذا السيئة في ذي الحجة، أشهر ذي الحجة، أعظم إثمًا من السيئة في ذي القعدة، أو ما بعد العيد. والمقصود من هذا أن الحسنات تُضاعف من جهة الكمية والعدد جميعًا، أما السيئة فلا تضاعف إلا من جهة الكيفية فقط، الكيفية لها شأن، فسيئة في الحرم مثلما تقدم في مكة ليست مثل سيئة في الطائف وفي جدة في الإثم، بل هي أشد إثمًا، وهكذا الحسنات مضاعفة في مكة وفي الزمن الفاضل كرمضان وعشر ذي الحجة.","link":"https://binbaz.org.sa/fatwas/22946/هل-تضاعف-المنكرات-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تضاعف المنكرات في الحج.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":2842,"question":"شخص جمع جمعية له ليدفع منها زكاة ماله عن أرض في مصر، سُرق منه مال الزكاة ومصروفه الشخصي في المدينة، هل يُعتبر أنه أخرج مال الزكاة بنيّته أم ماذا؟ وجزاكم الله خيرًا.","title":"ما حكم مَن أخرج مال الزكاة فسُرِق قبل أدائه؟","answer":"الجواب: لا، ما أدّى الزكاة؛ حتى يوصِلها إلى أهلها، إذا سُرقت هذا يُعَوِّضه الله خيرًا، لكن عليه الزكاة، عليه أن يؤدي الزكاة حتى يوصلها إلى أهلها ما دامت عنده ما أداها، سواء سرقت أو أنفقها، ما أدى الزكاة حتى يخرج الزكاة.","link":"https://binbaz.org.sa/fatwas/22995/ما-حكم-من-اخرج-مال-الزكاة-فسرق-قبل-اداىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أخرج مال الزكاة فسرق منه.mp3","categories":["مسائل متفرقة في الصيام","مسائل متفرقة في الزكاة","مسائل متفرقة في الحج والعمرة"]},{"id":2843,"question":"رجل دخل في العمرة ولبّى بها ظهرَ ثلاثين رمضان، ووصل مكة فجر العيد وأتم عمرته بعد صلاة العيد، هل تعتبر عمرته في رمضان؟","title":"حكم مَنْ أحْرَم آخِرَ رمضان وأتم عُمرته بعده؟","answer":"الجواب: العبرة بوقت الإحرام؛ تُعتبر في رمضان، ما دام أحْرَم بها في رمضان فهي عمرة في رمضان.","link":"https://binbaz.org.sa/fatwas/22996/حكم-من-احرم-اخر-رمضان-واتم-عمرته-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دخل في العمرة ظهر ثلاثين رمضان ووصل مكة فجر العيد فهل عمرته في رمضان.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":3167,"question":"تقول إن لها ابنة عندها سنة وخمسة شهور وتريد الحج هذا العام، ولأجل هذا الأمر تريد أن تَفْطِمها، هل عليها شيء؟","title":"هل يجوز فِطامُ الطفل لأجل الحج؟","answer":"الجواب: تتشاور هي وزوجها، إذا كان ما في فِطامها مضرة فلا بأس، إذا كانت تأكل تتغذى بشيء آخر؛ فالله جل وعلا يقول: فَإِنْ أَرَادَا فِصَالًا عَنْ تَرَاضٍ مِنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَا.. [البقرة 233]، الفِصال: الفِطام، إذا أرادت المرأة أن تفطِمها لأقل من سنتين فلا بد من التشاور مع زوجها فإذا كان فطامها لا يضرها فلا بأس.","link":"https://binbaz.org.sa/fatwas/23330/هل-يجوز-فطام-الطفل-لاجل-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فطام الطفل لأجل الحج.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":3323,"question":"بعض الناس يظن أن الحج إذا صادف جمعة فإنه له مَزِيّةٌ على غيره؟","title":"هل للحج مَزِيّةٌ إذا صادف يوم جمعة؟","answer":"الجواب: بسط الكلام في هذا ابن القيم رحمه الله في أول الهَدْي؛ لأنه صادف حجة النبي ﷺ، ولكن لم يرد فيه شيء خاص، وإنما صادف حجة النبي ﷺ وهو أفضل أيام الأسبوع؛ فله مَزِيّةٌ من هذه الحيثية.","link":"https://binbaz.org.sa/fatwas/23489/هل-للحج-مزية-اذا-صادف-يوم-جمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للحج إذا صادف يوم جمعة مزية عن غيره.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":3348,"question":"لو فعله متعمّدًا (التقديم والتأخير الخاطئ في الحج)؟","title":"حكم تَعَمُّد التقديم والتأخير في مناسك الحج","answer":"الجواب: لا حرج، قد يحتاج إلى هذا، قد يتأخر النحر ما يكون جاهزًا، قد يُقَدّم الحلق، قد يتيسر له الحلق قبل الرمي؛ لا بأس.\nس: لا يكون هذا معلقًا بالنُّسُك؛ فمن كان نُسُكُه الإفراد: يحلق؟\nالشيخ: لا، عام، عام يا ولدي، الرسولﷺ ما فصّل، ما فصّل الناس في يوم العيد، وفي القارن، وفي المتمتع؛ فالأمر بحمد الله مُيَسّر.\nس: وإن كان مُفْرِدا يا شيخ؟\nالشيخ: مفردًا، أو متمتعًا، أو قارنًا؛ هذا حُكمه: الرمي، ثم النحر، ثم الحلق، ثم الطواف، ومن قدّم شيئًا على شيء فلا حرج.\nس: تقديم السعي على الطواف؟\nالشيخ: الصواب لا حرج فيه، لكن الأفضل يَقَدّم الطواف، هذا هو السُّنة كما فعل النبي ﷺ طاف ثم سعى.","link":"https://binbaz.org.sa/fatwas/23514/حكم-تعمد-التقديم-والتاخير-في-مناسك-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من تعمد تقديم أو تأخير الحلق أو الرمي، وما أشبه ذلك في الحج.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":3445,"question":"الذين عندهم عاملات في البيت، خادمات، وأرادوا الحج، ماذا يفعلون؟","title":"ما يفعل من كان عنده خادمات وأراد الحج؟","answer":"الجواب: يذهبون معهم، مثل عائشة أعتقت بريرة مع النبي ﷺ، مثل بقية الخادمات، لا يضيعونهن، تبع.","link":"https://binbaz.org.sa/fatwas/23620/ما-يفعل-من-كان-عنده-خادمات-واراد-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من كان عنده عاملات وأراد الحج.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":4385,"question":"يقول بعض الناس: إذا اعتمرت في شهر شوال ثم رجعت إلى بلدك ثم ذهبت إلى الحج في نفس العام فعليك دم العمرة، ما صحة هذا الكلام، وما المقصود بدم العمرة؟","title":"ما حكم من اعتمر في شوال ورجع لبلده ثم حج؟","answer":"الجواب: ما عليه شيء، إذا اعتمر ثم رجع إلى أهله ثم حج حجا مفردا ليس عليه شيء عند أهل العلم كما أفتى به عمر وغيره رضي الله عنه؛ لأنه جاء بحج مفرد.","link":"https://binbaz.org.sa/fatwas/24662/ما-حكم-من-اعتمر-في-شوال-ورجع-لبلده-ثم-حج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما الواجب على من اعتمرت في شهر شوال، ورجع إلى بلده، ثم حج في نفس العام.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":4646,"question":"لو أحرمت المرأةُ بالعمرة ثم جاءها الحيضُ وأرادت أن ترجع إلى بلدها بدون عمرةٍ، يلزمها دمٌ؟","title":"حكم من حاضت في العمرة وتريد الرجوع لبلدها","answer":"الجواب: ليس لها ذلك، لا بد أن تكمل عمرةً، بعدما تطهر تكمل العمرة، تبقى في مكة حتى تكمل، فإن اضطرَّت للخروج تخرج إلى جدة، إلى الطائف، ثم ترجع وتُكمل، إذا صارت مشقة على أوليائها يخرجون إلى جدة أو الطائف أو غيرهما ثم يرجعون.\nس: وإذا خرجت عليها دم؟\nج: لا، ما عليها شيء، ترجع فقط وتكمل، عليها أن تأتي وتُكمل عمرتها.","link":"https://binbaz.org.sa/fatwas/24936/حكم-من-حاضت-في-العمرة-وتريد-الرجوع-لبلدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من أحرمت بالعمرة ثم جاءها الحيضُ وأرادت الرجوع إلى بلدها بدون عمرةٍ.mp3","categories":["مسائل متفرقة في الحج والعمرة","الحيض والنفاس","قضايا المرأة"]},{"id":4662,"question":"قول شيخ الإسلام: مَن أتى بعمرةٍ مفردةٍ في رمضان وبقي في مكة إلى الحج أفضل ممن أتى مُتمتعًا أثناء الحج؟","title":"حكم مَن اعتمر في رمضان وبقي إلى الحج","answer":"الجواب: هذا محل نظرٍ، والأمر واسع، إذا أتى بعمرةٍ في رمضان وبقي حتى يُحرم بالحجِّ لا بأس، وإن أراد أن يأخذ عمرةً بأشهر الحجِّ فلا بأس، لكن المقصود الذي فيه الأحاديث إذا قدم في أشهر الحجِّ هذا محل البحث، أما مَن قدم في رمضان فالسنة أن يُحرم بعمرةٍ فقط.","link":"https://binbaz.org.sa/fatwas/24954/حكم-من-اعتمر-في-رمضان-وبقي-الى-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول شيخ الإسلام مَن أتى بعمرةٍ مفردةٍ في رمضان وبقي في مكة إلى الحج أفضل ممن أتى.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":4664,"question":"كون النبي ﷺ أمر مَن لم يسقِ الهدي بالإحلال، ولم يأذن إلا لعائشة، ما يدل على وجوب أنَّ مَن لم يسق الهدي أن يحلَّ إلا مَن عنده عذر كعائشة؟","title":"حكم مَنْ حَلِّ مَن الحج ولم يسقِ الهدي","answer":"الجواب: هذا قول بعض أهل العلم، والمشهور أنه للسنية، وابن القيم رحمه الله يميل إلى الوجوب لظاهر الأوامر، والشيخ تقي الدين يقول: إنه واجب على الصحابة، سنة في حقِّ غيرهم. ولكن الجمهور على أنه مُستحب للجميع، مَن حجَّ قارنًا ولم يسقِ الهدي السنة له أن يحلَّ، وقد يستدلون له بحديث عروة بن مضرس؛ فإنه حجَّ ولم يأمره النبيُّ ﷺ بأن يتحلل، لكنه إنما سأل النبيَّ ﷺ ليلة عرفة، فليس فيه حُجَّة ظاهرة.\nوالمقصود أنَّ القول بوجوب الفسخ قول قوي؛ لظاهر الأوامر، وإليه يميل ابنُ القيم رحمه الله مطلقًا، وهو المشهور عن ابن عباسٍ، قال: \"مَن حجَّ هذا البيت وطاف وسعى فقد حلَّ\"، يعني إذا لم يسقِ الهدي.\nس: وجه تقييد شيخ الإسلام للصحابة بالخصوص؟\nج: ليس بظاهر، النبي باشرهم بالأمر، لكن أمره لهم أمر لغيرهم، وكلام ابن القيم في هذا أقوى من كلام شيخ الإسلام، القول بالوجوب أقوى في الأدلة.\nس: حديث سُراقة: بل لأبد الأبد؟\nج: عام للجميع، ويستدل الجمهورُ بما فعل الصديقُ وعمر وعثمان؛ كانوا يُحرمون بالحجِّ ولا يحلُّون إلا بعد ذلك، وكان عليٌّ  وأرضاه وابن عباسٍ يحثُّون الناس على العمرة، والصديق وعمر وعثمان رأوا أن يقدم بحجٍّ؛ حتى يكون للعمرة وقتٌ آخر؛ حتى يكثر الزوار في البيت والعُمَّار والحُجَّاج، من باب الاجتهاد.\nس: ما ذكر توجيهًا لما اختاره شيخ الإسلام؟\nج: ما أتذكر شيئًا واضحًا.","link":"https://binbaz.org.sa/fatwas/24956/حكم-من-حل-من-الحج-ولم-يسق-الهدي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في حِلِّ مَن حجَّ ولم يسقِ الهدي.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":4665,"question":"المُتمتع إذا انتهت عمرته يقطع التَّلبية إلى حين الدخول في الحج؟","title":"متى يقطع المُتمتع التَّلبية؟","answer":"الجواب: يقطع التلبية حين يشرع في العمرة، فإذا لبَّى بالحج بعد ذلك شرع في التَّلبية.","link":"https://binbaz.org.sa/fatwas/24957/متى-يقطع-المتمتع-التلبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يقطع المُتمتع التَّلبية.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":4708,"question":"أهل مكة قصرهم للنُّسك؟","title":"حكم قصر أهل مكة للصلاة والنسك","answer":"الجواب: تبع الحُجَّاج؛ لأنَّ الرسول أقرَّهم، ما نهاهم، ما قال: يا أهل مكة، أتمُّوا. مثلما قال لهم يوم الفتح: أتمُّوا فإنَّا قوم سَفْرٌ.\nس: إذا كانوا بعيدين عن مسجد نمرة ولا يسمعون الخطبة؟\nج: يُصلون وحدهم الظهر والعصر جمعًا في منازلهم.\nس: ويخطب بهم أحدهم؟\nج: إذا خطب بهم أحدهم لا بأس، وإن استمعوا من طريق مكبرات الصوت أو من طريق المذياع فالحمد لله.\nس: قول بعض أهل العلم أنَّ قصر أهل مكة للسفر، هل هو وجيه؟\nج: لا، ما هو بواردٍ، ما بين منى ومكة مدة سفر، ما بين منى وعرفة سفر قصير.","link":"https://binbaz.org.sa/fatwas/25000/حكم-قصر-اهل-مكة-للصلاة-والنسك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قصر أهل مكة للصلاة والنسك.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":4710,"question":"..... في الحديث ورد أنه ﷺ صلى في مكة يوم النحر، ولكن إذا نظرنا إلى الأعمال التي قام بها النبيُّ ﷺ قد تستهلك أكثر الوقت، فقد نحر ثلاثًا وستين بدنة بيده عليه الصلاة والسلام، وانتظر حتى قسمت ثم طُبخت ثم شرب من مرقها وأكل من لحمها، ثم قبل هذا قصَّر من رأسه، وبيَّن للناس أحكام ذلك، وسألوه، فقد يستهلك هذا وقت، وقد لا يستطيع أن يذهب إلى مكة؟!","title":"كيف قام النبي بأعمال كثيرة يوم النحر؟","answer":"الجواب: اليوم طويل، حجة النبي في أيام الحرِّ، أيام طويلة، وهو نحر مبكرًا، نحر الإبل مبكرًا عليه الصلاة والسلام وأكلوا منها، ثم ذهب وصلَّى في مكة الظهر عليه الصلاة والسلام، الوقت واسع، والضحى طويل في أيام الحرِّ، أيام الصيف، قريب من ثماني ساعات من الفجر إلى الظهر، فإذا رمى الجمرة بعد طلوع الشمس يمكن قريب من خمس ساعات، يمكن انتهى من نحر الإبل والطبخ لها في ثلاث ساعات أو حولها أو أربع، ثم راح مكة قبل الزوال بساعةٍ أو نحوها، يمكن، الأمر واسع؛ لأنَّ النهار طويل، والضحى طويل، أيام الغيض.\nس: كذلك الزحام ما كان مثل اليوم؟\nج: والزحام قليل.","link":"https://binbaz.org.sa/fatwas/25002/كيف-قام-النبي-باعمال-كثيرة-يوم-النحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في صلاة النبي يوم النحر ونحره ثلاثة وستين بدنة.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":4718,"question":"مَن قدَّم وأخَّر مُتعمدًا؟","title":"حكم التقديم والتأخير بين مناسك الحج","answer":"الجواب: ما في بأس، لا حرج.\nس: مَن طاف ولم يحلق ولم يرمِ هل يحلّ أو لا؟\nج: لا، ما يحل حتى يرمي ويحلق مع الطواف، قد يقال: إذا حلَّ بعد الرمي فالطواف من باب أولى، لكن كونه يصبر حتى يفعل الثاني أحوط، حتى يرمي أو يحلق، فإذا فعل الثلاثة حصل التَّحلل الكامل.\nس: يستقبل القبلة في حال الحلق؟\nج: ما أعلم في هذا شيئًا.\nس: حديث عائشة فيه أنَّه نحر ثم رجم ثم نحر؟\nج: رمى ثم نحر، ثابت في الأحاديث الصحيحة، ثم حلق بعد ذلك.\nس: ....... انصرف من مُزدلفة، ما ذهب إلى منًى يرمي، ذهب إلى الحرم لأنَّ معه نسوانًا؟\nج: لا حرج، بدأ بالطواف لا حرج، قال رجلٌ: يا رسول الله، ....... قبل أن أرمي، قال: لا حرج، فإذا انصرف من مُزدلفة ونزل مكة وطاف لا حرج، ثم يرمي بعد ذلك.","link":"https://binbaz.org.sa/fatwas/25011/حكم-التقديم-والتاخير-بين-مناسك-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل متفرقة في الحج والعمرة.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":4889,"question":"يُعطى من الزكاة أو من النفقات من خسر بضاعته وأفلس؟","title":"هل تجوز الزكاة للمفلس؟ وهل يُحذَّر الناس منه؟","answer":"من ذا ومن ذا، إذا كان فقيرًا يُعطى من الصدقة ومن الزكاة.\nس: هل يُحذَّر الناس من التعامل مع المفلس؟\nج: لا ما هو بلازم.\nس: يغرُّ الناس بأكل حقوقهم وهذا مشتهر الآن؟ ما يُحذر ولا يكون من باب الغيبة؟\nج: هذا محل نظر، أما هو في حقه له أن يشتكيه ويقول: ظلمني، بطلني حقي؛ لأنه مظلوم. أما مسألة إخبار الناس أنه مفلس: هذه محل نظر؛ لأنه قد يكون مضطرًا يشتري حاجات.","link":"https://binbaz.org.sa/fatwas/25401/هل-تجوز-الزكاة-للمفلس-وهل-يحذر-الناس-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يحذر الناس من التعامل مع المفلس.mp3","categories":["مسائل متفرقة في الصيام","مسائل متفرقة في الزكاة","مسائل متفرقة في الحج والعمرة"]},{"id":5549,"question":"التكبير المُقَيَّد بالنسبة للحاجِّ؟","title":"متى يبدأ التكبير المُقَيَّد بالنسبة للحاجِّ؟","answer":"الجواب: يبدأ من ظهر يوم النحر؛ لأنه مشغول بالتلبية، إذا أحرم بالحجِّ مشغول بالتلبية، فيشتغل بالتلبية أفضل، وإن كبَّر فلا بأس، قال أنسٌ في \"الصحيحين\": كان يُهلُّ منا المهلُّ ولا يُنكر عليه، ويُكبر المكبر فلا يُنكر عليه، حين توجَّهوا إلى عرفات مع النبي ﷺ، لكن التَّلبية أوْلى في هذا؛ لأنها شعار الحجِّ.[1]","link":"https://binbaz.org.sa/fatwas/31493/متى-يبدا-التكبير-المقيد-بالنسبة-للحاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 011.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":6254,"question":"وآخر أرسل إلينا سؤالاً بخط ركيك نحاول قراءته على علته، فيقول: سمعت يوم عرفة محدثًا يقول: العيد أربعة أيام، مثل عدد الرمي، أن الرمي أربعة أيام، فيقول العيد أربعة أيام كذلك، وسمعه يقول: من تعجل؛ فيرمي أربعة بحجر اليوم الثاني عشر مع الحادي عشر، يعني يرمي يوم حادي عشر، ثم يرمي يوم الثاني عشر؟","title":"بيان عدد أيام عيد الأضحى والتعجيل للحاج فيها","answer":"الجواب: هذا كلام معقول، معناه أن أيام العيد التي هي أيام الذبح، وتسمى أيام العيد أربعة، يوم العيد، وثلاثة أيام بعده، وكلها فيها رمي يوم العيد، يرمي جمرة العقبة، والحادي عشر، يرمي الجمرات الثلاث، والثاني عشر، يرمي الجمرات الثلاث، وهكذا الثالث عشر فيمن لم يتعجل، فيرمي الجمرات الثلاث، فهي كلها أيام عيد، كلها أيام رمي، كلها أيام ذبح، كلها أيام أكل، وشرب، وذكر لله .  فإذا رمى يوم العيد، ورمى اليوم الحادي عشر الجمار الثلاث بعد الزوال، ورمى الثاني عشر بعد الزوال، الجمار الثلاث؛ فله التعجل قبل غروب الشمس، له أن يتعجل من منى إلى مكة قبل غروب الشمس، ويعود إلى وطنه إذا شاء؛ فلا بأس في ذلك، يتعجل، ولا شيء عليه، وإن بات ليلة الثالث عشر، ورمى يوم الثالث عشر؛ فهو أفضل؛ لأن الرسول -عليه الصلاة والسلام- بات، ورمى في اليوم الثالث عشر، هذا هو الأفضل؛ لما فيه من زيادة العمل، والتأسي بالنبي -عليه الصلاة والسلام- وإن تعجل بعد الزوال، وبعد الرمي في اليوم الثاني عشر؛ فلا بأس عليه. وله أن يقيم في مكة ما شاء، فإذا أراد السفر؛ طاف للوداع بعد ذلك، وإن تعجل في الحال، وسافر بعد الوداع بعدما رمى يوم الثاني عشر، مر إلى مكة، وطاف الوداع، ومشى، وسافر؛ فلا بأس. ولكن بعض الناس قد يغلط، ويعد يوم العيد هو اليوم الأول من أيام التشريق، وإذا رمى يوم الحادي عشر؛ تعجل، وهذا غلط يوم العيد، ليس من أيام التشريق المذكورة في قوله -جل وعلا-: وَاذْكُرُواْ اللّهَ فِي أَيَّامٍ مَّعْدُودَاتٍ فَمَن تَعَجَّلَ فِي يَوْمَيْنِ فَلاَ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلا إِثْمَ عَلَيْهِ لِمَنِ اتَّقَى [البقرة:203] هذه الأيام غير يوم العيد، هي الحادي عشر، والثاني عشر، والثالث عشر، فالتعجل في يومين معناه الثاني عشر، ويوم العيد، لا يعد منها.  فينبغي أن يفهم هذا الأيام الثلاثة، هي: الحادي عشر، والثاني عشر، والثالث عشر، والتعجل يكون في الثاني عشر، والتريث يكون إلى الثالث عشر، ولا يجوز الرمي إلا بعد الزوال في هذه الثلاثة أيام، كله بعد الزوال، والتعجل يكون من بعد رمي الجمار، وبعد زوال الشمس، يرميها بعد الزوال، ثم يتعجل إلى مكة، فيطوف طواف الوداع، ثم يسافر إذا شاء، وإن بقي في مكة؛ فيبقى حتى يعزم على السفر، فإذا عزم على السفر؛ طاف للوداع.","link":"https://binbaz.org.sa/fatwas/1775/بيان-عدد-ايام-عيد-الاضحى-والتعجيل-للحاج-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_614.mp3","categories":["مسائل متفرقة في الحج والعمرة","البيوع","الأخلاق المذمومة"]},{"id":6263,"question":"وآخر أرسل إلينا سؤالاً بخط ركيك نحاول قراءته على علته، فيقول: سمعت يوم عرفة محدثًا يقول: العيد أربعة أيام، مثل عدد الرمي، أن الرمي أربعة أيام، فيقول العيد أربعة أيام كذلك، وسمعه يقول: من تعجل؛ فيرمي أربعة بحجر اليوم الثاني عشر مع الحادي عشر، يعني يرمي يوم حادي عشر، ثم يرمي يوم الثاني عشر؟","title":"بيان عدد أيام عيد الأضحى والتعجيل للحاج فيها","answer":"الجواب: هذا كلام معقول، معناه أن أيام العيد التي هي أيام الذبح، وتسمى أيام العيد أربعة، يوم العيد، وثلاثة أيام بعده، وكلها فيها رمي يوم العيد، يرمي جمرة العقبة، والحادي عشر، يرمي الجمرات الثلاث، والثاني عشر، يرمي الجمرات الثلاث، وهكذا الثالث عشر فيمن لم يتعجل، فيرمي الجمرات الثلاث، فهي كلها أيام عيد، كلها أيام رمي، كلها أيام ذبح، كلها أيام أكل، وشرب، وذكر لله .  فإذا رمى يوم العيد، ورمى اليوم الحادي عشر الجمار الثلاث بعد الزوال، ورمى الثاني عشر بعد الزوال، الجمار الثلاث؛ فله التعجل قبل غروب الشمس، له أن يتعجل من منى إلى مكة قبل غروب الشمس، ويعود إلى وطنه إذا شاء؛ فلا بأس في ذلك، يتعجل، ولا شيء عليه، وإن بات ليلة الثالث عشر، ورمى يوم الثالث عشر؛ فهو أفضل؛ لأن الرسول -عليه الصلاة والسلام- بات، ورمى في اليوم الثالث عشر، هذا هو الأفضل؛ لما فيه من زيادة العمل، والتأسي بالنبي -عليه الصلاة والسلام- وإن تعجل بعد الزوال، وبعد الرمي في اليوم الثاني عشر؛ فلا بأس عليه. وله أن يقيم في مكة ما شاء، فإذا أراد السفر؛ طاف للوداع بعد ذلك، وإن تعجل في الحال، وسافر بعد الوداع بعدما رمى يوم الثاني عشر، مر إلى مكة، وطاف الوداع، ومشى، وسافر؛ فلا بأس. ولكن بعض الناس قد يغلط، ويعد يوم العيد هو اليوم الأول من أيام التشريق، وإذا رمى يوم الحادي عشر؛ تعجل، وهذا غلط يوم العيد، ليس من أيام التشريق المذكورة في قوله -جل وعلا-: وَاذْكُرُواْ اللّهَ فِي أَيَّامٍ مَّعْدُودَاتٍ فَمَن تَعَجَّلَ فِي يَوْمَيْنِ فَلاَ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلا إِثْمَ عَلَيْهِ لِمَنِ اتَّقَى [البقرة:203] هذه الأيام غير يوم العيد، هي الحادي عشر، والثاني عشر، والثالث عشر، فالتعجل في يومين معناه الثاني عشر، ويوم العيد، لا يعد منها.  فينبغي أن يفهم هذا الأيام الثلاثة، هي: الحادي عشر، والثاني عشر، والثالث عشر، والتعجل يكون في الثاني عشر، والتريث يكون إلى الثالث عشر، ولا يجوز الرمي إلا بعد الزوال في هذه الثلاثة أيام، كله بعد الزوال، والتعجل يكون من بعد رمي الجمار، وبعد زوال الشمس، يرميها بعد الزوال، ثم يتعجل إلى مكة، فيطوف طواف الوداع، ثم يسافر إذا شاء، وإن بقي في مكة؛ فيبقى حتى يعزم على السفر، فإذا عزم على السفر؛ طاف للوداع.","link":"https://binbaz.org.sa/fatwas/1775/بيان-عدد-ايام-عيد-الاضحى-والتعجيل-للحاج-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_614.mp3","categories":["مسائل متفرقة في الحج والعمرة","البيوع","الأخلاق المذمومة"]},{"id":6355,"question":"هل الذهب محرم كما يقول الشيخ الألباني في كتابه عنوان آداب الزفاف، وأيضا في الحج يقول: إن مناسك الحج واحد، وهو التمتع؟","title":"الرد على القول بتحريم الذهب للنساء وأن الحج تمتع فقط","answer":"الجواب: لا، هذا غلط، مباح للحديث، مباح للأنثى، حكى عليه الإجماع، جمع من أهل العلم كالبيهقي، والنووي، والجصاص، وجماعة، وما يروى من بعض الأحاديث الموهمة في التحريم؛ فهي منسوخة، فالذهب حل للنساء، كالحرير، ومحرم على الذكور. وكذلك مسألة الحج أنساك الحج ثلاثة: القران، والتمتع، وإفراد الحج، لكن التمتع أفضل، وأما إفراد الحج، والقران فهو جائز، وإنما الرسول ﷺ أمر الصحابة أن يحلوا لحكمة ظاهرة، أن يحلوا، ويجعلوها عمرة؛ لأن أهل الجاهلية كانوا ينكرون العمرة في أشهر الحج، ويرونها من أفجر الفجور، وأمرهم النبي أن يحلوا، ويجعلوها عمرة وقال: لولا أني أهديت لأحللت معكم؛ ليبين للناس فضل العمرة، ولم ينسخ الحج -عليه الصلاة والسلام- فالحج باق، والقران باق، ولهذا فعله الصحابة بعده، وهم أعلم الناس به، أفرد الصديق، وأفرد عمر، وأفرد عثمان -رضي الله عنهم وأرضاهم- وقرن عليّ بين الحج، والعمرة في عهد عثمان، وهكذا فعل الصحابة  لكن التمتع أفضل.  أما القول بأن الحج منسوخ، ولا يصح من النسك إلا التمتع فهذا غلط لا وجه له يخالف إجماع المسلمين، قد أجمع العلماء جميعاً على أن الأنساك ثلاثة: القران، والتمتع، وإفراد الحج عند جميع أهل العلم، فمن زعم أن الحج نسخ، وأنه لم يبق؛ فهذا غلط.","link":"https://binbaz.org.sa/fatwas/1940/الرد-على-القول-بتحريم-الذهب-للنساء-وان-الحج-تمتع-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_726.mp3","categories":["مسائل متفرقة في الحج والعمرة","اللباس والزينة","قضايا المرأة"]},{"id":6703,"question":"حصل في يوم عرفة، وفي مسجد عرنة أن يقوم أحد الأشخاص بالتلبية بمكبرات الصوت، ثم يلبي الناس جميعهم خلفه، واستمر هذا الفعل عدة مرات، السؤال هل هذا جائز أن يلبي؟ وإذا لم يكن جائزًا، نرجو التنبيه على ذلك مستقبلًا؟","title":"حكم التلبية بمكبرات الصوت","answer":"الجواب: التلبية مشروعة للجميع، كل يلبي على حدته، أما كونه يلبي بالمكبر ليذكر الناس من باب التذكير، والترجيع، لا من باب التكبير الجماعي، ولا التلبية الجماعية، فالتنبيه بالمكبر عند غفلة الناس ليسمعوا لا مانع في هذا، أما يكون تلبية جماعية بأصوات مجتمعة فلا.","link":"https://binbaz.org.sa/fatwas/2576/حكم-التلبية-بمكبرات-الصوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1071.mp3","categories":["اللباس والزينة","مسائل متفرقة في الحج والعمرة","ردود وتعقيبات"]},{"id":7159,"question":"ما الحكمة في أن المرأة تكشف وجهها وكفيها أثناء أداء مناسك الحج؟","title":"حكم كشف المرأة وجهها وكفيها أثناء الحج","answer":"الجواب:\n\nليس لها ذلك، بل عليها أن تستر وجهها وكفيها حتى في الحج، هي لا تنتقب النقاب المعروف -البرقع الذي يعرفه البادية- ولكن تغطي وجهها بغير ذلك، الرسول ﷺ نهى عن البرقع، ولم ينهها عن تغطية وجهها، بل نهاها عن البرقع، وعن القفازين في الحج.\n\nفالمعنى: أن تستر وجهها بغير ذلك، كالخمار والجلباب، كما قالت عائشة -رضي الله عنها-: كان إذا دنا منهن الرجال؛ سدلت إحدانا خمارها على وجهها، أو قالت: جلبابها على وجهها، وإذا بعدوا كشفنا، وهكذا القفازان، وهما دسان يجعلان على اليدين، غشاء لليدين لا تلبسهما المحرمة، ولكن تغطي يديها بجلبابها، بعباءتها بغير ذلك، كالرجل لا يلبس القميص، ويغطي بدنه بالإزار، وبالرداء، ونحوه، والحمد لله، فالشيء المحرم لا يفعل.\n\nفالرجل لا يلبس القميص ولا يغطي رأسه بالإحرام، ولكن يغطي بدنه بالإزار، ويغطي بدنه بالرداء، ويغطي يديه بالرداء لا بأس، والمرأة كذلك تلبس القميص، وتغطي رأسها، لكن لا تغطي وجهها بالنقاب، ولا تغطي يديها بالقفازين، ولكن تغطي وجهها بالجلباب، بالخمار عند وجود الرجال، وتغطي يديها بخمارها، أو بعباءتها، أو بجلبابها، هذا فرق بين الأمرين.\n\nالسؤال: هذا البرقع يا شيخ، جزاك الله خيرًا؟\n\nالجواب: البرقع هو النقاب، لا يجوز لبسه للمحرمة.\n\nالسؤال: هذا البرقع واسع...؟\n\nالجواب: لا تلبسه المحرمة مطلقًا، المحرمة لا تلبس البرقع، ولكن تغطي وجهها بغير ذلك، أما غير المحرمة إذا لبسته للحاجة؛ فإنه يكون بقدر العينين فقط، أو إحدى العينين فقط، من دون زيادة.","link":"https://binbaz.org.sa/fatwas/3175/حكم-كشف-المراة-وجهها-وكفيها-اثناء-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1533.mp3","categories":["مسائل متفرقة في الحج والعمرة","اللباس والزينة","قضايا المرأة"]},{"id":7546,"question":"هذه الرسالة من الطائف (س. م. ح. أو خ) يقول: قدمت إلى مكة ولم آخذ عمرة؛ لأنني أخذت عمرة في هذه السنة أكثر من مرتين، ولكني أتيت إلى البيت وطفت به ثم خرجت من مكة وعدت إليها في أقل من أسبوع، وبت فيها، ثم خرجت منها ولم أطف بالبيت، علماً أن طوافي في الزيارة الأولى كان واحد بنية الزيارة، وطوف الوداع، وإنني لم أطف هذه المرة؛ لأني في نيتي أن أعود إلى مكة مرة أخرى في نفس الأسبوع، أفيدونا وفقكم الله؟","title":"دخول مكة دون قصد العمرة","answer":"الجواب: العمرة مثل الحج، إنما تجب مرة في العمر، العمرة كالحج، إنما تجب على المكلف مرة في العمر، فإذا اعتمر مرة في العمر كفاه ذلك، وصارت العمرة الباقية كلها سنة، كلها نافلة، فإذا أراد المجيء إلى مكة لزيارة أحد، أو تجارة، أو حاجة أخرى فهو مخير، إن شاء أحرم من الميقات إذا مر عليه، كالذي يأتي من الطائف يحرم من ميقات الطائف، أو يأتي من نجد يحرم من ميقات نجد، أو من المدينة يحرم من ميقات المدينة، إن أحب ذلك فهو أفضل، وإن لم يحرم فلا حرج عليه؛ لأنه ما جاء للعمرة إنما جاء لحاجات أخرى، فإن شاء أحرم ونوى العمرة وأدى مناسكها؛ طواف وسعي وتقصير، وإن لم يرد العمرة بأن أراد الدخول بدون إحرام؛ لأنه جاء للتجارة، أو لزيارة بعض الأقارب فلا حرج عليه، لكن متى نوى العمرة فلابد من إحرام ما دام قد أراد العمرة فليس له أن يتجاوز الميقات إلا بإحرام، فإذا أحرم يؤدي مناسك العمرة من الطواف والسعي والحلق أو التقصير، أما إذا دخل بدون نية العمرة فهو مخير إن شاء أتى البيت وطاف، وإن شاء ترك، إن طاف فلا بأس، وإن ترك فلا بأس. نعم.\nوليس للعمرة حد محدود، لو اعتمر مرتين في الشهر، أو ثلاث، أو مرتين في السنة، أو عشر مرات في السنة، كله ليس فيها تحديد، ليس للعمرة حد محدود، أما قول بعض العامة: إنها لابد أن يكون بين العمرتين أربعين يوم، هذا لا أصل له، ليس لهذا حد محدود. نعم.\nالمقدم: طيب بالنسبة لطواف الوداع، هل هو لمن قدم للحج أو العمرة، أو لمن قدم إلى مكة ولو لم ينو نسك الحج والعمرة؟\nالشيخ: فيه خلاف بين العلماء، والأرجح أنه للحاج بس فقط، الأرجح أنه يجب على الحاج فقط، وأما من دخل مكة للتجارة وغيره فليس عليه طواف، كذلك المعتمر لا يجب عليه الطواف لكن لو طاف يكون أفضل، وقد حكى أبو عمر ابن عبد البر الإجماع على أنه لا وداع على المعتمر، لكن إذا ودع خروجاً من الخلاف فهو أحسن وأولى. نعم.","link":"https://binbaz.org.sa/fatwas/4532/دخول-مكة-دون-قصد-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_012/01205.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":7556,"question":"سماحة الشيخ! هذه رسالة وردتنا من جمهورية مصر العربية من أحمد أمين جمعة جمهورية مصر -الزقازيق- يقول في رسالته هذه: السادة أصحاب الفضيلة العلماء في برنامج نور على الدرب! لقد حججت مرتين، واعتمرت أربع مرات، وهذا العام حججت لوالدتي التي لم تستطع أداء المناسك، وأيضاً أخي الذي حج لوالدي الذي لم يستطع أداء المناسك، ونظراً لكبر سنهما فقد نويت عند الإحرام بالحج متمتعاً، وبعد أن وصلت إلى الأراضي الطاهرة قمت بطواف القدوم وطواف السعي، ولم أقصر من شعري، ولم أتحلل إلا بعد رمي الجمرة الأولى، ولم أنحر، ولم أسع مرة أخرى غير طواف الإفاضة وطواف الوداع، فهل يجوز ذلك؟ وهل يحتسب حجة فقط، أم ماذا؟ وما هو حكم الدين في ذلك؟ وهل لي حسنات أجزى بها؟ أفيدوني جزاكم الله الكريم خير الجزاء؟","title":"حكم من تمتع بالعمرة إلى الحج وعمل ما يعمله القارن","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالذي يظهر من سؤال السائل أنه أراد التمتع بالعمرة إلى الحج، ولكنه ما صرح بعمرة، أحرم متمتعاً، فإذا كان أراد بقصده متمتعاً بالعمرة إلى الحج فالقران يسمى تمتعاً، وهذا عمل القارن، كونه طاف وسعى وبقي على إحرامه، هذا عمل القارن، ثم طاف بعد ذلك ولم يسع يجزئ السعي الأول عن السعي بعد الحج، إذا كان نوى أن يؤدي حج وعمرة جميعاً فقط، ولم يقصد أنه يتحلل بعد السعي عند قدومه مكة، إنما أراد متمتعاً بالعمرة إلى الحج يعني: أن يجمع بينهما وأن يقرن بينهما، فهو قد طاف وسعى، ثم طاف بعد الحج، وطوافه للوداع هذا يكفي، لكن عليه هدي، عليه يرسل من يذبح عنه هدياً في مكة؛ لأن القارن مثل من أحل بالعمرة، سواء سواء، فعليه هدي يذبح في مكة، أما إن كان أراد بقوله متمتعاً؛ يريد متمتعاً بالحج لا بالعمرة، وأن قصده حج مفرد، هذا ليس عليه هدي، طوافه وسعيه كافي الأول، وطواف الإفاضة الذي فعله بعد ذلك يكفيه، وطواف الوداع كذلك وليس عليه سعي آخر، وهكذا إذا كان أراد الحج والعمرة جميعاً ليس عليه إلا سعي واحد وهو السعي الأول الذي فعله يكفيه، لكن إذا كان أراد العمرة وهو يعرفها ويقصدها فإن عليه الهدي، عليه أن يأتي فيذبح بمكة أو يوكل ثقة من الثقات فيذبحه في مكة عن قرانه، ويكون بذلك قد أدى الواجب وهو واجب هدي التمتع، وليس عليه سوى ذلك، والله أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/4560/حكم-من-تمتع-بالعمرة-الى-الحج-وعمل-ما-يعمله-القارن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_014/01401.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":7847,"question":"أيضاً تقول: في سنة ماضية أحرمت بالحج مفردة، ثم جاءتني العادة الشهرية ووصلت إلى مكة، وبقيت بها ولم أطف، ويقال: إن تحية المسجد هو الطواف بالبيت، ومعلوم لدينا أن جميع الحرم يعتبر من المسجد، فهل علي شيء في ذلك أم لا؟","title":"حكم من أحرمت ثم أتتها الدورة الشهرية","answer":"الجواب: إذا أحرمت المرأة بالحج أو بالعمرة ثم نزل بها الحيض -عادة النساء- فإنها تبقى على إحرامها، يعني لا تطوف ولا تطيب، ولا تأخذ شعراً ولا ظفراً، هذا معنى بقى على إحرامها، يعني تبقى لها حكم الإحرام، لكن لا بأس أن تغير ثيابها، الثياب لا بأس تغير ثيابها، تغير سراويلها تغير ملابسها الأخرى لا بأس، حتى ولو كان ما حاضت تغيير الثياب لا بأس به؛ لأن بعض الناس قد يظن أن القول بأنها تبقى على إحرامها معناه أنها ما تغير الثياب، ويظن أن المراد بالإحرام الثياب لا، المراد أنها تبقى على حكم الإحرام، يعني بحيث لا تغطي وجهها بالنقاب، لا تلبس القفازين، لا تطيب، لا تقلم أظفارها، لا تحل لزوجها، هذا معنى بقائها على الإحرام، أما الملابس فلا بأس أن تغير الملابس، والمسجد الحرام لا تدخله، اللهم إلا مارة لحاجة تمر من باب إلى باب لحاجة مع التحفظ لا بأس، ولكن لا تجلس فيه ولا تطوف حتى تطهر، فإذا طهرت اغتسلت الغسل الشرعي وتوضأت الوضوء الشرعي، ثم تأتي فتطوف وتسعى لحجها إن كان في الحج، وإن كان لعمرة تطوف وتسعى لعمرتها وتقصر وتتم عمرتها هذا إن كان عمرة، وإن كان حج تبقى حتى تطهر، فإن طهرت قبل الحج يوم الثامن وإلا السابع وإلا السادس من ذي الحجة أو قبل ذلك، إذا طهرت تذهب إلى البيت وتطوف وتسعى وتقصر .... العمرة، هذا هو الأفضل أن تجعل العمرة بدل الحج، ثم تحرم بالحج يوم الثامن مع الناس فتكون متمتعة كما أمر النبي أصحابه بذلك عليه الصلاة والسلام، وإن كانت لم تطهر إلا في عرفات أو في يوم العيد فإنها إذا طهرت تغتسل وتنوي طهارتها ثم تطوف وتسعى لحجها، أما الرمي والحلق والتقصير ونحوه هذا لا بأس وإن كانت حائضة تفعل كل شيء إلا الطواف، وقد وقع هذا لـعائشة رضي الله عنها لما وصلت إلى مكة لما دنت من مكة نزل بها الحيض، وكانت قد أحرمت بالعمرة، فقال لها النبي ﷺ: دعي العمرة وأحرمي بالحج لأنه جاء الحج وهي على حيضها، فلبت بالحج مع عمرتها، فلما جاء يوم النحر واغتسلت طافت وسعت لحجها وعمرتها جميعاً، ورمت الجمرة وقصرت من رأسها وتم حلها، ثم طلبت من النبي عمرة أخرى فأمرها عليه الصلاة والسلام من التنعيم من الجعرانة .... من التنعيم ... مسجد عائشة المعروف، يعني أمرها من التنعيم عمرة جديدة مفردة مستحبة غير واجبة، وإلا فعمرتها الأولى مع حجها كافيان، فالتي دخلت مكة مثلاً في وقتنا هذا للعمرة في رمضان أو في غيره وحاضت في الطريق أو بعد وصولها مكة قبل أن تطوف تبقى على إحرامها، تبقى يعني في حكم الإحرام، لا تطيب لا تقلم أظفارها، لا تقص شعراً، لا يأتيها زوجها حتى تطهر، فإذا طهرت اغتسلت وتوضأت الوضوء الشرعي وطافت وسعت وقصرت وحلت لعمرتها، هذا هو المشروع وهذا هو الواجب عليها، أما الملابس فلها تغير ملابس، الملابس لا بأس كونها تغير إزار إلى إزار، سراويل إلى سراويل، قميص إلى قميص ما في بأس، تغير ما شاءت من الملابس، أو دسوس الشراب في رجليها تغير ما شاءت لا بأس، فلا ينبغي أن يظن إذا قيل تبقى على إحرامها أن المقصود الثياب لا، ليس المقصود الثياب، المقصود الأحكام، أما الملابس فللرجل أن يغير وللمرأة أن تغير ملابس، كل واحد له أن يغير حتى ولو كانت غير حائض، ولو كانت طاهرة، لما وصلت مكة وأرادت أن تغير لا بأس أن تغير ملابسها وهي محرمة لا بأس أو الرجل لما وصل أراد أن يغير الفوطة اللي عليه بفوطة أخرى، أو أصابها شيء من شاهي أو قهوة، أو أصابها شيء فحب أن يغيرها فلا بأس، المقصود له أن يغير مطلقاً ولو ما أصابها شيء، والمرأة لها تغير ملابسها ولو ما أصابها شيء، هذا ما له تعلق بالإحرام لا بأس، إنما المقصود إذا قيل: أن الرجل يبقى على إحرامه، أو قيل: إن المرأة تبقى على إحرامها فالمعنى في حكم الإحرام، يعني يبقى كل منهما في حكم الإحرام ليس له أن يخالف حكم الإحرام لا بقص أظفار، ولا بقص شعر، ولا بطيب، ولا بتغطية رأس الرجل، أو لبس المخيط، ولا أن تلبس النقاب المرأة على وجهها، أو تلبس قفازين في يديها، كل هذا باقي حتى تحل من إحرامها هذا المراد، فينبغي أن يعلم، وأرجو من المستمعات أن يبلغن هذا لغيرهن، وهكذا المستمعون أرجو أن يبلغوا هذا؛ لأن هذا يشكل على كثير من الناس، إذا قيل: يبقى على إحرامه ما هو معناه الملابس المعنى الأحكام، أما الملابس فللرجل أن يغير والمرأة لها أن تغير ملابسها ولو كانت لم تطف ولم تسع، وهكذا الرجل قبل أن يطوف ويسعى له أن يغير ملابسه، فالمراد بقول العلماء يبقى على إحرامه وتبقى على إحرامها مرادهم بهذا أن الأحكام تبقى، يعني لا يتطيب المحرم، لا يقص أظفاره، لا يقلم شعره، لا يحل له أن يأتي زوجته، لا يحل لها أن تمكن زوجها منها وهي محرمة حتى تطهر من حيضها أو نفاسها ثم تطوف وتسعى، هذا المعنى، نسأل الله للجميع التوفيق. نعم.\nالمقدم: شكراً سماحة الشيخ عبد العزيز .","link":"https://binbaz.org.sa/fatwas/5255/حكم-من-احرمت-ثم-اتتها-الدورة-الشهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_054/05407.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":7937,"question":"سؤاله الثاني يقول: أنا قاصد العمل مع الحج، وصار موسم الحج وذهبت إلى الحج، وهل ذهب عني الفرض؛ لأنه جاء للعمل لكنه حج مع العمل، يقول: علماً أن بعض الناس يقول: لا يجوز الحج إلا عندما نأتي من سوريا، أرجو توضيح ذلك ولكم الشكر والدعاء من الفقير إلى الله: صالح سعيد سويد من سوريا.","title":"حكم من قصد مكة لعمل ثم نوى الحج أو العمرة","answer":"الجواب: لا حرج في ذلك، سواء حج من بلاده قاصداً أو جاء للعمل في المدينة أو مكة أو غيرهما ثم لما حضر الحج توجه للحج، كل هذا بحمد الله كافي، متى حضر الحج وحج مع المسلمين فإنه يكفيه ولو كان جاء من بلاده لغير الحج، مثلاً جاء من سوريا أو من مصر أو من المغرب أو من المشرق، جاء للعمل أو للتجارة، فصادف وقت الحج، فأحرم من الميقات وصلى وحج مع الناس فإنه يجزئه بحمد الله بغير خلاف نعلمه بين أهل العلم، بل هذا محل وفاق من أهل العلم، ولو كان في مكة نفسها، لو قدم إلى مكة للعمل أو للتجارة أو لزيارة بعض أقاربه، ما قصد حجاً ولا عمرة، ثم بدا له فاعتمر من الحل من التنعيم أو غيره كالجعرانة، ثم جاء الحج فحج مع الناس من مكة، أحرم من مكة بالحج أجزأه ذلك، بغير خلاف نعلمه بين أهل العلم.\nالمقدم: شكراً سماحة الشيخ عبد العزيز .","link":"https://binbaz.org.sa/fatwas/5461/حكم-من-قصد-مكة-لعمل-ثم-نوى-الحج-او-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_066/06608.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":8113,"question":"هو له عدة أسئلة ولكن جاء الجواب أثناء الإجابة على سؤاله الأول، لكن سؤاله الخامس هو الذي يقع فيه لبس على السائل عبد الله علي سليمان الأسمري يقول: حاج صلى الظهر مفرداً في عرفات يوم التروية، وصلى العصر أيضاً مفرد وصلى المغرب مفرداً، وصلى العشاء مفرداً، فما حكمه أفيدونا جزاكم الله عنا خيراً؟","title":"حكم من صلى يوم التروية في غير جماعة","answer":"الجواب: هو يرى أنه صلى مفرداً يعني، ما معه أحد ما صلى في الجماعة، هذا الظاهر ولا حرج، يعني: صلاته صحيحة لكن أساء وأثم في عدم فعله الصلاة مع الجماعة، والصلاة صحيحة إن شاء الله، لكنه عليه التوبة إلى الله؛ لأنه ترك الجماعة والجماعة واجبة، صلاة الجماعة أمر واجب، والصلاة صحيحة والحج ليس فيه شيء، إنما عليه التوبة إلى الله ، لأن الواجب على الحاج أن يصلي مع الجماعة، الجماعة التي عنده في منزلة، أو الجماعات الآخرين، أو في مسجد الخيف إن كان في منى، المقصود أنه يتحرى الجماعة، يلتمس الجماعة ويصلي مع الجماعة ولا يصلي وحده.","link":"https://binbaz.org.sa/fatwas/5909/حكم-من-صلى-يوم-التروية-في-غير-جماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_087/08705.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":8208,"question":"رسالة وصلت إلى البرنامج من الأخ: أحمد صالح إدريس سوداني يعمل في المملكة، يقول: نويت العمل في المملكة، لكن الخروج من السودان لا يتم إلا عن طريق الحج، فحضرت وحجيت وبقيت أطلب العمل حتى الآن، ما حكم الحج والحالة هذه؟","title":"حكم السفر بنية الحج والعمل","answer":"الجواب: لا بأس والحمد لله، نويت الحج ولو كان لك نية أخرى، فإذا خرج الإنسان من بلده إلى الحج ولقصد آخر ؛ للتجارة، أو للعمل، أو لزيارة الأقارب، فالأمر في هذا واسع والحمد لله، حجك صحيح، ونسأل الله أن يسهل لك العمل النافع المفيد المباح.\nالمقدم: لكن هذا يصوره أخونا في صورة احتيال سماحة الشيخ؟\nالشيخ: جعله طريقاً ما في بأس، جعله طريقاً للعمل لا بأس، كأن يجعله طريقاً للتجارة، هو ملزوم يريد التجارة، ولكن لا طريق إلا الحج، فالحج يؤدي المناسك وليتجر، صرح العلماء بهذا وأنه لا حرج المكاري، والتاجر وغيرهم. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6022/حكم-السفر-بنية-الحج-والعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09508.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":8710,"question":"شيخ عبدالعزيز نستكمل مع مطلع هذه الحلقة القضايا التي طرحت من قبل الأخ (م. ع. ن. ز) من جمهورية مصر العربية، في هذه الحلقة يسأل ويقول: بعض الحجاج لا يبالي بحجه، فهو لا يسأل عما أشكل عليه أو أنه يسأل عامياً أو شخصاً لا يعرف بالعلم، وتعلمون سماحتكم ما يترتب على ذلك، فبم تنصحون الناس جزاكم الله خيراً؟","title":"نصيحة للحجاج الذين لا يبالون بمناسك الحج","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن وصيتي لكل مسلم ولكل حاج أن يعنى بحجه وعباداته من صلاة وصوم وزكاة وغير ذلك، المؤمن من شأنه أن يهتم بدينه وأن يحرص على دينه حتى يؤدي ما أوجب الله عليه على بصيرة، وحتى يحذر ما حرم الله عليه على بصيرة، والحجاج جاءوا من أقطار الأرض من كل فج عميق يريدون رحمة الله وفضله وعتقه لهم من النار، ويريدون أداء ما أوجب الله عليهم من مناسك الحج والعمرة، فالواجب عليهم أن يهتموا بذلك وأن يعنوا بذلك، وأن يسألوا عما أشكل عليهم أهل العلم، وهم بحمد الله موجودون، ومن أشكل عليه سأل عنهم في المسجد الحرام والمسجد النبوي، وقد عينت الحكومة السعودية وفقها الله علماء في المسجد الحرام وفي المسجد النبوي وفي المشاعر يبصرون الناس ويعلمونهم مناسكهم ويرشدونهم إلى كل ما ينفعهم في الدنيا والآخرة، وهم يقومون بالوعظ والتذكير والتدريس والإفتاء.\nفعلى الحاج أن يسأل من وجد منهم في المسجد الحرام في المشاعر في المسجد النبوي وهكذا يسأل من يعرف من العلماء من جماعته من رفقته من غيرهم، من عرف من علماء الشريعة المعروفين بالاستقامة والغيرة لله والعلم بشريعته يسأله من أي جنس كان من الشام من العراق من مصر من أفريقيا من أي مكان، ما دام يعرفه بالخير ويعرفه بالعلم والفضل والغيرة لله والبصيرة في دينه حتى يفقهه حتى يعلمه ما يحتاج إليه في حجه وعمرته وصلاته وسفره وإقامته وغير ذلك.\nثبت عن رسول الله عليه الصلاة والسلام أنه قال: من يرد الله به خيراً يفقهه في الدين متفق على صحته، فهذا يدلنا على أن من علامات الخير ومن علامات التوفيق للعبد أن يفقه في دين الله وأن يتبصر في دين الله، كما يدل على أن من علامات الخذلان وعدم التوفيق الجهل بالدين والإعراض عن الدين والغفلة.\nفعليك يا أخي أيها الحاج وعليك أيها الأخت في الله الحاجة عليكما جميعاً العناية بالحج والعناية بجميع أمور الدين، في مكة وفي المدينة وفي بلادكم وفي كل مكان.\nفالواجب على المكلف من الرجال والنساء العناية والتبصر في الدين، لماذا؟ لأننا مخلوقون لنعبد الله، يقول الله سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] والله أرسل الرسل لهذا الأمر؛ ليبصروا الناس ويعلموهم وعلى رأسهم نبينا وإمامنا وسيدنا محمد بن عبد الله عليه من ربه أفضل الصلاة والتسليم، فهو أفضل الرسل وهو إمامهم وهو خاتمهم وهو نصيبنا منهم عليه الصلاة والسلام، فالواجب علينا جميعاً أن نتعلم ديننا من كتاب ربنا ومن سنة نبينا عليه الصلاة والسلام حتى نعلم العبادة التي خلقنا لها، ما هي العبادة التي خلقنا لها، نتعلمها من كلام ربنا ومن كلام رسوله، فما أمر الله به ورسوله فهو العبادة، وما نهى عنه الله ورسوله فهو المنكر الذي يترك، والطريق إلى هذا العلماء، العلماء الشرعيون، العلماء الفقهاء بدين الله المعروفون بالخير والاستقامة، هم الواسطة بين العامة وبين كتاب الله وسنة رسوله عليه الصلاة والسلام، هم الذين يعلمون الناس دينهم، فمن كان عنده علم رجع إلى كتاب الله وسنة رسوله عليه الصلاة والسلام وتبصر منهما وعلم الناس، ومن لم يكن له علم ... عامة المسلمين من الحجاج وغيرهم يسألوا أهل العلم، والله يقول سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43].\nفوصيتي للحجاج جميعاً من الرجال والنساء أن يتقوا الله وأن يحرصوا غاية الحرص على إكمال حجهم وعلى العناية به، وعلى كل ما أوجب الله عليهم من صلاة وصوم وحق الزوج وحق الزوجة وحق الأقارب وحق الوالدين وحق الجار إلى غير ذلك، المؤمن يتبصر في دينه والمؤمنة كذلك وبالأخص في الحج، وقت أداء الحج يخص ذلك بمزيد عناية حتى يؤدي حجه على بصيرة، والله سبحانه يقول: الْحَجُّ أَشْهُرٌ مَعْلُومَاتٌ فَمَنْ فَرَضَ فِيهِنَّ الْحَجَّ فَلا رَفَثَ وَلا فُسُوقَ وَلا جِدَالَ فِي الْحَجِّ وَمَا تَفْعَلُوا مِنْ خَيْرٍ يَعْلَمْهُ اللَّهُ وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَى وَاتَّقُونِ يَا أُوْلِي الأَلْبَابِ [البقرة:197] ويقول النبي صلى الله عليه وسلم في الحديث الصحيح: من حج فلم يرفث ولم يفسق رجع كيوم ولدته أمه يعني: رجع مغفوراً له إذا أدى الحج كما ينبغي، والرفث: الجماع ودواعيه من قبلة ومس بشهوة ونحو ذلك.\nفالحاج لا يجوز له جماع زوجته، وليس لها أن تمكنه من ذلك حتى يحل من حجه، حتى يحل التحلل الثاني الكامل؛ برمي الجمار يوم العيد وبالحلق أو التقصير وبالطواف والسعي، هذا هو التحلل الكامل، وبعده يحل للرجل جماع أهله، وفي العمرة ليس له جماعها ولا وسائل ذلك من القبلة والملامسة بشهوة ليس له ذلك حتى يطوف كل منهما وحتى يسعى كل منهما وحتى يحلق الرجل أو يقصر وحتى تقصر المرأة لأنه ليس لها إلا التقصير، فإذا طاف الرجل وسعى وحلق أو قصر حل من عمرته، وإذا طافت وسعت وقصرت من رأسها حلت من عمرتها فبعد ذلك يحل لهما الجماع الذي أباح الله.\nومن الرفث -مثلما تقدم- دواعي الجماع كونه يلمسها بشهوة أو يداعبها المداعبة التي تجر إلى الجماع هذا محرم؛ لأنه من الرفث. والفسوق: المعاصي جميعها، كل المعاصي تسمى فسوق؛ كالسب والشتم للناس وضربهم وإيذائهم والغيبة والنميمة والسرقة؛ سرقة أموال الناس أو نهبها، كل هذا من الفسوق، فيجب على الحاج أن يحذر ذلك، وهكذا غير الحاج يجب الحذر من هذه المعاصي، ولكن الحاج بصفة خاصة يجب أن يحذر ذلك فلا يؤذي أحداً لا عند الطواف ولا في السعي ولا في أي مكان، لا بيده ولا برجله ولا بكلامه، ولا يأخذ مال أحد إلا بحق، ولا يغتب الناس، ولا ينم عن الناس، ولا يشهد الزور، ولا يكذب، ولا يفعل شيئاً مما حرم الله حتى يكمل حجه وحتى يتممه، وحتى يرجع مغفوراً له بإذن الله، والجدال معناه: المراء في الدين بغير حق وَلا جِدَالَ فِي الْحَجِّ [البقرة:197] يعني: لا مراء في غير الحق كونه يجادل بالباطل مع إخوانه أو مع آخرين غير جماعته لا يجادل، أما بيان الحق بالدليل وبالتي هي أحسن فهذا لا بأس به؛ لأن الله قال في كتابه العظيم: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125].\nفالجدال بالتي هي أحسن في بيان الحق بيان مشاعر الحج بيان ما أشكل على الناس لإزالة الشبهة هذا لا بأس، أما الجدال لإظهار جودته أو لإظهار فهمه أو ليغلب الناس أو لشيء من الأغراض الأخرى ليس لقصد الخير فهذا هو المذموم، وهو الجدال الذي نهى الله عنه، أما الجدال بالتي هي أحسن في بيان الحق وإرشاد الجاهل وتعليمه وإزالة الشبهة وكشفها؛ فهذا مأمور به وليس داخلاً في النهي. نسأل الله للجميع التوفيق والهداية. نعم.","link":"https://binbaz.org.sa/fatwas/6860/نصيحة-للحجاج-الذين-لا-يبالون-بمناسك-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_160/16001.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":8714,"question":"أحد المهتمين بهذا البرنامج سماحة الشيخ يسأل ويقول: لخصوا لنا الطريق الذي سار عليه النبي ﷺ في حجه؟","title":"صفة حج النبي عليه الصلاة والسلام","answer":"الجواب: هذا معناه: بيان حجه ﷺ، وعمدة المؤمنين وعمدة الفقهاء في كل مذهب من المذاهب المعروفة هو عمدتهم حج النبي عليه الصلاة والسلام في بيان أحكام الحج؛ لأنه ﷺ حج وقال: خذوا عني مناسككم، فالمسلمون اعتمدوا في بيان أعمال الحج وسننه وما ينهى عنه؛ اعتمدوا على حجته ﷺ حجة الوداع، وهي حجة واحدة لم يحج بعدما هاجر سوى حجة واحدة، وهي الحجة الأخيرة التي حجها عام عشر ولم يعش بعدها إلا قليلاً.. قريباً من ثلاثة أشهر، قريبًا من ثمانين يومًا تزيد قليلًا، ثم توفي عليه الصلاة والسلام ونقله الله إلى الرفيق الأعلى عليه الصلاة والسلام، وقيل لها: حجة الوداع؛ لأنه ودع الناس فيها وقال: خذوا عني مناسككم فلعلي لا ألقاكم بعد عامي هذا.\nفهو ﷺ خرج من المدينة لخمس بقيت من ذي القعدة عام عشر من الهجرة ونزل ذا الحليفة -ميقات أهل المدينة- يوم السبت بعد صلاة الظهر، صلى بالناس الظهر في المدينة وذكرهم ووعظهم وعلمهم كيفية مناسك الحج، ثم ارتحل فنزل في ذي الحليفة بالناس وصلى فيها العصر ركعتين والمغرب ثلاثاً والعشاء ركعتين، وصلى فيها الفجر يوم الأحد، وصلى فيها الظهر يوم الأحد ركعتين حتى تلاحق الناس، ثم توجه من ذي الحليفة بعد الظهر أحرم بعدما صلى الظهر عليه الصلاة والسلام، أحرم بالحج والعمرة جميعاً قارناً، وساق معه ثلاثاً وستين بدنة، وجاء علي  من اليمن ببقية الهدي سبعة وثلاثين صار الجميع مائة بدنة، ساقها عليه الصلاة والسلام، وكان بعدما صلى الظهر وبعدما لبس الإزار والرداء وبعد الغسل والتطيب لبى بقوله اللهم لبيك عمرة وحجة عليه الصلاة والسلام، بعدما اغتسل وبعدما لبس الإزار والرداء وبعدما طيبته عائشة بطيب طيب من المسك بعد ذلك لبى بعدما ركب دابته، هذا هو السنة إذا أتى الميقات: يغتسل ويتطيب ويلبس إزاره ورداءه إن كان رجلًا، وتلبس ملابسها المرأة التي تريد والأفضل أن تكون ملابس ما تلفت النظر ملابس غير جميلة حتى لا تلفت النظر، فإذا فرغ كل منهما من ذلك ركب دابته أو السيارة ثم لبى، هذه السنة، يلبي بعدما يركب بعدما يفرغ من حاجاته كلها، كما فعله النبي ﷺ، وإذا كان بعد فريضة كان أفضل؛ لأن الرسول أحرم بعد فريضة الظهر عليه الصلاة والسلام، وإن كان في غير فريضة كالضحى فلا بأس، وذكر جمهور العلماء أنه يستحب له أن يتوضأ ويصلي ركعتين قبل أن يحرم كما صلى النبي ﷺ الظهر وأحرم بعدها، يستحب للمسلم والمسلمة عند الإحرام في غير وقت الصلاة أن يصلي ركعتين مثل الضحى فيحرم بعدهما هكذا قال الجمهور، ولا أعلم نصاً واضحاً في ذلك إلا أنهم أخذوا بفعله ﷺ لما أحرم بعد صلاة الظهر، ولأنه جاء في حديث صحيح رواه البخاري أن النبي ﷺ قال: أتاني آت من ربي فقال: صلِّ في هذا الوادي المبارك وقل: عمرة في حجة قال بعض أهل العلم: إن هذا بعمومه يدل على شرعية الصلاة عند الإحرام، ولكنه ليس بصريح لأنه يحتمل أن المراد صلوات الفريضة التي صلاها عليه الصلاة والسلام.\nفالحاصل أن الأمر في هذا واسع، إن كان بعد فريضة فهو أفضل إذا وافق فريضة فهو أفضل، وإن لم يوافق فريضة بأن كان إحرامه مثلا في الضحى فإذا توضأ وصلى ركعتين وأحرم بعدهما كان حسنًا إن شاء الله كما قال جمهور أهل العلم، ولأن الوضوء له سنة فإذا توضأ الإنسان شرع له سنة الوضوء فيلبس إزاره ورداءه ويتطيب ويستكمل كل شيء، مثلا: إن كان شاربه طويل قصه، إن كان عنده أظفار طويلة قلمها، وهكذا إبطه وهكذا عانته، هذا من باب السنة، وإذا فعل هذا في بيته قبل ذلك كفى ذلك والحمد لله. ولما كانت أسماء بنت عميس قد ولدت في ذي الحليفة ابنها محمد بن أبي بكر واستفتت النبي ﷺ أمرها أن تغتسل وتلبي وهي في نفاسها، فدل ذلك على أن المرأة إذا كانت في النفاس تلبي وهي في النفاس لا بأس، وهكذا الحائض إذا جاءت الميقات وهي حائض تلبي، تغتسل، الرسول ﷺ أمرهما بالاغتسال؛ أمر أسماء بالاغتسال وأمر عائشة لما حاضت وأرادت التلبية بالحج ثم بمكة أمرها أن تغتسل. ثم سار النبي ﷺ من ذي الحليفة ملبياً وسار معه المسلمون يلبون: (لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك لا شريك لك)، حتى وصل مكة في يوم الأحد الدائر الذي هو دور الأحد الذي أحرم فيه عليه الصلاة والسلام، وصل مكة صباح يوم الأحد ونزل بذي طوى في طرف مكة، وصلى بها الفجر وبات بها عليه الصلاة والسلام، واغتسل فيها أيضاً عند دخوله مكة فهو أفضل عند دخول مكة إذا تيسر أن يغتسل، هذا إذا تيسر وليس بلازم، ثم لما اغتسل دخل مكة ﷺ وطاف عليه الصلاة والسلام وسعى يوم الأحد عليه الصلاة والسلام رابع شهر ذي الحجة عام عشر من الهجرة، طاف وسعى وبقي على إحرامه؛ لأنه قارن ومعه الهدي فلم يحل إلا يوم النحر عليه الصلاة والسلام، وأما الصحابة الذين معه؛ فمن كان معه الهدي فعل فعله طاف وسعى وبقي على إحرامه فلم يحل إلا يوم النحر، وأما الذين ليس معهم هدي وقد لبوا بالحج أو بالحج والعمرة جميعًا فإنه ﷺ أمرهم أن يجعلوها عمرة وأن يفسخوا إحرامهم بالحج والعمرة إلى العمرة، أمرهم أن يجعلوها عمرة مفردة؛ فطافوا وسعوا وقصروا وحلوا بأمره عليه الصلاة والسلام، ومن كان معه الهدي بقي على إحرامه مع النبي ﷺ.\nهذه صفة دخوله مكة عليه الصلاة والسلام وسيره من ذي الحليفة إلى أن وصل مكة عليه الصلاة والسلام على هذا النحو، والمسلمون تابعوه بهذا عليه الصلاة والسلام واحتجوا بعمله هذا على ما ذكر من هذه الأمور لأنه ﷺ المشرع المبين للناس، ولأنه قال للناس: خذوا عني مناسككم فهذا هو المشروع كما ذكرنا عنه عليه الصلاة والسلام، ويأتي إن شاء الله بيان بقية أعماله صلى الله عليه وسلم لما توجه إلى منى وتوجه المسلمون يأتي إن شاء في حلقات أخرى. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6864/صفة-حج-النبي-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_160/16002.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":8817,"question":"مع مطلع هذه الحلقة سماحة الشيخ أرجو أن تتفضلوا بتكملة الحديث عن حجة النبي ﷺ ذلك لما في هذا الموضوع من فائدة عظيمة ولعل الكثير يتأسون بفعله عليه أفضل الصلاة والسلام؟","title":"صفة حج النبي ﷺ حتى مزدلفة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد سبق في حلقة مضت أن ذكرنا صفة حجه عليه الصلاة والسلام من حين أحرم في ذي الحليفة إلى أن خرج من منى إلى عرفات صباح اليوم التاسع، ذكرنا أنه توجه من منى إلى عرفات بعد طلوع الشمس في اليوم التاسع ملبيًا، والصحابة منهم من يلبي ومنهم من يهل فلا ينكر على واحد منهم فدل ذلك على أن الحجاج إذا توجهوا من منى إلى عرفات يشرع لهم التلبية والتهليل والتكبير، والتلبية أفضل؛ لأنها عمله عليه الصلاة والسلام.\nوقد سبق أنه ﷺ نزل في نمرة وجد فيها قبة من شعر قد ضربت فنزل بها حتى زالت الشمس فلما زالت الشمس أمر بناقته فرحلت له، ثم ركب عليه الصلاة والسلام حتى أتى بطن الوادي، يعني: وادي عرنة وخطب الناس خطبة طويلة عليه الصلاة والسلام وذكرهم بالله وبحقه، وبين فيها ما قدمنا من وضعه أمر الجاهلية ووضعه الربا ووضعه دماء الجاهلية ووصيته للمسلمين بالنساء خيرًا وبيانه حق النساء على الأزواج وحق الأزواج على النساء، وقد تقدم أيضًا أنه أوصى عليه الصلاة والسلام بكتاب الله أوصى بالقرآن الكريم وقال: إنكم لن تضلوا ما اعتصمتم به وفي الرواية الأخرى: بكتاب الله وسنته عليه الصلاة والسلام.\nوسبق أن هذا أمر معلوم، فالوصية بكتاب الله وصية بالسنة؛ لأنها الوحي الثاني؛ ولأن القرآن أمر بطاعة الله ورسوله، وطاعة الرسول هي امتثال السنة والأخذ بها والتمسك بها، ثم إنه صلى الله عليه وسلم لما فرغ من خطبته قال لهم: وأنتم تسألون عني فما أنت قائلون؟ قالوا: نشهد أنك قد بلغت وأديت ونصحت، فجعل يرفع إصبعه إلى السماء ثم ينكبها للناس ويقول: اللهم اشهد اللهم اشهد.\nفهذا يدل على أن الله سبحانه في السماء في العلو؛ ولهذا رفع يده إلى السماء وهذا قول أهل السنة والجماعة أن الله سبحانه فوق العالم فوق جميع الخلق، وأنه سبحانه فوق العرش، هذا هو الحق الذي عليه أهل السنة والجماعة ، وعلمه في كل مكان سبحانه وتعالى، كما قال : الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] وقال سبحانه: وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255] وقال سبحانه: فَالْحُكْمُ لِلَّهِ الْعَلِيِّ الْكَبِيرِ [غافر:12] وهو سبحانه فوق العرش فوق جميع الخلق، وعلمه لا يخلو منه مكان؛ ولهذا استشهد عليه الصلاة والسلام برفع إصبعيه إلى السماء عليه الصلاة والسلام.\nوفي هذا من الفوائد: شرعية خطبة الناس في عرفات وأن ولي الأمر يخطب الناس تأسيًا بالنبي عليه الصلاة والسلام، أو يخطبهم نائبه حتى يبين لهم مناسك حجهم وحتى يرشدهم إلى أصل الدين وأساسه وهو شهادة أن لا إله إلا الله، وأن محمدًا رسول الله مع بيان معنى ذلك، وأن هاتين الشهادتين هما أصل الدين وهما أصل الإسلام، ومعناهما: توحيد الله والإخلاص له، والإيمان برسوله محمد عليه الصلاة والسلام.\nويذكر لهم أيضًا ما يحتاجون إليه في هذه الخطبة من مناسك الحج ومن غير هذا من شئون الإسلام، ثم إنه ﷺ بعدما فرغ من خطبته أمر بلالًا فأذن ثم أقام فصلى الظهر ركعتين، ثم أقام فصلى العصر ركعتين جمع تقديم، وهذا هو السنة، للحجاج أن يصلوا الظهر والعصر قصرًا وجمعًا في أول وقت الظهر كما فعله المصطفى عليه الصلاة والسلام حتى يتسع الوقت للدعاء والذكر في عرفات.\nوتكون الخطبة قبل ذلك قبل الأذان وقبل الصلاة كما فعله النبي عليه الصلاة والسلام، وفيه دلالة على أنه ما صلى الجمعة ولو كان يوم جمعة، فخطب الناس قبل الأذان وذكرهم ثم أذن وصلى الظهر ركعتين بعدما أقام بلال ثم صلى العصر ركعتين أيضًا بعد الإقامة هكذا السنة، ويدل ذلك على أن المسافر لا يصلي جمعة وإنما يصلي ظهرًا، وهكذا الحجيج إذا صادف يوم الجمعة يوم عرفة فإنهم يصلون ظهرًا كما فعله المصطفى عليه الصلاة والسلام، لا يصلون جمعة، ولهذا صلى الظهر ركعتين وصلى العصر ركعتين بأذان وإقامتين بأذان واحد وإقامتين، هذا هو السنة للحجاج؛ لفعله عليه الصلاة والسلام.\nثم بعد ذلك تقدم إلى عرفات ووقف عند الصخرات أو جبل الدعاء ويسمى جبل الرحمة وجعل وجهه إلى القبلة عليه الصلاة والسلام، وجعل طريق المشاة بين يديه فلم يزل يدعو ويضرع إلى الله رافعًا يديه حتى غابت الشمس، فهذا يدل على أن هذا هو المشروع للحجاج، بعد صلاة الجمع الظهر والعصر يتوجهون إلى عرفات إن كانوا خارج عرفات وإن كانوا في عرفات استقبلوا القبلة واجتهدوا بالدعاء والذكر اقتداء به عليه الصلاة والسلام.\nوقال لهم عليه الصلاة والسلام لما وقف عند الصخرات واستقبل القبلة قال: وقفت هاهنا وعرفة كلها موقف فدل ذلك على أن جميع أجزاء عرفة كلها موقف وأن الحاج يقف في أي جزء من عرفات ويكفيه ذلك.\nوالسنة استقبال القبلة حال الدعاء والذكر سواء كان الجبل أمامه أو عن يمنيه أو شماله أو خلفه، يستقبل القبلة كما استقبلها النبي ﷺ ويدعو ويضرع إلى الله ويذكره سبحانه حتى تغيب الشمس، والسنة أن يرفع يديه كما فعل المصطفى عليه الصلاة والسلام.\nوإن أكل أو استراح فلا بأس عليه؛ فقد ثبت عنه ﷺ أن أم الفضل أرسلت إليه بقدح لبن فشرب وهو على راحلته عليه الصلاة والسلام، فعلم الناس أنه مفطر وهذا هو السنة، أن يفطر الحجيج يوم عرفة؛ لأنه أنشط لهم على العبادة؛ ولأنهم ضيوف الرحمن فناسب أن يكونوا مفطرين ينشطون للعبادة والذكر والدعاء في هذا اليوم العظيم، وقد قال عليه الصلاة والسلام: الحج عرفة هذا اليوم هو ركن الحج الأعظم الوقوف فيه، فمن فاته الوقوف في عرفة فاته الحج.\nويبتدي الوقوف بعد الزوال إلى طلوع الفجر من ليلة النحر، يعني: بقية يوم عرفة على الليلة كلها ليلة النحر، غروب الشمس إلى طلوع الفجر، كل هذا موقف، فمن وقف في عرفات بعد الزوال أو بعد غروب الشمس إلى طلوع الفجر فقد أدرك الحج، ومن لم يدرك عرفة إلا بعد طلوع الفجر فاته الحج، واختلف العلماء رحمة الله عليهم فيما قبل الزوال من يوم عرفة هل يجزئ الوقوف فيه أم لا يجزئ على قولين: الأكثرون على أن الوقوف لا يجزي إلا بعد الزوال؛ لأنه الموقف الذي فعله النبي عليه الصلاة والسلام.\nوقال آخرون: لو وقف قبل الزوال في صباح عرفة وانصرف أجزأه ذلك، ولكن عليه الدم لأنه لم يقف إلى الغروب، واحتجوا بما ثبت من حديث عروة بن مضرس أنه أتى النبي ﷺ فقال: يا رسول الله! أكللت راحلتي وأتعبت نفسي، فما تركت من جبل إلا وقفت عنده فهل لي من حج؟ فقال عليه الصلاة والسلام: من شهد صلاتها هذه بمزدلفة وقد وقف بعرفة قبل ذلك ليلًا أو نهارًا فقد تم حجه وقضى تفثه فقوله ﷺ: وقد وقف بعرفة قبل ذلك ليلًا أو نهارًا يعم ما قبل الزوال؛ ولهذا ذهب أحمد رحمه الله وجماعة إلى أن الوقوف قبل الزوال يجزئ ويدرك به الحج.\nوذهب الجمهور رحمة الله عليهم إلى أنه لا يدرك الحج إلا بالوقوف بعد الزوال، فينبغي للمؤمن أن يحتاط لدينه، وأن لا يقف إلا بعد الزوال كما وقف النبي عليه الصلاة والسلام، ثم بعدما غابت الشمس توجه عليه الصلاة والسلام إلى مزدلفة بعد غروب الشمس، فهذا هو المشروع للحجيج أن يمكثوا في عرفات ذاكرين ملبين داعين مخلصين لله خاشعين لله عز وجل، حتى تغيب الشمس، فإذا غابت انصرفوا إلى مزدلفة، وليس في يوم عرفة دعاء واجب ولا متعين بل يدعو الله بما تيسر، يذكر الله ويدعوه بما تيسر، وروي عنه ﷺ أنه قال: خير الدعاء دعاء يوم عرفة وخير ما قلت أنا والنبيون من قبلي: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير فينبغي أن يكثر من ذكر الله عز وجل؛ تسبيحه وتحميده .. تكبيره، والاستغفار والدعاء في هذا اليوم العظيم، فيسأل ربه الجنة ويستعيذ به من النار، ويسأله كل خير  ويستجير به من كل شر، فهو يوم عظيم فيه يتجلى الله لعباده كما ثبت في الصحيح عن النبي ﷺ: إن الله جل وعلا يتجلى للعباد يوم عرفة ويدنو منهم كما يشاء سبحانه فيقول: ما أراد هؤلاء؟ ويقول ﷺ: ما من يوم أكثر عتيقًا من النار من يوم عرفة، وإنه سبحانه ليدنو فيباهي بهم الملائكة فهو يوم عظيم يباهي الله فيه ملائكته بالحجيج ويدنو منهم كما يشاء  دنوًا يليق بجلاله، لا يعلم كيفيته إلا هو ، ويعتق العتقاء الكثير من النار في هذا اليوم العظيم.\nفينبغي لك -يا عبد الله- أن تجتهد في الضراعة إلى الله واستغفاره وسؤاله القبول وسؤاله العتق من النار في هذا اليوم العظيم.\nثم بعدما وصل مزدلفة صلى بها المغرب والعشاء، وكان في الطريق عليه الصلاة والسلام يحث الناس على السكينة وعدم العجلة، ويقول لهم في الطريق: السكينة السكينة، فإن البر ليس بالإيضاع يعني: ليس بالإسراع، ويلبي في طريقه عليه الصلاة والسلام، فهكذا السنة، إذا انصرف الناس من عرفات بعد الغروب أن يلبوا، ويكثروا من التلبية ولا يعجلوا لئلا يضر بعضهم بعضًا، بل بالسكينة، فإذا وجد ..... عليه الصلاة والسلام، فهكذا الناس، ينبغي أن يكون انصرافهم بالسكينة، ومن وجد سعة في بعض الأماكن فلا مانع أن يعجل تعجيلًا لا يضر غيره.\nفلما وصل ﷺ مزدلفة أمر بالأذان فأذن ثم صلى المغرب بإقامة ثلاثًا وصلى العشاء بإقامة ركعتين، يعني: صلاهما بأذان واحد وإقامتين كما فعل في عرفات عليه الصلاة والسلام وهذا هو السنة للحجيج أن يصلوا المغرب والعشاء جمعًا وقصرًا، يعني: قصرًا للعشاء، أما المغرب فإنها لا تقصر ثلاثًا دائمًا في السفر والحضر، فيصليهما بأذان واحد وإقامتين، اقتداء بنبينا عليه الصلاة والسلام.\nثم بعد ذلك استراح عليه الصلاة والسلام ونام كما ثبت من حديث جابر  حتى طلع الفجر، فلما طلع الفجر قام فصلى الفجر بأذان واحد وإقامة، صلاها بغلس، أبكر من عادته عليه الصلاة والسلام حتى يتسع الوقت للوقوف عند المشعر الحرام، وأذن للضعفاء والنساء والشيوخ بالانصراف من مزدلفة ليلًا لئلا يحطمهم الناس، وأما الأقوياء فجلسوا معه حتى صلوا الفجر ووقفوا عند المشعر ودعوا الله كثيرًا حتى أسفروا، فلما أسفر ﷺ انصرف إلى منى قبل طلوع الفجر، هكذا ينبغي للناس أن يبقوا في مزدلفة حتى يبيتوا بها ويصلوا بها الفجر، أما الضعفاء من النساء والعجائز والشيوخ الكبار والصبيان ونحوهم ومن يكون معهم فلا بأس، بل الأفضل أن ينصرفوا قبل حطمة الناس من مزدلفة إلى منى في النصف الأخير من الليل، ومن انصرف معهم من محارمهم ومن هو معهم في رحلهم فلا بأس عليه، أما القوي الذي ليس معه نساء فالأفضل له أن يبقى حتى يصلي الفجر ثم يدعو الله ويذكره كثيرًا حتى يسفر، وقد قال ﷺ لما وقف يوم مزدلفة قال: وقفت هاهنا وجمع كلها موقف يعني: مزدلفة، يقال لها: جمع، فالمعنى: أن مزدلفة كلها موقف كما أن عرفة كلها موقف، كل إنسان في مزدلفة يجلس في محله ويدعو الله ويستغفر ويضرع إليه  ويذكر الله، وليس هناك حاجة إلى أن يتقدم إلى قزح موقف النبي عليه الصلاة والسلام الجبل المعروف بل كل إنسان يدعو الله في مكانه والحمد لله.\nوكان في عرفات وفي مزدلفة يرفع يديه في الدعاء، ويلح في الدعاء عليه الصلاة والسلام، فالسنة رفع اليدين مع الإلحاح في الدعاء والإكثار من الدعاء تأسيًا به عليه الصلاة والسلام.\nومن انصرف من الأقوياء إلى منى قبل طلوع الفجر أجزأه على الصحيح لكنه فاته الفضل، فالأفضل له والكمال أن يجلس حتى يصلي الفجر وحتى يقف بعد طلوع الفجر يذكر الله ويثني عليه ويدعو إلى أن ينصرف قبل طلوع الشمس، وكان المشركون ينصرفون بعد طلوع الشمس فخالفهم النبي ﷺ وانصرف قبل طلوع الشمس بعد ما أسفر عليه الصلاة والسلام، وهذا هو المشروع لجميع الحجاج أن ينصرفوا قبل طلوع الشمس اقتداءً به عليه الصلاة والسلام.\nولعل هذا المقدار يكفي في هذه الحلقة حتى نكمل ذلك في الحلقة الأخرى إن شاء الله. نعم.\nالمقدم: جزاكم الله خيرًا، إذًا: وصل بنا الحال إلى انصرافه ﷺ من مزدلفة؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/6972/صفة-حج-النبي-ﷺ-حتى-مزدلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_163/16301.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":8821,"question":"جزاكم الله خيرًا، ما رأيكم -سماحة الشيخ- في بعض الحجاج الذين يوكلون على بقية النسك التي تؤدى في منى ويسافرون؟","title":"حكم السفر قبل انتهاء الحج وتوكيل الغير ببقية المناسك","answer":"الجواب: هذا غلط ليس له أن يسافر حتى يكمل حجه، وليس له أن يوكل إلا لعذر شرعي فإذا وكل لعذر شرعي وجب عليه الانتظار حتى يفرغ الوكيل من أداء ما عليه كالرمي.\nفالحاصل: أن سفر الإنسان قبل انتهائه من الحج أمر ممنوع لا يجوز، بل عليه أن يصبر حتى ينتهي حجه ولو أنه يوكل في بعض الأشياء، مثلًا: يعجز عن الرمي يوكل من يرمي عنه لكن لا يسافر حتى يتم الرمي كله ثم يطوف للوداع، ثم يسافر بعد ذلك وليس له أن يسافر قبل ذلك، فيقول للوكيل: يكفي، لا، لابد يصبر حتى يرمي الوكيل ثم هو بعد الرمي كله يطوف للوداع، نعم.\nالمقدم: ومن فعل ذلك ما الحكم سماحة الشيخ؟\nالشيخ: هذا فيه التفصيل: إن فعل ذلك والواجب عليه شيء من الأركان وجبت عليه العودة، أن يعود مثل سافر قبل أن يطوف طواف الإفاضة فعليه أن يرجع حتى يطوف طواف الإفاضة أو يسعى إن كان عليه سعي، أما إن كان طواف الوداع فقط عليه دم يذبح في مكة ولا يلزمه العودة. نعم.\nأما إن كان الرمي رمي الجمار فهذا فيه التفصيل:\nإن كان الوقت باقي وهو ليس له عذر وجب عليه العودة حتى يرمي بنفسه، يعني: سافر الطائف أو جدة وهو لا عذر له يرجع من الرجوع حتى يرمي في أوقات الرمي، فإن كان الوقت قد خرج، قد فات يعني: ما نبه ما تنبه إلا بعدما فاتت أيام الرمي فعليه دم يذبح في مكة عن الرمي؛ لأن الرمي لا يقضى ذهبت أيامه ذهب فعله، فلا يقضى إنما يرمى في وقته، فإذا ذهبت الأيام فإنه يسقط فيلزمه الدم يحل محله الدم، ذبيحة تذبح في مكة للفقراء بدل الرمي كله.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6976/حكم-السفر-قبل-انتهاء-الحج-وتوكيل-الغير-ببقية-المناسك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_163/16304.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":8823,"question":"هناك أناس يتباهون بسرعة العودة من الحج، توجيهكم لمثل هؤلاء لو تكرمتم سماحة الشيخ؟","title":"مشروعية التعجل بالعودة بعد الفراغ من الحج","answer":"الجواب: هذا ينبغي فيه التفصيل: إن كان هناك حاجة مصلحة إسلامية، فلا بأس لكن بعد فراغه من الحج، مثل الإنسان عنده عمل مهم، خلفه عمل مهم، هذا لا بأس أن يستعجل لمقصد شرعي، أو عنده مراجعة الأطباء أو سجناء هو المسئول عنهم، أو تعليم يفوت وقته أو ما أشبه من الحاجات المعلومة التي تقتضي السرعة، فإذا فرغ من رمي الجمار وطواف الوداع فلا بأس أن يتعجل للمصلحة الإسلامية.\nأما إذا ما هناك ضرورة فالأفضل له عدم العجلة حتى يستفيد من بقائه في مكة، والصلاة في المسجد الحرام، الطواف في الحرام، هذا خير عظيم، كل يوم يمر عليه إذا حصل له فرصة يصلي في المسجد الحرام هذا خير عظيم، أو يطوف هذا خير عظيم، ولكن الحمد لله الأمر واسع ما دام كمل الحج، فمن أحب أن يسافر فلا بأس، لكن كونه يحرص على السفر على وجه يضره، أو يضر غيره بالمزاحمات هذا ينبغي له تركه حتى يطوف بهدوء وحتى لا يضر أحدًا وحتى يتيسر له أيضًا المزيد من الطواف أو الصلوات في المسجد الحرام كل هذا خير عظيم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6978/مشروعية-التعجل-بالعودة-بعد-الفراغ-من-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_163/16305.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":8824,"question":"سماحة الشيخ! في حلقات مضت من هذا البرنامج تفضلتم بتفصيل القول في كيفية حج النبي ﷺ، ووصل بكم الحديث إلى انصراف الرسول ﷺ من مزدلفة، حبذا لو تفضلتم بتكملة الحديث عن تلكم الرحلة المباركة، جزاكم الله خيرًا؟","title":"صفة حج النبي ﷺ بعد الانصراف من مزدلفة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد سبق أن تكلمت على صفة حجه عليه الصلاة والسلام من حين خرج من المدينة إلى أن وصل إلى مكة عليه الصلاة والسلام، ثم عن رحلته من مكة إلى منى، وعن رحلته من منى إلى عرفات، وعن رحلته من عرفات بعد غروب الشمس إلى مزدلفة، وما فعله في مزدلفة عليه الصلاة والسلام.\nوسبق أنه عليه الصلاة والسلام صلى بها الفجر، ثم أتى المشعر فرقيه وجعل يدعو ويذكر الله ويهلل حتى أسفر جدًا عليه الصلاة والسلام، ورفع يديه بالدعاء، فلما أسفر انصرف إلى منى، هذا هو السنة، أن يبيت الحجيج في مزدلفة، وأن يصلوا بها الفجر وأن يدعوا الله كل في مكانه وفي منزله؛ لأنها كلها موقف، كل يدعو في مكانه ويضرع إلى الله ويسأله من فضله ويرفع يديه ويذكره كثيرًا ويدعوه كثيرًا حتى يسفر، فإذا أسفر جدًا انصرف إلى منى قبل طلوع الشمس تأسيًا بالنبي عليه الصلاة والسلام.\nوتقدم أنه أذن للضعفة من النساء والشيوخ والصبيان بأن ينصرفوا إلى منى في الليل قبل حطمة الناس، هذا هو الذي ينبغي للضعفاء أن ينصرفوا حتى يخففوا عن الناس، وحتى يسلموا هم أيضًا من حطمة الناس.\nفالنساء والشيوخ ونحو ذلك ومن يتبعهم من محارمهم ومن صاحبهم في الرحلة إلى منى في النصف الأخير من ليلة المزدلفة.\nفإذا وصلوا إلى منى باتوا بها بقية الليل، وإن رموا الجمرة فلا بأس، رموها في آخر الليل فلا بأس، وقد ثبت عن أم سلمة رضي الله عنها أنها رمت الجمرة في آخر الليل.\nوثبت عن أسماء بنت أبي بكر ما يدل على ذلك، وأن الرسول ﷺ أذن للضعف وهن النساء في ذلك، فإذا رمين ومن معهم في آخر الليل كفى ذلك، وإن أخروا رموا بعد ارتفاع الشمس فلا بأس، ولكن الأرفق بهم وبمن معهم أن يرموا في آخر الليل إذا وصلوا منى، هذا هو الأرفق بهم.\nثم يرجعون إلى منازلهم، كل يرجع إلى منزله في منى للإقامة بها لذبح الهدايا ورمي الجمار في الأيام القادمة وغير ذلك من شئون الحج.\nأما هو ﷺ فقد انتظر حتى صلى الفجر ودعا ربه بعد الصلاة وذكره، ورفع يديه وألح بالدعاء، ثم انصرف قبل طلوع الشمس عليه الصلاة والسلام، وسبق أنه صلى بها المغرب والعشاء قصرًا وجمعًا ثم نام بعد ذلك بأذان واحد وإقامتين عليه الصلاة والسلام.\nوهكذا الفجر صلاها بأذان وإقامة مع سنتها الراتبة، وصلاها بعد طلوع الفجر مبكرًا، قال ابن مسعود : إنه صلاها قبل ميقاتها يعني: قبل ميقاتها المعتاد؛ وذلك -والله أعلم- ليتسع الوقت للدعاء والذكر بعد صلاة الفجر.\nثم المشروع للمسلمين إذا وصلوا منى بعد انصرافهم من مزدلفة أن يرموا الجمرة؛ لأنه ﷺ انصرف من مزدلفة قبل طلوع الشمس ملبيًا حتى أتى الجمرة، أتاها ضحىً فرماها بسبع حصيات، يكبر مع كل حصاة ولم يقف عندها، بل رمى وانصرف عليه الصلاة والسلام، فهكذا المسلمون من الحجاج إذا وصلوا إلى منى بعد طلوع الشمس رموا بالجمرة، بدءوا بها تحية منى وليس في الصلاة عيد، ليس في منى صلاة عيد للحجاج، ليس عليهم صلاة العيد، يقوم مقامها رمي الجمار ذلك اليوم، فيرمي الجمرة بسبع حصيات، يرميها الرجل والمرأة والصغير والكبير بسبع حصيات، واحدة بعد واحدة، يكبر مع كل حصاة، يقول: (الله أكبر) مع كل حصاة، مستشعرًا عظمة الله، وطاعته سبحانه، ومستشعرًا إرغام الشيطان ودحره بهذه الحصيات التي ترجم بها مواقفه، ثم ينصرف ولا يقف؛ لأن الرسول لم يقف عليه الصلاة والسلام عند جمرة العقبة، بل رماها وانصرف عليه الصلاة والسلام، ووقف للناس يسألونه في منى بعد رميه الجمرة، فهذا يقول: يا رسول الله! أفضت إلى البيت قبل أن أرمي؟ يعني: ذهبت للطواف قبل الرمي فقال: لا حرج عليه الصلاة والسلام.\nوآخر يقول: نحرت قبل أن أرمي؟ فيقول: لا حرج وآخر يقول: حلقت قبل أن أذبح؟ فيقول: لا حرج فهذا يدل على أن أفعال الحج يوم العيد فيها توسعة، وأن الرمي والطواف والسعي والحلق أو التقصير والنحر كلها فيها سعة، والنبي ﷺ رتبها، فرمى يوم العيد ثم نحر عليه الصلاة والسلام ثم حلق رأسه ثم طيبته عائشة رضي الله عنها ثم ركب إلى البيت فطاف عليه الصلاة والسلام، هكذا الترتيب، هذا هو الأفضل، رمي فنحر فحلق أو تقصير فطواف وسعي إن كان عليه سعي، هذا هو الترتيب.\nالأول الرمي، ثم نحر الهدي، ثم حلق الرأس أو تقصيره، وبهذا تحلل التحلل الأول، يلبس المخيط يغطي رأسه إن كان رجل، والمرأة كذلك تتطيب، تكف شعرها إن شاءت، تقص أظفارها إن شاءت حلت التتحلل الأول، ولا يبقى عليهما جميعًا الرجل والمرأة إلا الجماع وما يتعلق بالجماع من النساء.\nفإذا طافا وسعيا بعد ذلك تم الحل كله، وحل للرجل الاتصال بأهله إذا طاف وسعى بعد الرمي وبعد الحلق أو التقصير، والسعي إنما يجب عليه إذا كان متمتعًا؛ لأن السعي الأول لعمرته وهذا لحجه، أو كان قارنًا أو مفردًا لكن لم يسع مع طواف القدوم، وإنما سعى مع طواف الإفاضة، وإن كان سعى مع طواف القدوم فلا سعي عليه يكفيه الطواف، الحاج المفرد والحاج القارن بين الحج والعمرة.\nوالنبي كان قارنًا عليه الصلاة والسلام، فلهذا طاف طوافًا فقط، ولم يسع؛ لأنه قد سعى مع طواف القدوم عليه الصلاة والسلام.\nوفي هذا من الفوائد: أن الإنسان قد يشق عليه تأخير الطواف، قد يشق عليه تأخير الحلق إلى أن يذبح؛ لأن الذبح مو بمتيسر، قد يتأخر لليوم الثاني، فمن رحمة الله ومن تيسير الله عز وجل ومن إحسانه إلى عباده ورحمته بهم أن فسح لهم المجال، وجعل هذا الترتيب ليس بواجب، هذا هو الصحيح الذي عليه جمهور أهل العلم، أنه له أن يبدأ بما أخره الرسول ﷺ له أن يقدمه؛ لأنه سئل عليه الصلاة والسلام: عما يقدم ويؤخر؟ فقال: لا حرج، لا حرج.\nفإذا أفاض الإنسان قبل أن يرمي، مثل: امرأة خافت من الحيض فأفاضت قبل أن ترمي قصدت مكة فلا بأس، ومثل إنسان نحر هديه صار صار النحر متيسر، والرمي ما تيسر له أن يرمي مبكر، فنحر قبل أن يرمي فلا بأس، أو حلق قبل أن يرمي، أو ذبح قبل أن يرمي كل ذلك لا بأس به والحمد لله.\nفالحاصل: أن الترتيب ليس بواجب، ولكنه أفضل يرمي ثم ينحر ثم يحلق أو يقصر ويتحلل التحلل الأول، يلبس المخيط ويغطي رأسه، ثم يذهب إلى البيت ويطوف ويسعى، هذا هو الترتيب المشروع.\nلكن..\nالمقدم: النحر لمن كان متمتعًا أو قارنًا؟\nالشيخ: أو قارنًا بس، أما الحاج المفرد فليس عليه شيء إلا أن يطوع، فمن قدم بعضها على بعض فلا حرج عليه في ذلك، كما فعله المصطفى ﷺ وكما أذن للناس عليه الصلاة والسلام في ذلك.\nثم بعد ذلك لما رمى الجمرة عليه الصلاة والسلام ونحر هديه وحلق رأسه طيبته عائشة ثم ركب إلى البيت فطاف به عليه الصلاة والسلام، وصلى بمكة الظهر عليه الصلاة والسلام.\nثم عاد من مكة وصلى بالناس الموجودين ينتظرونه صلى بهم الظهر بمنى ، فصلاها مرتين، الأولى في مكة وهي فريضة، والثانية في منى لمن بقي ينتظره، وهي نافلة له عليه الصلاة والسلام.\nوبهذا يستدل على صحة صلاة المفترض خلف المتنفل كما كان معاذ يصلي بأصحابه متنفلًا ويصلي مع النبي فريضته العشاء عليه الصلاة والسلام، يصلي العشاء مع النبي ﷺ فرضه ثم يذهب فيصلي بأصحابه فريضتهم وهي له نافلة، كل هذا جائز بحمد الله.\nثم أقام النبي ﷺ في منى الحادي عشر والثاني عشر والثالث عشر، يرمي بعد الزوال الجمار الثلاث، كل جمرة يرميها بسبع حصيات واحدة بعد واحدة، ويكبر مع كل حصاة، ويجعل الجمرة الأولى وهي التي تلي مسجد الخيف يجعلها عن يساره، ويتقدم فيسهل حتى لا يصيبه رمي الناس وحتى لا يضايق الناس فيرميها بسبع حصيات، ويقف عندها ويجعلها عن يساره فيدعو ويرفع يديه ويلح بالدعاء ويطيل الدعاء، كما فعله النبي ﷺ، فإنه رفع يديه وأكثر الدعاء عليه الصلاة والسلام، بعدما رمى الجمرة يوم الحادي عشر والثاني عشر والثالث عشر، ثم أتى الوسطى فرماها بسبع حصيات يكبر مع كل حصاة، ثم جعلها عن يمينه وأخذ ذات الشمال -أي: يساره- ووقف يدعو ورفع يديه وألح في الدعاء عليه الصلاة والسلام، فهذا هو السنة، أن الحاج يقف عند الأولى بعد رميها ويدعو، وعند الثانية بعد رميها ويدعو مستقبل القبلة، يجعل الجمرة الأولى عن يساره والوسطى عن يمينه حال الدعاء، هذا هو السنة لمن تيسر له ذلك، من لم يتيسر له ذلك فلا شيء عليه، هو سنة مؤكدة فعله المصطفى عليه الصلاة والسلام.\nأما الثالثة فكان يرميها ولا يقف عندها، رمي الجمرة العقبة يرميها يوم الحادي عشر والثاني عشر والثالث ولا يقف عندها، كما أنه لم يقف عندها يوم العيد، بل رماها وانصرف عليه الصلاة والسلام.\nثم أذن للناس بالتعجل من أراد أن يتعجل في اليوم الثاني عشر فلا بأس؛ لقول الله سبحانه: وَاذْكُرُوا اللَّهَ فِي أَيَّامٍ مَعْدُودَاتٍ فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ فَلا إِثْمَ عَلَيْهِ وَمَنْ تَأَخَّرَ فَلا إِثْمَ عَلَيْهِ [البقرة:203] من أحب أن يتعجل بعد الرمي يوم الثاني عشر فلا بأس، يرمي الجمار ثم يذهب إلى مكة لطواف الوداع، ومن أحب أن يبقى إلى اليوم الثالث عشر كما بقي النبي ﷺ فإنه بقي إلى الثالث عشر عليه الصلاة والسلام، فلما رمى الجمار يوم الثالث عشر بعد الزوال تقدم إلى الأبطح فنزل به، وصلى به الظهر والعصر والمغرب والعشاء عليه الصلاة والسلام، ثم ركب في أثناء الليل إلى مكة في آخر الليل إلى مكة لطواف الوداع، فطاف في آخر الليل طواف الوداع عليه الصلاة والسلام، وصلى بالناس الفجر وقرأ فيها بالطور.\nثم بعدما انتهى من صلاة الفجر توجه إلى المدينة عليه الصلاة والسلام، صباح يوم الأربعاء الرابع عشر من ذي الحجة عليه الصلاة والسلام.\nوبهذا انتهى الحج انتهت أعمال الحج بطواف الوداع، من انصرف في الثاني عشر ودع -إذا كان يريد السفر- ذلك اليوم، وإن أحب أن يبقى في مكة أيامًا أخر الوداع حتى يعزم على السفر، فإذا عزم على السفر طاف ثم سافر، وهكذا من أخر إلى اليوم الثالث عشر ولم يتعجل فإنه إذا فرغ من الرمي إن كان أحب أن يبقى في مكة بقي في مكة، وإن أحب السفر طاف للوداع وسافر، هكذا كما فعله النبي عليه الصلاة والسلام.\nوالرمي بعد الزوال في أيام التشريق لا قبل الزوال، لا يرمي قبل الزوال لكن .... بعد الزوال، فإن عجز أو شغل رمى بعد الغروب لهذا اليوم، يعني: كل يوم إذا لم يتيسر في النهار يرمي له بعد الغروب في ذلك اليوم الذي غابت شمسه، وهكذا اليوم الثاني عشر يرمي بعد الزوال إن تيسر وإلا فبعد الغروب.\nوهكذا اليوم الثالث عشر يرمي بعد الزوال لكن ليس فيه رمي بعد الغروب؛ لأنه انتهى الرمي، عند غروب الشمس ينتهي الرمي، فالثالث عشر يجب أن ينهيه قبل الغروب، وهذا في الغالب غير متعذر ولا متعسر؛ لأن الناس في الغالب ينصرفون في اليوم الثاني عشر، ولا يبقى إلا القليل في الثالث عشر، فلا يكون هناك صعوبة في الرمي قبل الغروب، لكن بعد الزوال.\nوفي أيام المنى يكثر من ذكر الله ومن التكبير والتهليل، قال النبي ﷺ: أيام التشريق أيام أكل وشرب وذكر الله يذبح فيها الهدايا ويأكل ويطعم كما قال سبحانه: فَكُلُوا مِنْهَا وَأَطْعِمُوا الْبَائِسَ الْفَقِيرَ [الحج:28] ويكثر من الدعاء والذكر، وقراءة القرآن في الأوقات المناسبة، تعليم الناس للخير، والدعوة إلى الخير، كل هذا مطلوب، إذا كان عنده علم.\nوفي يوم العيد كذلك إذا لم يتيسر الرمي يوم العيد رمى بعد الغروب إلى آخر الليل، ليلة الحادي عشر تابعة ليوم العيد، إذا لم يتيسر الرمي فيه فإنه يرمي بعد الغروب ويجزئه ذلك والحمد لله؛ لأن بعض الناس قد يشغل يوم العيد، قد يحصل له مانع من الرمي يوم العيد، فيرمي -على الصحيح- بعد الغروب ولا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيرًا، ونفع بعلمكم.\nالواقع سماحة الشيخ وأنتم تذكروننا بهذه الرحلة الطيبة المباركة، وهذا الأسلوب الذي اتبعه نبينا وحبيبنا وسيدنا محمد ﷺ تدعون أمة الإسلام كيفما تقتفي ذلك الأثر، وتسير على ذلكم المنهج فجزاكم الله خير الجزاء.\nالشيخ: نسأل الله أن يوفقهم لذلك، نسأل الله أن يوفق المسلمين لاتباع نبيهم ﷺ والتمسك بهديه في كل شيء، في الحج وغيره، فذلك طريق السعادة وسبب النجاة في الدنيا والآخرة، نسأل الله أن يوفقنا وإياهم لذلك.","link":"https://binbaz.org.sa/fatwas/6979/صفة-حج-النبي-ﷺ-بعد-الانصراف-من-مزدلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_164/16401.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":9054,"question":"السؤال الثالث في رسالة الأخت: صالحة محمد علي أبو حسين من مكة المكرمة تقول فيه: ماذا تفعل المرأة إذا جاءتها العادة أو الدورة الشهرية في الحج، وماذا تفعل المرأة النفساء إذا وضعت مولودها في يوم الوقوف بعرفات؟ أفيدونا أفادكم الله.","title":"ماذا تفعل المرأة إذا أصابها الحيض في الحج؟","answer":"الجواب: كلتا الحادثتين وقعت في عهد النبي ﷺ، فقد حجت معه عائشة رضي الله عنها وأصابها الحيض، يعني: الدورة الشهرية، في مكة قبل الخروج إلى منى وعرفات، فأمرها النبي ﷺ أن تغتسل للنظافة وتلبي بالحج مع العمرة، وكانت قد دخلت للعمرة فجاءها الحيض في سرف موضع قرب مكة قبل أن تطوف قبل أن تسعى، فأمرها النبي ﷺ أن تلبي بالحج، وأن تدع العمرة وتكون بهذا قارنة بين الحج والعمرة ففعلت، فلما طافت وسعت يوم العيد، قال لها النبي ﷺ: طوافك بالبيت وبين الصفا والمروة يكفيك لحجك وعمرتك فأخبرها ﷺ أن عملها هذا يكفيها للحج والعمرة، وهو الطواف والسعي؛ لأنها دخلت العمرة في الحج، كما قال النبي ﷺ: دخلت العمرة في الحج إلى يوم القيامة فهذا شأن الحائض إذا أصابها الحيض قبل أن تطوف وتسعى للعمرة، فإنها تلبي بالحج، وتدخل ... العمرة وتكون قارنة ويكون عملها واحداً تطوف لحجها وعمرتها طوافاً واحداً سبعة أشواط وتسعى سعياً واحداً سبعة أشواط، ويكفي هذا في حجها وعمرتها.\nأما لو جاءها الحيض وقد فرغت من العمرة، بأن طافت وسعت وقصرت وحلت، ثم جاءها الحيض قبل خروجها إلى منى أو في منى أو في عرفات فإنها تكمل الحج، تفعل ما يفعل الحجاج كما قال النبي ﷺ لـعائشة: افعلي ما يفعل الحاج غير أن لا تطوفي بالبيت حتى تطهري، فأمرها أن تفعل ما يفعل الحجاج، غير ألا تطوف حتى تطهر.\nفتقف مع الناس في عرفات تذكر الله  وتدعو وتقف معهم في مزدلفة، تذكر الله وتدعو، ترمي الجمار يوم العيد وهكذا الأيام بعدها، أيام التشريق وتبيت بمنى أيام منى، تفعل ما يفعله الحجاج من كل شيء إلا أنها لا تطوف، تبقى عن الطواف حتى تطهر، فإذا طهرت اغتسلت وطافت لحجها وسعت، هذا هو المشروع لمن أصيبت بالدورة الشهرية وهي الحيض، فلا يمنعها هذا الحيض إلا من الطواف، والسعي يكون بعد هذا الأفضل، يؤجل معه السعي فإذا طهرت طافت وسعت ولو بعد أيام منى، لا يضرها ذلك، أما إذا كان الحيض أصابها قبل أن تحل من العمرة فقد تقدم البيان، وأنها تلبي بالحج مع العمرة وتكون قارنة، ويكفيها الطواف والسعي للأمرين جميعاً للحج والعمرة جميعاً كما تقدم.\nأما النفساء فهي مثل الحائض، فقد أصاب ذلك أسماء بنت عميس ، فإنها ولدت في الميقات في حجة النبي ﷺ، ولدت محمد بن أبي بكر ولدها محمد بن أبي بكر الصديق ، ولدته في ذي الحليفة، فأمرها النبي ﷺ أن تغتسل يعني: للنظافة، وأن تستنفر بشيء يحفظ عنها الدم، وأن تلبي مع الناس، ففعلت رضي الله عنها وأرضاها فاغتسلت ولبت مع الناس وحجت مع الناس، لكنها لا تطوف ولا تسعى حتى تطهر كما في حق الحائض، تفعل ما يفعل الحجاج من التلبية والذكر، والوقوف بعرفة يوم التاسع، والمبيت بمزدلفة ليلة العاشرة، ورمي الجمار يوم العيد وما بعده، والمبيت بمنى أيام منى، كل هذا تفعله النفساء كالحائض وكالطاهرات، لكن يبقى عليها الطواف والسعي، فإذا طهرت من نفاسها، ولو بعد أيام بمنى بأيام، تطوف وتسعى لحجها والحمد لله، كما فعلت أسماء بنت عميس بأمر النبي عليه الصلاة والسلام. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7206/ماذا-تفعل-المراة-اذا-اصابها-الحيض-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_224/22405.mp3","categories":["مسائل متفرقة في الحج والعمرة","الحيض والنفاس","قضايا المرأة"]},{"id":9089,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع الحاج أحمد الشريف محمد إسماعيل من الأردن -عمان، يقول فيها: قرأت في بعض الكتب: أنه يجوز للحاج الاتجار خلال أيام الحج، ودليل ذلك قول الله : لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلًا مِنْ رَبِّكُمْ [البقرة:198] فأرجو من فضيلتكم توضيح هذا الأمر؟ وما الحكم في ذلك جزاكم الله خير الجزاء؟","title":"حكم مزاولة الحجاج للتجارة خلال أيام الحج","answer":"الجواب: الأمر كما سمعتم لا حرج في ذلك، ليس في التجارة بأس في مواسم الحج للحجاج، وهذا من فضل الله ، فهو يحج ويطلب ما عند الله، ولا بأس أن يتجر ويبيع ويشتري يطلب الرزق في عرفات في مزدلفة في منى في أي مكان؛ لقوله : لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلًا مِنْ رَبِّكُمْ [البقرة:198] وقد تحرج الناس في ذلك فأنزل الله الآية فرفعت الحرج، قرأ بعضهم: ليس عليكم جناح أن تبتغوا فضلاً من ربكم في مواسم الحج، زيادة: في مواسم الحج والمعنى هو هذا المعنى: من باب التفسير، المعنى أنه ليس عليهم حرج في التجارة في مواسم الحج من ..... مشعر مزدلفة، مشعر عرفة، مشعر منى، في بطن مكة، .. كل هذا لا حرج فيه والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/7245/حكم-مزاولة-الحجاج-للتجارة-خلال-ايام-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_226/22607.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":9101,"question":"السؤال الثاني في رسالة الأخ: عبد الرحمن صالح محمد أحمد من جمهورية الصومال يقول فيه: هل هناك إثم على الحاج لو ذبح قبل أن يرمي أو حلق قبل أن يذبح، وهل يلزمه شيء وما هي الكفارة أفتونا جزاكم الله خيراً؟","title":"حكم تقديم بعض الأعمال على بعض يوم النحر","answer":"الجواب: النبي ﷺ في يوم العيد رمى الجمرة ضحى، ثم نحر هديه ﷺ ثم حلق رأسه، ثم طيبته عائشة رضي الله عنها، ثم ركب إلى البيت فطاف به، هذا هو السنة، وقال: خذوا عني مناسككم اللهم صل عليه وسلم، هذا هو المطلوب من الحاج وهذا هو الأفضل: أنه يرمي سواء كان رجل أو امرأة يرمي أولاً جمرة العقبة يوم العيد بسبع حصيات ثم ينحر هديه إن كان عنده هدي، ثم بعد ذلك يحلق رأسه أو يقصر، وبهذا حل التحلل الأول، فيلبس المخيط ويتطيب كما فعل النبي ﷺ، ثم الطواف بعد ذلك، وليس له أن يأتي النساء حتى يطوف وحتى يسعى إن كان عليه سعي بعد الرمي والحلق، أما إذا رمى وحلق فإنه يتطيب ويلبس المخيط ويغطي رأسه، ويقلم أظفاره ويقص شاربه لا بأس، لكن لا يأتي المرأة حتى يضيف إلى الرمي والحلق الطواف والسعي إن كان عليه سعي، لكن لو قدم بعضها على بعض فلا حرج، لو أنه حلق قبل أن يرمي، أو نحر قبل أن يرمي، أو طاف قبل أن يرمي، أو طاف قبل أن ينحر فلا حرج في ذلك، أو سعى قبل أن يطوف كما يفعل بعض الجهال، فقد ثبت عنه ﷺ: أنه سئل يوم العيد عمن قدم وأخر في هذه الأمور فقال: لا حرج لا حرج عليه الصلاة والسلام وقال له رجل: يا رسول الله! إني أفضت قبل أن أرمي، قال: لا حرج، وقال آخر: يا رسول الله! حلقت قبل أن أذبح؟ قال: لا حرج، وقال آخر: سعيت قبل أن أطوف قال: لا حرج، فما سئل يومئذ عن شيء قدم أو أخر إلا قال: افعل ولا حرج عليه الصلاة والسلام.\nفهذا من لطف الله ومن رحمته وإحسانه إلى عباده جل وعلا، فالحاج من الرجال والنساء مشروع له أن يفعل ما فعله الرسول ﷺ، فيرمي أولاً يوم العيد ثم ينحر هديه إن كان هناك هدي، ثم يحلق أو يقصر والحلق أفضل، ثم يطوف ويسعى إن كان عليه سعي، هذا هو المشروع، فمن قدم بعضها على بعض ولم يرتب فلا حرج عليه مثلما تقدم، إذا حلق قبل أن يرمي أو طاف قبل أن يرمي أو نحر قبل أن يرمي أو حلق قبل أن يذبح، أو طاف قبل أن يذبح كله لا حرج، وهكذا لو سعى قبل أن يطوف على الصحيح، وإن كان خلاف قول الجمهور، لكن هو الصحيح؛ لأنه جاء به النص عن النبي ﷺ، فمن سعى قبل أن يطوف جاهلاً أم ناسياً فلا حرج عليه، وسعيه صحيح. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7258/حكم-تقديم-بعض-الاعمال-على-بعض-يوم-النحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_227/22704.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":9347,"question":"رسالة أخرى وصلت أيضًا من السودان وباعثها أحد الإخوة يقول: (ح. م. ج) أخونا يسأل عن صديق له حميم -كما يصفه- ويقول: إنه قتل نفسًا وهو في سن الثاني عشرة من عمره، وبعد أن بلغ سن الرشد صار رجلًا مؤمنًا تقي، وصلى وصام وأدى جميع الفرائض، وعندما أراد أداء فريضة الحج سأل بعض العارفين، فقالوا له: قاتل النفس لا يجوز له أداء الفرض، أفيدوني زادكم الله علما؟","title":"حكم حج من قتل نفسًا قبل البلوغ","answer":"الجواب: هذا الجواب غلط، وهذه الفتوى غلط نسأل، الله السلامة، هذا الرجل الذي قتل في حال الصغر قبل التكليف لا شيء عليه؛ لقول النبي ﷺ: رفع القلم عن ثلاثة: عن الصبي حتى يبلغ، وعن المعتوه حتى يفيق، وعن النائم حتى يستيقظ لكن على العاقلة الدية إذا كان له عاقلة، يعني: عصبة أغنياء عليهم الدية للقتيل، وأما هو فليس عليه كفارة؛ لأنه غير مكلف، وإنما الدية على العاقلة؛ لأن عمد الصبي وعمد المجنون حكمه حكم الخطأ، ودية الخطأ على العاقلة وهم العصبة كما جاء ذلك عن النبي عليه الصلاة والسلام، وحجه صحيح سواء كان قبل أداء العاقلة للدية أو بعدها، لا يتعلق حجه بأداء الدية، بل حجه صحيح إذا استوفى ما شرع الله له، والدية يطالب بها العاقلة، والكفارة لا شيء عليه؛ لأنه ليس من أهل التكليف ذلك الوقت لا بصوم ولا عتق. نعم.\nالمقدم: إذا كان ابن الثانية عشرة في بعض البلدان بلغ مبلغ الرجال -سماحة الشيخ- يتغير الحكم؟\nالشيخ: الحكم على البلوغ إذا كان بلغ بالمني يعني: بإنزال المني، أو بإنبات الشعرة وهي الشعر الخشن الذي حول الفرج فله حكم الرجال.. حكم المكلفين، فإذا كان حين القتل قد احتلم، يعني: أنزل بالشهوة المني في الليل أو في النهار في احتلام أو غيره، أو أنبت الشعر المعروف الذي هو الشعرة وهو شعر العانة المعروفة عند الفرج، الشعر الخشن المعروف على الصحيح يكون بالغًا بذلك، أو كمل خمسة عشر، هذا ما كمل خمسة عشر. نعم.\nالمقدم: فيكون الحكم حينئذ على افتراض أنه بلغ مبلغ الرجال ...\nالجواب: إذا كان بلغ عليه العتق إن قدر وإلا فصيام شهرين متتابعين عن القتل إذا كان خطأ، أما إن كان عمدًا فلا شيء عليه إلا الدية أو القصاص، إذا كان عمدًا وهو قد كلف فأهل القتيل لهم الخيار بين القود وبين الدية وبين العفو، فإن طلبوا القود فهذا إلى ولي الأمر يعطيهم القود إذا توفرت شروطه عند المحكمة، فإن طلبوا الدية يعطون الدية في ماله هو؛ لأنه عامد، فإن عفوا فالأجر لهم، وليس فيه كفارة العمد، الكفارة في الخطأ، أما إذا تعمد ........ الكفارة لكن عليه التوبة، البدار بالتوبة إلى الله والندم على ما مضى منه؛ لأن القتل جريمة عظيمة، وكبيرة عظيمة، فعليه التوبة إلى الله والإنابة والحزن على ما وقع منه، والعزم أن لا يعود في ذلك، وعليه أن يمكن ورثة القتيل من حقهم من القصاص أو الدية. نعم.\nالمقدم: وبارك الله فيكم، وحينئذ يلزمه أيضًا أداء الفرائض كفريضة الحج؟\nالشيخ: نعم، ما لها تعلق بهذا، عليه أن يؤدي الحج ويصوم رمضان وغيره من الشرائع، ولا تعلق لها بهذه الجريمة. نعم.\nالمقدم: إذًا فتوى أولئك خاطئة سواء كان عامدًا أو مخطئًا.\nالشيخ: خطأ عظيم.\nالمقدم: جزاكم الله خيرا.\nالشيخ: سواء كان بالغًا أو غير بالغ.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7502/حكم-حج-من-قتل-نفسا-قبل-البلوغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_185/18503.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":9413,"question":"أخونا أيضاً يسأل ويقول: الكثير من الحجاج هداهم الله يأتون من مكان بعيد ويتكبدون الصعوبات والمشاق ولكنهم لا يصونون حجهم مما يفسده أو ينقصه، مثل التساهل بالصلاة مع الجماعة ولعب الورق واستماع آلات اللهو وشرب المحرمات وغير ذلك، فنرجو بيان حرمة هذا العمل لاسيما في هذا السبيل جزاكم الله خيراً؟","title":"وصايا للحجاج","answer":"الجواب: وصيتي لجميع الحجاج من الرجال والنساء أن يتقوا الله  في كل مكان في طريقهم للحج وفي مشاعر الحج وفي المسجد الحرام وفي كل مكان، وصيتي للجميع أن يتقوا الله وأن يحرصوا كثيراً على أداء ما فرض الله وعلى ترك ما حرم الله وأن يكملوا حجهم بالبعد عن كل ما حرم الله عليهم حتى يكون الحج كاملاً تاماً لقول النبي ﷺ: من حج فلم يرفث ولم يفسق رجع كيوم ولدته أمه وهذا فضل عظيم، فالمؤمن إذا أكمل حجه فلم يرفث ولم يفسق رجع من هذا الحج العظيم رجع كيوم ولدته أمه يعني: مغفوراً له يعني: قد غفر الله له، والرفث هو الجماع للمرأة وما يدعو إليه من القول والفعل، فالمحرم يبتعد عن ذلك لا يجامع زوجته حتى ينتهي من إحرامه من رمي الجمار والحلق أو التقصير والطواف والسعي بعد نزوله من عرفات والمعتمر كذلك إذا أحرم بالعمرة لا يأتي زوجته ولا يداعبها ولا يمسها لشهوة حتى يطوف ويسعى ويقصر أو يحلق ويتم عمرته، هذا هو الرفث، فالجماع وما يدعو إليه يسمى رفثاً، فالمحرم يبتعد عن ذلك في حجه وعمرته حتى يكمل حجه حتى يتحلل من عمرته وحتى يتحلل التحلل الثاني من حجه بعد الطواف والسعي ورمي الجمار يوم العيد والحلق أو التقصير، هذا هو الواجب على الحاج والمعتمر وكذلك الفسوق يجتنبه، الفسوق والمعاصي كلها فالمؤمن يجتنب الفسوق في الحج وفي غيره، فكل المعاصي تسمى فسوق، ومن ذلك الغيبة والنميمة والتعدي على الناس بالضرب أو بغيره، أو التعدي عليهم في أموالهم والسب والشتم، كل هذا من المعاصي فالواجب على الحاج والمعتمر وغيرهما من رجال ونساء أن يتجنبوا ذلك، ومن ذلك التكاسل عن الصلاة في الجماعة فإن صلاة الجماعة فريضة والواجب على الحاج.. أن يصلي في الجماعة وأن لا يتساهل، وأعظم من ذلك وأكبر أن يدع الصلاة وأن يتساهل بها هذا أعظم وأكبر يجب أن يحافظ على الصلاة في أوقاتها فإنها عمود الإسلام وقد قال عليه الصلاة والسلام: رأس الأمر الإسلام وعموده الصلاة وذروة سنامه الجهاد في سبيل الله وقال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة رضي الله عنه، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه.\nفالواجب على الجميع من الرجال والنساء العناية بالصلاة والمحافظة عليها في أوقاتها في الحج وفي غيره وفي أي مكان فهي عمود الإسلام وهي أعظم الفرائض بعد الشهادتين، فيجب على الرجال والنساء من المسلمين العناية بالصلاة والمحافظة عليها وأداؤها بخشوع والطمأنينة والإقبال عليها وعدم العجلة يؤديها بطمأنينة وعدم نقر وعدم عجلة في أيام الحج وفي غير الحج هكذا المؤمن وهكذا المؤمنة، وكذلك آلات الملاهي والغناء يبتعد المؤمن عن ذلك في الحج وفي غيره؛ لأن الغناء كما قال ابن مسعود : ينبت النفاق في القلب كما ينبت الماء البقل والله يقول سبحانه: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ [لقمان:6] قال أكثر العلماء من المفسرين: (لهو الحديث) هو الغناء. وإذا كان من النساء ومن يتشبه بالنساء صارت الفتنة أكبر وأعظم، وإذا كان في الإذاعة وفي مواسم الحج صار أشد، يقول عبد الله بن مسعود  وهو أحد علماء الصحابة أصحاب النبي عليه الصلاة والسلام: إنن الغناء ينبت النفاق في القلب كما ينبت الماء الزرع الغناء هو ما يقع من الأشعار الملحنة في مدح الزنا أو الخمور أو ذكر النساء أو الفتنة بالنساء أو غير هذا مما يجر إلى الفساد والشر، فهذا خطره عظيم في الحج وفي غيره، فالواجب اجتنابه، وإذا كان مع الغناء آلات اللهو من العود والكمان والمزمار والموسيقى صار الشر أكثر وصارت الفتنة أكبر وصار الإثم أشد، فيجب على المؤمن و على المؤمنة الحذر من ذلك في أي مكان في الحج في السيارة في الطائرة في القطار في بلاده في غير بلاده أينما كان فالمؤمن مع إخوانه يتواصون بالخير، فالله يقول سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] هؤلاء هم الرابحون هؤلاء هم السعداء: الَّذِينَ آمَنُوا بِاللَّهِ وَرَسُولِهِ[النور:62] صدقوا الله ورسوله ووحدوا الله وعظموه وأخلصوا له العبادة وآمنوا برسوله محمد ﷺ وصدقوه واتبعوه وعملوا الصالحات، يعني: أدوا فرائض الله واجتنبوا محارم الله، ثم مع ذلك تواصوا بالحق يعني: يتناصحون يتعاونون على البر والتقوى (وتواصوا بالصبر) أيضاً على ذلك، هؤلاء هم الصالحون هؤلاء هم الرابحون هؤلاء هم السعداء هم الأخيار فعلى كل مؤمن ومؤمنة أن يحرص على أن يكون من هؤلاء.","link":"https://binbaz.org.sa/fatwas/7578/وصايا-للحجاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_159/15903.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":9716,"question":"الرسالة التالية وصلت من الأخ المستمع محمد زهير الرفاعي من المدينة المنورة يقول في رسالته: ما الفرق بين الفرض والواجب في الحج؟ وهل يستويان في الابتداء أفيدونا أفادكم الله؟","title":"الفرق بين الفرض والواجب في الحج","answer":"الجواب: الفرض والواجب الفرق بينهما أمر اصطلاحي: فالجمهور يرون أن الفرض والواجب شيء واحد، وأن الفرض هو ما لزم العبد شرعًا والواجب كذلك، وقال آخرون من أهل العلم: الفرض ما تأكد دليله وقويت حجته صارت فرضيته أشد وأقوى، والواجب ما كان دون ذلك في الأدلة، فالوقوف بعرفة مثلًا فرض لأن أدلته عظيمة وهو الحج، رمي الجمار أسهل من ذلك وإن كان واجبًا، فيطلق على مثل رمي الجمار ومثل المبيت بمزدلفة واجب، ويطلق على الوقوف بعرفة مثلًا والطواف أنه فرض لعظم أدلتهما وشدة وجوبهما، والقول الآخر للجمهور يسمي الجميع فرضًا ويسمي الجميع واجبًا والأمر في هذا لا مشاحة فيه، لكن لاشك أن الواجبات تختلف بعضها أوجب من بعض وأشد فرضية من بعض، فالوقوف بعرفة وطواف الإفاضة لهما شأن وهكذا الإحرام له شأن بخلاف رمي الجمار بخلاف طواف الوداع فإنهما أسهل من ذلك وإن كان الكل واجبًا. نعم.","link":"https://binbaz.org.sa/fatwas/7871/الفرق-بين-الفرض-والواجب-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_195/19506.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":9719,"question":"ويضيف الأخ محمد زهير الرفاعي ويسأل السؤال التالي: كيف كانت حجة رسول الله ﷺ؟ هل تمتع أو قرن أو أفرد، أفيدونا أفادكم الله؟","title":"كيفية حج الرسول عليه الصلاة والسلام","answer":"الجواب: الرسول ﷺ حج قارنًا، هذا هو الصواب الذي عليه المحققون من أهل العلم وقد تواترت به الأخبار عن رسول الله ﷺ أنه لبى بالحج والعمرة جميعًا وقال: لولا أن معي الهدي لأحللت معكم.\nفالمقصود أنه حج قارنًا لبى بهما جميعًا -للعمرة والحج جميعًا- وبقي على إحرامه ؛ لأنه كان ساق الهدي عليه الصلاة والسلام، وأما الصحابة الذين لم يسوقوا الهدي فإنه أمرهم بالإحلال فحلوا فطافوا وسعوا وقصروا وحلوا وأحرموا بالحج يوم التروية عند توجههم إلى منى، وأما هو ﷺ فكان قارنًا، هذا هو الصواب لبى بالحج والعمرة جميعًا هذا هو المحفوظ من فعله عليه الصلاة والسلام ولكونه ساق الهدي لم يتحلل مع الناس وقد بقي على إحرامه حتى حل منهما جميعًا يوم النحر فرمى يوم العيد ثم نحر ثم حلق رأسه ثم تحلل وتطيب ثم ركب إلى البيت فطاف به طواف الإفاضة عليه الصلاة والسلام، هذا هو الحق. نعم.","link":"https://binbaz.org.sa/fatwas/7874/كيفية-حج-الرسول-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_195/19507.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":10380,"question":"ننتقل بعد هذا إلى رسالة وصلت من جمهورية مصر العربية باعثها المستمع: ( أحمد . م)، يسأل جمعاً من الأسئلة في أحدها يقول: هل الحج لا يصح إلا بزيارة مسجد الرسول ﷺ، وكذلك السلام عليه؟","title":"حكم حج من لم يقم بزيارة المسجد النبوي","answer":"الجواب: الحج مستقل ما له تعلق بالزيارة، ولا يربط بالزيارة، الحج إذا أداه المؤمن على ما شرعه الله تمت ولو ما زار المدينة، أما زيارة المدينة سنة، زيارة المسجد النبوي سنة، نافلة من زاره فله أجر، ومن ترك فلا شيء عليه؛ لقوله ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى، وقال عليه الصلاة والسلام: صلاة في مسجدي هذا خير من ألف صلاة فيما سواه إلا المسجد الحرم، وصلاة في المسجد الحرام خير من مائة صلاة في مسجدي هذا، فدل ذلك على أن الزيارة للمسجد سنة فيها مضاعفة للصلاة، ولكن ليست واجبة، الواجب إتيان المسجد الحرام للحج والعمرة، هذا هو الواجب، مرة في العمر، إذا حج مرة، واعتمر مرة، سقط عنه زيارة المسجد بعد ذلك، وإذا أتى المسجد الحرام للعمرة والحج ولو مرات كثيرة هذا سنة، التزود من الحج مرات ومن العمرة مرات هذا شيء مطلوب مشروع، وهكذا زيارة المسجد النبوي، إذا زاره للصلاة فيه والقراءة والتعبد مشروعة ولو تكرر.\nهكذا المسجد الأقصى، لكنه دون المسجدين، والصلاة فيه بخمسمائة صلاة، مسجد القدس كل هذه سنة زيارتها، ولو تكررت كثيرًا، لكن الواجب الزيارة للمسجد الحرام للحج والعمرة فقط، هذا الواجب مرة في العمر، الحج مرة، والعمرة مرة، والبقية كلها نافلة، بعد الحج مرة واحدة، والعمرة مرة يكون نافلة، وزيارة المسجد النبوي نافلة، وزيارة المسجد الأقصى نافلة، ما في فرض إلا إذا نذر، قال: نذر لله أني أصلي في المسجد النبوي يكون واجب حتى يؤدي النذر، أو قال: نذر لله علي أن أصلي في المسجد الأقصى يكون واجب، أو نذر لله أن يصلي في المسجد الحرام يكون واجب بالنذر، لقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ولا شك أن الصلاة في المسجد النبوي طاعة، وفي المسجد الأقصى طاعة، فلا بأس أن يؤديه ولو بشد الرحل، أما لو قال: لله علي أن أصلي ركعتين في مسجد قباء أو في مسجد دمشق غير المسجد الأقصى، ما يلزمه، وليس عليه شد الرحل، ليس له شد الرحل في هذا؛ لأن الرسول ﷺ نهى عن هذا، شد الرحل، يصلي في أي مسجد ويكفي، لكن إذا خص الثلاثة يلزمه شد الرحل، المسجد الحرام، والمسجد الأقصى، ومسجد النبي ﷺ، لقوله ﷺ: من نذر أن يطيع الله فليطعه، وقوله ﷺ: لا تشدوا الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى، فلو نذر صلاة في أي مكان لم يلزمه الوفاء أو الصوم إلا في هذه الثلاثة، في المسجد الحرام ومسجد النبي ﷺ، والمسجد الأقصى. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8552/حكم-حج-من-لم-يقم-بزيارة-المسجد-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28005.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":10815,"question":"يقول: ما حكم حج الابن الصغير إذا ذهب مع والده، وأخطأ في بعض الأحكام؟","title":"حكم حج الصغير إذا أخطأ في بعض المناسك","answer":"الجواب:  حجه يعتبر نافلة، وإذا أخطأ في شيء عليه ما على الكبير المكلف، فإذا مثلًا لم يرم الجمار، ولم يرم عنه الجمار، يفدى عنه بذبيحة، أما لو قطع أظفرًا، أو غطى رأسه وهو ذكر ما عليه شيء؛ لأنه في حكم الناسي، والجاهل فلا عليه شيء؛ لأن مثله ليس ممن يفهم الأحكام، فإذا غطى رأسه، أو قلم أظفره، أو قطع بعض الشعر، ولم ينتبه له وليه الذي معه حتى يعلمه فلا شيء عليه؛ لأنه ليس بمكلف، نعم.","link":"https://binbaz.org.sa/fatwas/9007/حكم-حج-الصغير-اذا-اخطا-في-بعض-المناسك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35418.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":10821,"question":"يقول: ما حكم حج الابن الصغير إذا ذهب مع والده، وأخطأ في بعض الأحكام؟","title":"حكم حج الصغير إذا أخطأ في بعض المناسك","answer":"الجواب:  حجه يعتبر نافلة، وإذا أخطأ في شيء عليه ما على الكبير المكلف، فإذا مثلًا لم يرم الجمار، ولم يرم عنه الجمار، يفدى عنه بذبيحة، أما لو قطع أظفرًا، أو غطى رأسه وهو ذكر ما عليه شيء؛ لأنه في حكم الناسي، والجاهل فلا عليه شيء؛ لأن مثله ليس ممن يفهم الأحكام، فإذا غطى رأسه، أو قلم أظفره، أو قطع بعض الشعر، ولم ينتبه له وليه الذي معه حتى يعلمه فلا شيء عليه؛ لأنه ليس بمكلف، نعم.","link":"https://binbaz.org.sa/fatwas/9007/حكم-حج-الصغير-اذا-اخطا-في-بعض-المناسك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35418.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":11319,"question":"المستمع إبراهيم سالم بعث برسالة يقول: لقد قضيت فريضة الحج، وكنت متمتعًا، وأحب أن أقضي عمرة عن والدي وعمرة عن والدتي، فهل يجوز هذا؟ جزاكم الله خيرًا.","title":"حكم من حج متمتعاً وأراد أن يعتمر عن والديه","answer":"الجواب:  نعم، أنت مأجور إذا اعتمرت عن أبيك أو حججت وعن أمك كذلك أنت مأجور، إذا كانا ميتين أو عاجزين لكبر السن فأنت مأجور على كل حال فتحج عن أبيك أو تعتمر عن أبيك، وإذا أديت العمرة عن نفسك ثم اعتمرت عنهما كل ذلك حسن. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9501/حكم-من-حج-متمتعا-واراد-ان-يعتمر-عن-والديه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37712.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":11368,"question":"يقول: اعتمرت ولكني لم ألبِ، فهل عمرتي صحيحة؟","title":"حكم التلبية في الحج والعمرة","answer":"الجواب:  نعم صحيحة، التلبية سنة، إذا أحرم من الميقات أو من مكة إن كان من أهل مكة، أو من جدة إن كان من أهلها فإن إحرامه صحيح إذا نوى العمرة، وهكذا الحج والسنة التلبية. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9551/حكم-التلبية-في-الحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37901.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":11376,"question":"يقول: اعتمرت ولكني لم ألبِ، فهل عمرتي صحيحة؟","title":"حكم التلبية في الحج والعمرة","answer":"الجواب:  نعم صحيحة، التلبية سنة، إذا أحرم من الميقات أو من مكة إن كان من أهل مكة، أو من جدة إن كان من أهلها فإن إحرامه صحيح إذا نوى العمرة، وهكذا الحج والسنة التلبية. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9551/حكم-التلبية-في-الحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37901.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":11626,"question":"مجموعة من النساء ذهبن للحج، وعندما وصلن عرفة يقلن: إننا خلعنا الثياب عن رؤوسنا لشدة الحر، ولم يكن يعلمن ما حكم ذلك، فما هو توجيهكم؟","title":"حكم نزع المرأة غطاء رأسها في الحج بعرفات","answer":"الجواب: الوقوف الحمد لله لا بأس به، إذا كان ما عندهم أجانب لا حرج -إن شاء الله- الستر هذا يجب عند وجود الأجنبي، أما إذا خلعنه عن رؤوسهن في الخيمة ليس عندهن إلا النساء؛ فلا حرج في ذلك، مثل الرجل لو طرح الرداء عن كتفيه للحر؛ فلا بأس بذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9811/حكم-نزع-المراة-غطاء-راسها-في-الحج-بعرفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38822.mp3","categories":["اللباس والزينة","مسائل متفرقة في الحج والعمرة","ردود وتعقيبات"]},{"id":11711,"question":"مستمع يسأل سؤالين يقول في سؤاله الأول: جئت لكي أعتمر، ولم أحرم في الباخرة، ولم أمكث في البلد هنا سوى ليلتين فقط، وفي اليوم الثالث قمت بالاعتمار، فقال لي بعض الناس: لابد أن تمكث في البلد ثلاثة أيام، أريد من سماحتكم أن أعرف هل عمرتي صحيحة؟ أم أن علي كفارة؟ جزاكم الله خيرًا.","title":"حكم اشتراط بقاء المعتمر في مكة ثلاثة أيام","answer":"الجواب:  إذا كنت أحرمت من الميقات لما حاذيته في الباخرة، أو ذهبت إليه حتى أحرمت من الميقات ميقات بلدك؛ فليس عليك بأس إذا كملت العمرة، ولو ما مكثت إلا يومًا واحدًا، أو ساعة واحدة، ليس للعمرة أيام معلومة، فالذي قال لك: لابد من ثلاثة أيام قوله لا أصل له، قول باطل، متى طاف الإنسان وسعى وقصر؛ تمت عمرته، وله أن يسافر في الحال في اليوم الذي قدم فيه، لا حرج في ذلك. أما إن كنت ما أحرمت إلا من مكة، أو من قرب مكة؛ تجاوزت الميقات، ولم تحرم؛ فعليك دم يذبح بمكة للفقراء، والعمرة صحيحة، لكنها ناقصة، تجبر بدم؛ لأنك لم تحرم من الميقات. نعم. المقدم: جزاكم الله خيرًا، إذًا الإقامة لا تأثير على الإحرام فيها؟ جزاكم الله خيرًا.  الشيخ: أما الإقامة لا. المقدم: لابد أن يكون الإحرام من الميقات. الشيخ: نعم، نعم. المقدم: بارك الله فيكم. الشيخ: ميقات بلده. المقدم: ميقات بلده. الشيخ: أو البلد الذي يمر عليه. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9889/حكم-اشتراط-بقاء-المعتمر-في-مكة-ثلاثة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_392/39202.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":11844,"question":"المستمع (ع. د. أ) بعث بسؤال يقول فيه: أريد أن أحج حجًا بدون عمرة؛ لأنني ليس عندي الاستطاعة للفدية، لكني لا أعرف الطرق الصحيحة التي أتبعها حتى يكون حجي صحيحًا، وبدون فدية، علمًا بأنني أقيم، وأعمل في جدة، أفيدوني بارك الله فيكم.","title":"صفة حج المفرد","answer":"الجواب:  الحج الذي ليس فيه فدية أن تحرم بالحج مفردًا، تقول: اللهم لبيك حجًا مع النية بقلبك إذا كنت في جدة من جدة تلبي بالحج، ناويًا الحج مفردًا، فتذهب إلى مكة وقت الحج، تطوف وتسعى، وتبقى على إحرامك، حتى تقف في عرفات حتى ترمي جمرة العقبة. فإذا رميت جمرة العقبة؛ فالأفضل أن تحلق، وإن قصرت؛ فلا بأس، ثم تحل، ومن حل بعد الرمي؛ أجزأه، لكن الأفضل أن يكون بعد الحلق، بعد الرمي والحلق، أو التقصير، ثم يلبس ثيابه إذا شاء، ويتطيب إذا شاء، ثم يطوف ويسعى طوافًا بالبيت سبعة أشواط، ويصلي ركعتين، ثم يسعى بين الصفا والمروة سبعة أشواط، هذا هو الحج المفرد ما فيه هدي، تحرم من مكانك من جدة، أو من الميقات إن كنت في غير جدة، إذا مررت بالميقات تحرم من الميقات بالحج فقط تقول: اللهم لبيك حجًا.  ثم إذا جئت مكة تطوف بالبيت، وتسعى، وتبقى على إحرامك حتى تخرج إلى عرفات، وحتى ترمي الجمرة يوم العيد، ثم تحل، تحلق أفضل، أو تقصر، ثم تحل، تطيب، وتلبس الملابس، ثم عليك الطواف بعد ذلك، طواف فقط بدون سعي، إلا إذا كنت أخرت السعي إلى بعد العيد؛ تسعى مع الطواف، ليس عليك إلا شيء واحد، إن قدمته مع طواف القدوم؛ كفى، وإن أخرته مع طواف الإفاضة؛ فلا بأس، وإذا رميت الجمرة حصل التحلل الأول. لكن الأفضل والأحوط أن يكون مع الرمي الحلق أو التقصير؛ خروجًا من الخلاف، ثم تحل، تطوف ثم تحل يعني: تلبس الملابس، تطيب، ثم يبقى عليك الطواف والسعي إن كنت ما سعيت مع طواف القدوم، يبقى عليك الطواف والسعي. وبهذا يحصل التحلل كله إن كان له زوجة تحل له الزوجة، ويبقى عليك الرمي في الحادي عشر، والثاني عشر رمي الجمار الثلاث، ويوم المبيت ليلة إحدى عشر وليلة اثنا عشر، وإن شئت بقيت ليلة الثالث عشر؛ فهو أفضل، تبقى اليوم الثالث عشر، وإن تعجلت في اليوم الثاني عشر بعد الرمي؛ فلا بأس، ترمي الجمرة بعد الزوال في الثاني عشر، وتعجل إلى مكة، تطوف طواف الوداع. ثم تخرج إلى أهلك، طواف وداع من دون سعي، وإن بقيت في منى إلى اليوم الثالث عشر؛ ترمي الجمار الثلاث، فهذا أفضل كما بقي النبي ﷺ ثم بعد رمي الجمار بعد الزوال تخرج إلى مكة للوداع، وإن بقيت في مكة أيامًا؛ فلا بأس، لكن إذا عزمت على السفر؛ تطوف للوداع سبعة أشواط، قبل السفر، وتصلي ركعتين سنة بعد الطواف، نعم وليس فيه سعي. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10034/صفة-حج-المفرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39614.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":12034,"question":"يسأل: هل يجوز لي زيارة البيت الحرام، والصلاة فيه بدون إحرام مع أنني من سكان جدة؟","title":"حكم زيارة البيت الحرام للصلاة فيه دون الإحرام بعمرة","answer":"الجواب:  نعم لا حرج أن تزور مكة، وتطوف، وتصلي في المسجد الحرام من دون حاجة إلى عمرة، والحمد لله، إذا كنت أديت العمرة سابقًا عمرة الإسلام، فلك أن تزور متى شئت، فتطوف، أو تصلي مع المسلمين، ثم ترجع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10219/حكم-زيارة-البيت-الحرام-للصلاة-فيه-دون-الاحرام-بعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43303.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":12122,"question":"من أدى الحج وهو محافظ على أركان الإسلام إلا أنه ارتكب بعض المعاصي، هل يؤثر ذلك على أعماله الطيبة؟ جزاكم الله خيرًا.","title":"حكم ارتكاب الحاج بعض المعاصي","answer":"الجواب:  الحج صحيح، ولو كان عنده شيء من المعاصي الحج صحيح، لكن ما يكون مبرورًا إلا إذا كان صاحبه ليس بفاسق، لقوله ﷺ: من حج فلم يرفث، ولم يفسق؛ رجع كيوم ولدته أمه وقال -عليه الصلاة والسلام-: الحج المبرور ليس له جزاء إلا الجنة والحج المبرور هو الذي ليس فيه رفث، وهو الجماع ودواعيه، ولا فسق المعاصي، فإذا كان حين حج يأتي بعض المعاصي؛ حجه ناقص، ولكنه يجزئ يبرئ ذمته من الفريضة، لكن يكون حجه ناقصًا، لا يكون مبرورًا، يكون ناقصًا، فإذا كان مثلًا يأكل الربا، أو عنده عقوق لوالديه، أو أحدهما أو قاطعًا للرحم، أو يغتاب الناس، يتعاطى الغيبة، أو ما أشبه ذلك، أو خان في معاملة، أو غش في معاملة، كل هذه معاصي، يكون حجه ناقصًا، ودينه ناقصًا، وإيمانه ناقصًا، ولكن لا يكفر بذلك، ولا يبطل حجه بذلك ما دام على الإسلام والتوحيد، والإيمان بالله ورسوله، هذا الذي عليه أهل الحق من الصحابة، ومن بعدهم، وهم أهل السنة والجماعة، وهم الفرقة الناجية، وهم الطائفة المنصورة الذين استقاموا على دين الله، ووحدوا الله، وأخلصوا له العمل، هؤلاء هم أهل الإسلام، وهم أهل الإيمان وهم أهل التقوى والبر، فإذا وقع من أحدهم معصية؛ صار نقصًا في الإيمان، ضعفًا في الإيمان، لا يخرج بذلك عن دائرة الإسلام، وحجه صحيح، وصلاته صحيحة، وصومه صحيح، لكنه يأثم بالمعصية التي تعاطاها، كالغيبة، أو أكل الربا، أو غش في المعاملة، أو أشبه ذلك، يكون نقصًا في إيمانه، نقصًا في صومه، نقصًا في حجه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10307/حكم-ارتكاب-الحاج-بعض-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43807.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":12167,"question":"رسالة من أحد الإخوة المستمعين سمى نفسه أبو سبعان من المنطقة الجنوبية في المملكة، يقول: ذهبت للحج مع أحد الأقارب، وكان بي مرض يسمى الناسور، وهو يقع في أسفل الظهر، ويخرج دمًا وقيحًا، وهو مرض مزمن، هل ذلك يؤثر على الحج؟","title":"صحة حج من به الناسور","answer":"الجواب:  ليس ذلك يؤثر على الحج، ولكن أنت تجتهد في الشيء الذي يقي ثيابك وبدنك من الصديد والدم، تفعل ما تستطيع، ولا يمنع صلاة ولا حجًا فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وهذا يكون في الدبر، والإنسان يعالجه بما يستطيع من جهة المختصين، ويتحفظ مما يخرج، وإذا كان الخارج يستمر توضأ لكل صلاة، تمسح بشيء من مناديل ونحوها عند دخول الوقتـ ثم يتوضأ، يتمسح ثلاث مرات، أو أكثر عن الخارج من داخل الدبر، أو يستنجي بماء إن كان لا يضره الماء، وإلا فليكفي التمسح بالمناديل الطاهرة ثلاث مرات فأكثر، حتى ينقي المحل حسب الطاقة بعد دخول الوقت، ثم يتوضأ وضوء الصلاة، ويتحفظ في بقية الأوقات بما يصونه من آثار الدم والصديد الذي يخرج، ولا يضر ذلك حجه، ولا يضر صلاته، والحمد لله، نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10353/صحة-حج-من-به-الناسور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_442/44205.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":12577,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع علي حمود سعيد البادي من باحة سلطنة عمان، أخونا علي عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يسأل بعض الأسئلة، فيقول في السؤال الأول: إذا قال شخص: إن شاء الله سأذهب هذا العام للحج، فوافته المنية قبل موسم الحج، فماذا على ذويه أن يفعلوا، هل عليهم أن يحجوا عنه؟","title":"حكم من علق حجه على المشيئة فمات قبل الحج","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذا ليس عليه شيء، إذا قال: إن شاء الله سأحج هذا العام، فتوفاه الله قبل ذلك؛ فليس عليه شيء، ولا على أقاربه إذا كان قد حج الفريضة. أما إن كان لم يحج الفريضة، وهو قادر في حياته على أن يحج، فإن عليهم أن يخرجوا من تركته ما يحج به عنه، أما إن كان فقيرًا؛ فلا شيء عليه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10783/حكم-من-علق-حجه-على-المشيىة-فمات-قبل-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_412/41201.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":12739,"question":"نويت أداء العمرة، ولبست الإحرام، ثم حليت الإحرام، قبل ذهابي للعمرة، فهل علي فدية؟","title":"حكم من نوى العمرة أو الحج ثم بدا له ألا يفعل","answer":"الجواب:  هذا فيه تفصيل: إن كنت نويت العمرة، ودخلت فيها -نويت الدخول في العمرة- فليس لك أن تخلع الإحرام، وليس لك أن ترجع، بل عليك أن ..... عليك أن تكمل بالطواف والسعي والحلق أو التقصير؛ لأن الله يقول سبحانه: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196] من دخل فيهما؛ وجب عليه إتمامهما، أما إن كنت لا، نويت أن تعتمر، ولبست الإحرام، ولكن ما نويت الدخول، إنما لبست لتدخل في الإحرام، ولم تنو الدخول فيه، وإنما أنت تتهيأ لخلع الملابس المخيطة، والتهيؤ للغسل، أو للطيب، أو غير هذا مما يتهيأ به ثم تهل، فأنت في هذه الحالة لم تحرم، والنية مثل نية الإنسان الذي سافر من بلده ليعتمر أو ليحج، نية مطلقة ليس نية الدخول، أما إذا نويت الدخول في الإحرام، وأنك دخلت في العمرة؛ فحينئذ عليك أن تكمل، ولا تترك العمرة، ولا تلبس المخيط، وإذا لبست المخيط؛ عليك أن تخلع، وعليك أن تكمل العمرة بالطواف والسعي والحلق أو التقصير، لقول الله سبحانه: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196] ولو كنت أتيت زوجتك في هذه الحال بعد نية الدخول في العمرة؛ فإن العمرة تفسد بذلك، وعليك ذبيحة تذبح بمكة للفقراء، وعليك أن تكمل العمرة .... تكملها بالطواف والسعي والتقصير أو الحلق، ثم تأتي بعمرة أخرى من نفس الميقات الذي أحرمت منه للعمرة الأولى، كما أفتى جمع من الصحابة -رضي الله عنهم وأرضاهم- بذلك، فعليك أن تكمل العمرة التي أفسدتها بالوطء، عليك أن تكملها، وعليك أن تقضيها أيضًا بعمرة أخرى من نفس الميقات، نعم. المقدم: جزاكم الله خيرًا، إذًا بلبسه للإحرام وبنيته لا يعتبر داخلًا في العمرة سماحة الشيخ؟  الشيخ: لا، إلا إذا نوى الدخول فيها، أما إذا كان للتهيؤ لبس الإحرام ليحرم لينوي ويلبي، لكن ما بعد نوى الدخول، ولا حصلت التلبية، إنما هو يتهيأ، هذا ليس بإحرام، حتى ينوي بقلبه الدخول في العمرة، وأنه دخل فيها ليلبي بها، نعم. المقدم: ألا يكفي لبسه للإحرام ... ؟ الشيخ: ما يكفي. المقدم: لا يكفي.  الشيخ: لبس الإحرام لا يكفي إذًا لأنه قد يتهيأ يلبس الإحرام، ويتطيب، ثم بعد هذا يحرم، والأفضل أنه لا يحرم حتى يركب السيارة، أو المطية إن كان مطية؛ لأن الرسول ﷺ إنما أحرم بعدما ركب ناقته، تهيأ، ثم ركب الناقة، ثم لبى عليه الصلاة والسلام، نعم.","link":"https://binbaz.org.sa/fatwas/10953/حكم-من-نوى-العمرة-او-الحج-ثم-بدا-له-الا-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41810.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":13267,"question":"على بركة الله نبدأ هذا اللقاء بسؤال للسائل (ع. ع. ج) من الرياض، يقول: سماحة الشيخ! ما حكم استخدام الكتيبات، والتي توجد في أماكن مواقيت الإحرام، وفي جوار الحرم الخاصة بأدعية الطواف والسعي في الحج والعمرة، لأنني أقرأ هذه في بعض الأشواط، فوجهوني في ضوء سؤالي مأجورين؟","title":"حكم اقتناء الكتيبات الخاصة بأدعية الطواف والسعي","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فما يحصل من الكتابات التي فيها بعض الأدعية، أو بعض الأذكار الشرعية لا بأس بها إذا استفاد منها الإنسان، إذا كانت أذكارًا شرعية، أو أدعية شرعية لا حرج فيها، فالإنسان في طوافه، وفي سعيه يدعو بما تيسر، ولا يتكلف، يقرأ القرآن، يقول: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير.. سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، سبحان الله وبحمده .. سبحان الله العظيم .. اللهم اغفر لي وارحمني .. اللهم اغفر لي ولوالدي إذا كان والداه مسلمين، وهكذا. ما في شيء -بحمد الله- متحتم، ما تيسر من القرآن، أو الأدعية الطيبة كله طيب، وإذا كانت الكتابات التي وجدتها ما فيها محذور؛ تعرضها على أهل العلم إذا كان ما فيها محذور؛ لا بأس، الأمر واسع، والحمد لله. لكن يستحب للمؤمن في طوافه أن يبدأ طوافه باستلام الحجر الأسود، يقبله إذا تيسر، ويستلمه بيده، ويقبله ويقول: الله أكبر كما فعله النبي ﷺ ثم بعد ذلك يجعل البيت عن يساره، ويطوف، ويكثر من الذكر والدعاء والقراءة، والحمد لله، حسب ما تيسر. وهكذا في السعي يبدأ السعي عند مبدأ السعي يقرأ إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ [البقرة:158] هذا أفضل، ثم إذا صعد يكبر الله ثلاثًا، ويحمد الله، ويدعو، ويكرر ثلاث مرات، وهو رافع يديه مستقبل القبلة على الصفا، وهكذا على المروة، ويدعو بين ذلك؛ يدعو ثلاث مرات بما تيسر من الدعاء، تكبير وذكر ودعاء مكرر ثلاث مرات وهو مستقبل القبلة، على الصفا وعلى المروة، وفي الطريق بينهما يكثر من ذكر الله، ومن الدعاء في الطريق، ما بين الصفا والمروة، كما فعله النبي ﷺ فالأمر في هذا واسع، والحمد لله. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11553/حكم-اقتناء-الكتيبات-الخاصة-بادعية-الطواف-والسعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51406.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":13412,"question":"السائلة تقول: امرأة ذهبت إلى مكة وهي حائض، وجلست فيها يومًا حتى طهرت من حيضها، ثم اغتسلت، وذهبت لقضاء العمرة من طواف وسعي، لكنها بعد ذلك وجدت بعضًا من آثار الحيض، فما الحكم؟","title":"حكم من وجدت آثار الحيض بعد عمرتها","answer":"الجواب: لا يضرها ذلك إذا كان لا تعلم لا يضرها، طوافها صحيح والحمد لله، إذا وجدت في ثوبها، أو في سراويلها أثرًا من الدم لم تغسله، ولكن لم تعلم إلا بعد الطواف لا يضرها، كمن صلى وفي ثوبه نجاسة لم يعلم إلا بعد الصلاة صلاته صحيحة، والصلاة أعظم من الطواف. فإذا صلى في ثوب، ثم بان بعد الصلاة أن به نجاسة، أو صلى في سراويل، وبان فيه نجاسة، أو طاف في ثوب، أو بشت، أو غير ذلك ثم تبين بعد الطواف أن به نجاسة، ولم يعلم، أو كان عالمًا، ثم نسيها؛ فلا يضره ذلك، والحمد لله، يقول الله -جل وعلا-: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] وروي عنه ﷺ أنه قال: عفي لأمتي عن الخطأ والنسيان، وما استكرهوا عليه والحمد لله. والنبي ﷺ \"صلى في نعليه ذات يوم، ثم جاءه جبرائيل، فأخبره أن بهما أذى؛ فخلعهما، ولم يعد أول الصلاة\" عليه الصلاة والسلام. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11705/حكم-من-وجدت-اثار-الحيض-بعد-عمرتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_526/52607.mp3","categories":["مسائل متفرقة في الحج والعمرة","اللباس والزينة","قضايا المرأة"]},{"id":13490,"question":"في آخر أسئلته يقول: سماحة الشيخ! ما حكم التمسح بحيطان الكعبة، وفي كسوتها وبالمقام والحجر؟","title":"حكم التمسح بالكعبة وكسوتها وغير ذلك","answer":"الجواب: بدعة، حكمها أنها بدعة، ما يجوز؛ لأن الرسول ﷺ ما فعل ذلك، ويقول ﷺ: من عمل عملاً ليس عليه أمرنا؛ فهو رد ويقول ﷺ: من أحدث في أمرنا هذا ما ليس منه؛ فهو رد، ويقول: إياكم ومحدثات الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة وإذا قصد أن تمسحه بالجدار، أو بالكسوة يحصل له البركة من نفس الكسوة، أو من الجدار شرك أكبر، أما إذا ظن أنها مباركة، وأن الله شرع هذا، وأنه مشروع أنه يقبل هذا الجدار، أو هذه الكسوة؛ هذه بدعة، تصير بدعة، أما فعل يطلب البركة شرك أكبر، نسأل الله العافية، نعم. إنما يشرع تقبيل الحجر الأسود، يقبل الحجر، يستلمه، يقبله، هذا سنة فعله النبي ﷺ وهكذا الركن اليماني يستلمه بيده، ويقول: باسم الله، والله أكبر، ولا يقبله، لما قبل عمر الحجر  قال: «إني أعلم أنك حجر لا تضر ولا تنفع، ولولا أني رأيت النبي ﷺ يقبلك ما قبلتك».  فنحن نقبله تأسيًا بالنبي ﷺ ولا نطلب البركة من الحجر، إنما تأسيًا بالنبي ﷺ واقتداءً به، وعملًا بسنته؛ لقوله ﷺ: خذوا عني مناسككم ولقوله: صلوا كما رأيتموني أصلي فنصلي كما صلى، ونحج كما حج -عليه الصلاة والسلام- ولا نتمسح بمقام إبراهيم، ولا بالجدران، ولا بالشبابيك ولا بالكسوة، كل هذا لا أصل له، من البدع.  أما الملتزم كونه يقف في الملتزم هذه عبادة ... على وجهه، وقصد هذا الملتزم بين الركن والباب هذا عبادة لله، ما هو بطلب من الكعبة، ولا تبرك بها، بل خضوع لله عند الباب، وهكذا في داخل الكعبة إذا طاف في نواحيها، وكبر في نواحيها، أو التزمها، جعل صدره عليها، ويديه، ودعا كما فعل النبي ﷺ كل هذا لا بأس به، هذا من باب التعبد، والتقرب إلى الله -جل وعلا- نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11794/حكم-التمسح-بالكعبة-وكسوتها-وغير-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51805.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":13644,"question":"في آخر أسئلة هذه السائلة (ع .م. ع) تقول: ما هي صفة العمرة؟","title":"صفة العمرة","answer":"الجواب: العمرة إن كان في مكة يخرج إلى الحل؛ إلى التنعيم، أو إلى عرفة، أو إلى الجعرانة، ونحوها إلى الحل يعني، ثم يلبي بالعمرة، ينويها بقلبه ويقول: (اللهم لبيك عمرة) ثم يدخل ويطوف بالبيت سبعة أشواط، ويصلي ركعتين، ثم يسعى بين الصفا والمروة سبعة أشواط، يبدأ بالصفا ويختم بالمروة، ثم يقصر من شعره، أو يحلق، هذه العمرة، والمرأة تقصر فقط. وإن كان بعيدًا.... ليس في مكة، فيلبي من مكانه، إذا كان داخل الحدود، داخل حدود المواقيت، كأهل، أم السلم، أو ..... أو جدة يحرم من مكانه من بيته، لقوله ﷺ لما حد الحدود، قال: ومن كان دون ذلك فمهله من أهله يحرم من جدة، من أم السلم، من..... يحرم للعمرة، يقول: اللهم لبيك عمرة وينويها بقلبه، ويلبي: لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك يلبي في الطريق حتى يصل المسجد، ثم يقدم رجله اليمنى عند الدخول، ويقول: باسم الله، والصلاة والسلام على رسول الله، اللهم افتح لي أبواب رحمتك، أعوذ بالله العظيم وبوجهه الكريم، وسلطانه القديم من الشيطان الرجيم مثل بقية المساجد. ثم يطوف، ويسعى، ويقصر، هذه العمرة، يطوف سبعة أشواط بالبيت، ويصلي ركعتين خلف المقام، أو في أي بقعة من المسجد الحرام، ثم يسعى سبعة أشواط، يبدأ بالصفا، ويختم بالمروة، ويدعو في سعيه، ويكبر عند الإحرام، يقول: الله أكبر، ويقبل الحجر الأسود، أو يستلمه بيده، ويقبلها، أو بالعصا، ويقبل طرف العصا، فإن لم يتيسر أشار إليه وكبر، وهكذا كلما مر عليه، سبعة أشواط. والأفضل في آخر كل شوط يقول: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201] وإذا أتى على الركن اليماني استلمه بيمينه، قال: باسم الله والله أكبر، إذا تيسر، فإن كان زحمة مضى، ولم يستلم، ولم يزاحم، ولم يقل شيئًا عند الركن اليماني، فإذا وصل الحجر الأسود استلمه، وقبله إن تيسر، فإن لم يتيسر؛ استلمه بيده، وقبل يده، أو بالعصا، وقبل طرفها، فإن لم يتيسر ذلك؛ أشار من بعيد وكبر. كل هذا فعله النبي -عليه الصلاة والسلام- حتى يكمل سبعة أشواط، يدعو فيها في كل شوط.. يذكر الله.. يدعو.. يصلي على النبي ﷺ حتى يكمل الأشواط السبعة، ويختم كل شوط من الطواف بقوله: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201] تأسيًا بالنبي ﷺ، هذا هو الأفضل.  ثم يصلي الركعتين خلف المقام إن تيسر، أو في أي بقعة من المسجد، ثم يقرأ فيهما بـ: قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1] وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] بعد الفاتحة، في الأولى: قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1] وفي الثانية: قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] بعد الفاتحة، ثم يذهب إلى الصفا، ويسعى سبعة أشواط، يبدأ بالصفا، ويقرأ عند البدأ: نبدأ بما بدأ الله به ويقرأ الآية: إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ [البقرة:158]  كما فعل النبي ﷺ ثم يرقاها، ويكبر الله، ويهلله، ويدعوه رافعًا يديه ثلاث مرات، يكررها ثلاث مرات رافعًا يديه، يحمد الله ويكبره، ويدعو، ويثني على الله ثلاث مرات، الله أكبر الله أكبر، لا إله إلا الله، الله أكبر الله أكبر ولله الحمد، لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا إله إلا الله وحده، أنجز وعده، ونصر عبده، وهزم الأحزاب وحده ويدعو بما تيسر من الدعاء، ثم يكرر الذكر والدعاء ثلاث مرات، هكذا السنة التي فعلها النبي ﷺ مستقبلًا القبلة، مستقبلًا الكعبة رافعًا يديه حين وقوفه على الصفا. وهكذا على المروة، على المروة مثلما فعل على الصفا، يفعل مثل فعله على الصفا، ويذكر الله في الطريق في أشواطه، يذكر الله، ويدعو في طريقه بين الصفا والمروة، حتى يكمل السبعة، يبدأ بالصفا، ويختم بالمروة، ويحمد الله، ويكبره، ويهلله، ويدعو ثلاث مرات على الصفا، وعلى المروة، في البدء والنهاية، في أول السعي، وفي آخر السعي حتى ينتهي بالمروة، ويقول على المروة عند النهاية مثلما قال على الصفا عند البدء سواء سواء. وهكذا في الطواف يبدأ بالتكبير، ويختم بالتكبير؛ الشوط السابع، يقول: (الله أكبر) عند البدء، وهكذا عند النهاية، يختم يكبر، ثم ينتهي، هكذا فعل النبي -عليه الصلاة والسلام-ويدعو في الطواف، والسعي ما يسر الله من الدعاء، والذكر والتكبير، والثناء على الله؛ لأن الطواف، والسعي، ورمي الجمار، شرعهن الله لإقامة ذكره، كما جاء في الحديث، إنما شرع الطواف والسعي ورمي الجمار لإقامة ذكر الله. المقدم: باقي الحلق، والتقصير، يا شيخ؟ الشيخ: نعم؟ المقدم: الحلق، والتقصير؟ الشيخ: ... في الحج والعمرة، يحلق ويقصر الرجل، إما حلقًا، وإما تقصيرًا، لكن الأفضل في العمرة التقصير، حتى يتوفر الحلق للحج إذا أتى بعمرة في ذي القعدة، أو في أول ذي الحجة، فالأفضل التقصير حتى يتوفر الحلق للحج. أما المرأة فليس لها إلا التقصير في عمرتها وحجتها؛ لأن الرأس من جمالها، فمشروع لها أن تقصر في الحج والعمرة، وليس لها أن تحلق، بل تقصر بعض الشيء من أطرافه ... في حجها، وفي عمرتها، وهذا تمام العمرة، العمرة تتم بالتقصير، أو الحلق، فالرجل يحلق، أو يقصر، والأفضل التقصير في حق الرجل إذا كان في أيام الحج؛ حتى يكون الحلق للحج، وأما المرأة فالسنة لها التقصير، ليس لها أن تحلق في حجها وعمرتها. وأما في الحج فإنه إذا رمى الجمرة يحلق، أو يقصر يوم العيد، هذا هو الأفضل، والمرأة إذا رمت تقصر، ولا تحلق، ويكون الطواف هو الأخير، وإذا كان عليه سعي يبقى السعي مع الطواف بعد ذلك، إما في يوم النحر، أو بعد ذلك، إن طاف في يوم النحر هذا أفضل، ويسعى، وإن لم يتيسر لأجل الزحام، وأخره؛ فلا بأس، يؤخر الطواف والسعي، وقد حل التحلل الأول، يلبس المخيط، يكشف[1] رأسه، يتطيّب، فإذا تيسر الطواف في اليوم الثاني.. في الثالث.. في الرابع.. بعد ذلك؛ طاف وسعى إذا كان متمتعًا أو مفردًا أو قارنًا، ولم يسع مع طواف القدوم؛ يسعى مع طواف الحج. أما إن كان سعى مع طواف القدوم وهو قارن أو مفرد؛ كفاه السعي الأول، أما المتمتع فإنه يسعى لعمرته، ويقصر ويحل، ثم يسعى أيام الحج لحجه. نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11982/صفة-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_542/54212.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":14133,"question":"هذه رسالة وردتنا من الرياض من شخص رمز إلى اسمه بـ (س. م. د) يقول: تركت واجبًا في حج هذا العام ولا أستطيع ذبح شاة في هذا المقام، أرجو إفتائي هل يجوز لي أن أصوم أم لا -وفقكم الله- بدلًا من الشاة؟","title":"حكم من ترك واجبًا في الحج ولم يستطع ذبح شاة","answer":"الجواب: إذا عجز المؤمن عن الصيام الذي وجب عليه إذا عجز عن الشاة التي وجبت عليه بسبب ترك الواجب مثل من تجاوز الميقات وأحرم من غير الميقات، هذا عليه دم، فإذا عجز عن ذلك صام عشرة أيام، مثل هدي التمتع والقران، إن صامها في مكة أجزأته وإن صام ثلاثة أيام منها في الحج قبل عرفة فحسن وسبعة إذا وصل إلى أهله، وإن أخرها كلها إلى أن يصل إلى أهله وصامها هناك فلا بأس، وإن قدر على الهدي ثم بعث به إلى مكة قبل أن يصوم، ويذبح في مكة أجزأه والحمد لله، فهو على سعة من الأمر، إن تيسر له الهدي وجب عليه الهدي، وإن عجز وجب عليه الصوم، فإن لم يتيسر له الصوم لشدة حر مكة أو لمرض أو أشباه ذلك؛ أخره إلى هناك ثم صام هناك، وإن تيسر أن يقدم ثلاثًا في الحج قياسًا على هدي التمتع والقران يصومها هنا، فهذا حسن، وفيه احتياط، وسبعة إذا رجع إلى أهله، ولكن لو أنه وجد الهدي بعد ذلك قبل أن يصوم وجد الهدي تيسر له الهدي، وبعثه إلى مكة أجزأه عن الصوم والحمد لله. نعم.\nولا هو شرط أن يبعثها إلى مكة يعني: يوكل من يشتري في مكة ويذبح إذا وكل ثقة يشتري في مكة ويذبح عنه هذا هو المطلوب. نعم.\nالمقدم: لكن إذا صام لا يقدم شيئًا؟\nالشيخ: نعم إذا صام يجزيه أجزأه الصوم.","link":"https://binbaz.org.sa/fatwas/12571/حكم-من-ترك-واجبا-في-الحج-ولم-يستطع-ذبح-شاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_646/nour_64602.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":15023,"question":"هذه الرسالة وردتنا من علي سالم يقول: من طرف علي سالم من جدة تصلكم هذه الرسالة، مهنئًا لكم فيها بسلامة حج هذا العام، ومباركًا لكم بالعام الجديد، وراجيًا أن تجيبونا على بعض هذه الأسئلة، حيث وقع لنا شك فيها، يقول: ما هو الراجح لأهل مكة بالنسبة للصلاة في عرفة ومزدلفة ومنى؟","title":"حكم الجمع والقصر لأهل مكة في عرفة ومنى والمزدلفة","answer":"الجواب: النبي ﷺ صلى بالناس في عرفات وفي مزدلفة وفي منى قصرًا، ركعتين ركعتين، الظهر والعصر والعشاء، ومعه أهل مكة وغيرهم، ولم يأمرهم بالإتمام، فدل ذلك على أن أهل مكة مع الناس، سواء سمينا الخروج إلى منى وعرفات سفرًا، أو لم نسمه سفرًا، سواء سميناه سفرًا، أم لم نسمه سفرًا، فإنهم يقصرون مع الحجيج، وهكذا جمع النبي ﷺ في عرفات وفي مزدلفة، بين الظهر والعصر في عرفة، والمغرب والعشاء في مزدلفة، والناس معه، ولم يقل: يا أهل مكة أتموا، ولم يقل لهم: لا تجمعوا، فدل ذلك على أنه لا حرج عليهم في الجمع والقصر. وهذا هو المختار، وهو الأرجح من أقوال أهل العلم في هذه المسألة، نعم.","link":"https://binbaz.org.sa/fatwas/13528/حكم-الجمع-والقصر-لاهل-مكة-في-عرفة-ومنى-والمزدلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_653/nour_65304.mp3","categories":["أحكام الجمع","مسائل متفرقة في الحج والعمرة"]},{"id":15146,"question":"من جمهورية مصر العربية السائل يقول: هل شرب الدخان في الحج والإنسان محرم يفسد في ذلك الحج ولا تقبل؟","title":"هل شرب الدخان يفسد الحج؟","answer":"الجواب: شرب الدخان ما يجوز، وفيه مضار كثيرة، لا يجوز شربه، لا في الحج، ولا في غيره، يجب تركه، ولكن شربه بالحج وفي العمرة لا يبطل العمرة، لكن نقص، نقص في الثواب، وإلا الحج صحيح، والعمرة صحيحة، ولو كان يشرب الدخان، لكن الواجب ترك التدخين، كما يجب ترك شرب المسكرات والمخدرات، يجب على المؤمن أن يحذر المخدرات والمسكرات والتدخين جميعًا؛ لأن الله حرم ذلك، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13644/هل-شرب-الدخان-يفسد-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56413.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":15189,"question":"أحد الإخوة المستمعين صالح الشرقي المري، بعث يسأل، ويقول: لقد أديت فريضة الحج، وأنا في سن العشرين، ولم أتزوج بعد، وبعدما أديت الفريضة ارتكبت بعض المعاصي، ومنها كبائر الذنوب -كما يقول- فهل بطل حجي؟","title":"حكم حج من ارتكب الكبائر بعد حجه","answer":"الجواب: حجك صحيح، والحمد لله، إذا كنت أديت ما شرع الله لك، حجك صحيح، والمعاصي ما تبطله بعد ذلك، حتى لو ارتد الإنسان، لو كفر ما يبطل حجه إلا إذا مات على الكفر، لو ارتد، ثم هداه الله، ورجع إلى الإسلام، بقي له عمله السابق؛ لأن الله شرط للردة أن يموت عليها فَيَمُتْ وَهُوَ كَافِرٌ [البقرة:217].  أما إذا هداه الله ورجع إلى الإسلام، أعماله تبقى له. فهكذا المعصية من باب أولى، المعصية لا تحبط الحج، فلو حججت، وصمت رمضان، وصليت الصلوات، ثم بعد ذلك حصل منك زنا، أو شرب مسكر، أو عقوق لوالديك، أو أكل ربا، هذا لا يبطل أعمالك، المعصية فيها الإثم، وعليك إثمها، ولكن لا تبطل بها الأعمال السابقة، الأعمال على حالها، لكن يضعف إيمانك، المعاصي تضعف الإيمان، تنقص الإيمان، وتسبب غضب الله ، لكن ما تبطل طاعتك الماضية، ولكن تنقص أجورها تضعفها. إلا من استحلها استحل الزنا، رآه حلال، استحل الزنا، وهو يعرف أنه حرام واستحله بين المسلمين، يعرف أن الزنا حلال أو استحل الخمر يكون مرتد عن الإسلام، فإذا مات على ذلك بطل حجه وعبادته كلها، كما قال سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ[الأنعام:88] وقال سبحانه: وَمَنْ يَكْفُرْ بِالإِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ وَهُوَ فِي الآخِرَةِ مِنَ الْخَاسِرِينَ [المائدة:5]. فالذي يرتد عن دينه إذا مات على الردة بطلت أعماله، ومن ذلك من يستحل الزنا، أو الخمر، أو العقوق، يقول: إنه حلال، وقد فهم السنة، وفهم الدليل فهذا يكون كافرًا ومرتدًا عن الإسلام نعوذ بالله، إذا مات على هذا تبطل أعماله، نسأل الله العافية، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/13679/حكم-حج-من-ارتكب-الكباىر-بعد-حجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_496/49604.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":15344,"question":"السائل (محمد .أ) يقول: حجيت حجة الإسلام، ولكنني لا أعرف كثيرًا عن المناسك، وكنت أعمل مثل رفاقي في الحج، فهل يؤثر ذلك على حجي؛ لأن النية قد تكون غير موجودة. مع العلم: بأنني حجيت عدة مرات، بعدما تعلمت المناسك، لكن الفريضة هل هي صحيحة، مع أنها قد تكون ناقصة، سماحة الشيخ؟","title":"حكم حج المقلد للحجاج","answer":"الجواب: الحمد لله، الأصل الصحة، والحمد لله، ولو كان عندك بعض...، ما دام فعلت ما يفعله الحجاج، والحمد لله، نعم، ودع عنك الوساوس، نعم.\nثم لو قدر أن الحج الأول لم يكمل، فقد جاء بعده حجات، والحمد لله، كل واحدة تكفي. المقصود: أن الحج الأول أدى به الفريضة، والبقية نوافل، ولا تنبغي للمؤمن الوسوسة التي تؤذيه، وتغضب الله، وترضي الشيطان، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13845/حكم-حج-المقلد-للحجاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56618.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":15346,"question":"هل من توجيه كريم -سماحة الشيخ- للذين قد يؤدون مناسك الحج سؤال أهل العلم والعلماء وأهل الذكر؟","title":"توجيه للحجاج بسؤال أهل العلم عما يجهلونه","answer":"الجواب: نعم، الواجب على كل مؤمن ومؤمنة السؤال عما أشكل عليه في الحج وغيره، في حجه، في صلاته، في زكاته، في صيامه، في معاملاته يسأل، الله يقول سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] ويروى عنه -عليه الصلاة والسلام- أنه قال: ألا سألوا إذ لم يعلموا؟ إنما شفاء العي السؤال فالواجب على من جهل أن يسأل في صلاته، في صومه، في حجه، في جهاده، في زكاته، في معاملاته، لا يجوز السكوت والسير على الجهل، بل يجب أن يسأل أهل العلم، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13847/توجيه-للحجاج-بسوال-اهل-العلم-عما-يجهلونه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56619.mp3","categories":["مسائل متفرقة في الحج والعمرة","العالم والمتعلم"]},{"id":15465,"question":"هذا سائل من سوريا أبو مراد، يقول: كيف يكون الحج المبرور يا سماحة الشيخ؟","title":"كيفية الحج المبرور","answer":"الجواب: مثلما في الحديث، يقول ﷺ: من حج فلم يرفث ولم يفسق رجع كيوم ولدته أمه هذا الحج المبرور، الذي معه التوبة الصادقة، ليس معه فسق ولا رفث، هذا الحج المبرور، الذي قد سلم من الإصرار على المعاصي، ولم يأت الرفث -وهو الجماع- لم يفسد حجه بالجماع، وهو الرفث. المقصود: أن الحج المبرور هو الذي يحج وهو غير مصر على السيئات، قد تاب إلى الله منها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13988/كيفية-الحج-المبرور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56814.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":15636,"question":"السائلة (آمنة . خ. خ) من المدينة النبوية، تقول: هل يجوز للرجل أن يترك زوجته في المنزل ويذهب للحج أو العمرة دون أن يصطحب معه الزوجة؟","title":"حكم سفر الرجل للحج دون اصطحاب زوجته","answer":"الجواب: نعم، يجوز له أن يدعها في البيت، ويذهب للحج، أو العمرة، أو للصلاة، أو للجهاد، أو لحاجاته الخاصة في التجارة؛ لا بأس بذلك، وإذا كانت تستوحش يجعل عندها من الخدم من يؤنسها، أو يسمح لها تذهب إلى أهلها عند أهلها للوحشة التي تصيبها، أو إذا كان عليها خطر تذهب عند أهلها، أو يكون عندها من أهلها من يؤنسها يجمع بين المصلحتين، إذا كان عندها من يؤنسها مثل بنات وأخوات فالحمد لله، إذا كان ما عندها من يؤنسها يكون عندها خادمة أو خادمات للأنس، أو تذهب إلى أهلها حتى تبقى عندهم إلى أن يرجع.  ولا يلزمه أن يذهب معها كلما سافر، له أن يسافر للحج أو للعمرة أو للتجارة، وما أشبه ذلك، وتبقى في البيت هي، لكن مثلما تقدم: إذا كانت تستوحش يجعل عندها ما يزيل وحشتها من الخادمات، أو تذهب إلى أهلها، وإذا كان عندها بنات كبيرات أو أخوات زالت الوحشة، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/14177/حكم-سفر-الرجل-للحج-دون-اصطحاب-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57118.mp3","categories":["مسائل متفرقة في الحج والعمرة","الحقوق الزوجية"]},{"id":15830,"question":"في ثاني أسئلة هذه السائلة من جدة أم محمود تقول: سماحة الشيخ لقد قلت في النية: بأنني سوف أعمل عمرة لجدي المتوفى، وفي نيتي أنها ستكون أول عمرة أعملها بعد أن قلت ذلك، ولكنني بعد ذلك أديت عمرة لنفسي، مع العلم بأنني اعتمرت قبل ذلك، ثم نويت الحج متمتعة، فأديت عمرة أخرى وحج، والحمد لله، ولم تكن عندي فرصة لأداء عمرة لجدي قبل الحج، ولم أؤديها إلى الآن، فهل حجي صحيح؟ وماذا يلزمني؟","title":"حكم من نوت أن تعتمر عن جدها ثم لم تف","answer":"الجواب: نعم، حجك صحيح، والعمرة صحيحة، والحمد لله؛ لأن هذا ليس بنذر، هذا نية، فليس عليك شيء متى تيسرت العمرة لجدك فلا بأس، وإلا العمرة التي فعلت صحيحة، والحج صحيح، والحمد لله؛ لأن هذا ليس بنذر، نية، مجرد نية، نعم. المقدم: أحسن الله إليكم يا شيخ.","link":"https://binbaz.org.sa/fatwas/14419/حكم-من-نوت-ان-تعتمر-عن-جدها-ثم-لم-تف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57522.mp3","categories":["مسائل متفرقة في الحج والعمرة","اللباس والزينة","قضايا المرأة"]},{"id":15905,"question":"هذا السائل أبو عبدالله يقول: ما حكم من حلق يوم عيد الأضحى قبل ذهابه للصلاة، علمًا بأنه نصح عن ذلك في الحج؟","title":"الحجاج ليس عليهم صلاة العيد","answer":"الجواب: هذا فيه تفصيل: إن كان في الحج، هذا إذا رمى الجمرة شرع له الحلق، ما لهم صلاة أهل منى، ما لهم صلاة، صلاتهم رمي الجمار، ما عندهم صلاة، يرمي الجمرة، ثم يحلق أفضل، ولو حلق قبل الرمي أجزأ، ولا بأس، النبي ﷺ سئل عن ذلك فقال ﷺ: لا حرج، لا حرج سئل يوم العيد عمن قدم وأخر، فقال: لا حرج -عليه الصلاة والسلام-.\nلكن السنة أن يرمي، ثم ينحر، ثم يحلق أو يقصر، والحلق أفضل، ثم الطواف يكون هو الأخير، طواف الإفاضة، لكن لو قدم بعضها على بعض فلا حرج، وليس لهم صلاة يوم العيد، صلاتهم يقوم مقامها رمي الجمار، نعم.","link":"https://binbaz.org.sa/fatwas/14496/الحجاج-ليس-عليهم-صلاة-العيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57705.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":16170,"question":"تسأل سماحتكم -لو تكرمتم- عن المرأة إذا حاضت وهي في الحرم ماذا تفعل؟ في الحج؟","title":"ما تفعل المرأة الحائض في الحج؟","answer":"الجواب: إذا حاضت فيها تفصيل، إذا كانت حاضت بعد الطواف، طواف الإفاضة؛ حجها تام، وليس عليها طواف وداع، إذا سافرت من مكة، وبها حيض، أو نفاس يسقط عنها طواف الوداع. أما إذا حاضت قبل أن تطوف طواف الإفاضة؛ فإنها تبقى حتى تطوف للإفاضة، تبقى في مكة حتى تكمل حجها بالطواف، ولا يضرها كونها تقف بعرفة وهي حائض أو نفساء، أو ترمي الجمار وهي حائض؛ لا يضرها ذلك، أو تبيت في مزدلفة وفي منى كذلك. إنما الحيض يمنع الطواف فقط، أما بقية أعمال الحج فلها أن تفعلها وهي حائض، أو نفساء والحمد لله، لكن لا تطوف؛ لأنه صلاة،  الطواف لا تطوف حتى تطهر، ولكن يسقط عنها طواف الوداع، إذا صادفها الحيض عند السفر؛ فإنه يسقط عنها طواف الوداع؛ لقول ابن عباس -رضي الله عنهما-: \"أمر الناس أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض\" والنفساء في حكمها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14839/ما-تفعل-المراة-الحاىض-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_805/nour_80503.mp3","categories":["مسائل متفرقة في الحج والعمرة","الحيض والنفاس","قضايا المرأة"]},{"id":16171,"question":"لها بعض الأسئلة عن الحج أيضًا، تقول: ما هي فرائض الحج على أتم وجه حتى يقبلها الله ؟","title":"أركان الحج وواجباته","answer":"الجواب: الحج له أركان، وله واجبات، وله أشياء مشروعة موضحة في المناسك التي كتبها أهل العلم، وقد كتبنا منسكًا مختصرًا سميناه \"التحقيق، والإيضاح لكثير من مسائل الحج والعمرة والزيارة\" لعلك تحصلين عليه من بعض الإخوان عندك في القصيم، وفيه بيان أركان الحج، وواجباته، وما شرع الله في ذلك، وهو كتاب -بحمد الله- مختصر، وفيه الفائدة المطلوبة. وأركان الحج أربعة: الإحرام بالحج في القلب كونه ينوي الحج، والواجب أن يكون من الميقات الذي يمر عليه، والوقوف بعرفة، وطواف الزيارة، يعني: طواف الإفاضة، والسعي، هذه أربعة أركان للحج. وله واجبات سبعة بينها العلماء، وهي مذكورة في المنسك، وهي المناسك، أولها: الإحرام من الميقات الذي يمر عليه الإنسان، فالذي جاء من مصر يحرم من ميقات مصر من الجحفة، يعني: رابغ، والذي من المدينة يحرم من ميقات المدينة، والذي من نجد يحرم من ميقات أهل نجد، والذي يأتي من اليمن يحرم من ميقات اليمن، كل إنسان يحرم من ميقات بلده، يجب عليه إذا مر عليه بنية الحج أن يحرم من الميقات، أو بنية العمرة كذلك. الثاني: كونه يقف بمزدلفة بعد انصرافه من عرفات يبيت فيها. والثالث: المبيت بمنى ليلة إحدى عشرة، واثنا عشرة لمن تعجل، والليلة الثالثة لمن لم يتعجل ليلة إحدى عشرة، واثنا عشرة، وثلاث عشرة. والرابع: رمي الجمار، هذا من واجبات الحج. والخامس: الحلق، أو التقصير للرجل، أو التقصير للمرأة، الحلق للرجل، أو التقصير مخير، والمرأة ليس لها إلا التقصير. والسادس: طواف الوداع، لابد من كون الإنسان إذا فرغ من حجه يطوف للوداع عند سفره إلى بلاده. والسابع: الوقوف بعرفة إلى الغروب، وإنه إذا وقف بعرفه نهارًا؛ يكمل إلى الغروب، هذا السابع، أما إن وقف في الليل؛ كفاه الوقوف بالليل، والحمد لله، لكن إذا وقف نهارًا؛ يلزمه أن يكمل إلى الغروب. فهي سبعة واجبات من ترك شيئًا منها وجب عليه دم إلا أن يكون له عذر شرعي، وهذا مبسوط في كتب المناسك وموضح. وهناك أشياء مشروعة للحاج من تلبية، من حين يحرم يلبي، والإكثار من ذكر الله  والإكثار من الطواف إذا تيسر ذلك، وكل ما يتعلق بالمسائل الشرعية التي ينتهزها الحاج، أو المعتمر، مثل الصدقات على الفقراء، والمساكين، مثل الإكثار من قراءة القرآن، إلى غير هذا من وجوه الخير التي يفعلها في الحرم الشريف، في مكة المكرمة، أو في المدينة إذا زار المدينة. هذه مكملات وفيها فضل، لكن الواجبات مثلما بينا لك، والأركان كذلك، ومتى تيسر لك المنسك الذي ذكرنا التحقيق والإيضاح؛ وجدت فيه -إن شاء الله- المطلوب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14833/اركان-الحج-وواجباته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_805/nour_80502.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":16239,"question":"يسأل ويقول: هل لأهل مكة عمرة؟ وإذا كان معنى العمرة عند علماء اللغة الزيارة، وشرعًا التعبد لله تعالى بأداء مناسك العمرة، فكيف يحدث هذا وهم من أهل مكة؟ جزاكم الله خيرًا.","title":"صفة العمرة لمن كان من أهل مكة","answer":"الجواب: العمرة هي الزيارة بالنسبة إلى الغريب، أما أهل مكة فالعمرة لهم هي الطواف، والسعي، والتقصير، وهي نوع من الزيارة بخروجه إلى الحل، ثم رجوعه، لكن المقصود منها في حق أهل مكة هذا العمل العظيم، وهو الطواف، والسعي، والتقصير، فلهم عمرة يخرجون إلى الحل التنعيم، أو عرفات، أو الجعرانة، أو جدة، ويحرمون بالعمرة، ثم يدخلون، ويطوفون، ويسعون، ويقصرون، وتسمى عمرة، وإن كان أصلها الزيارة بالنسبة إلى الغريب، لكنها عمل عظيم عمل. الطواف، والسعي، والتقصير، أو الحلق، هذه عبادة عظيمة، فيها الطواف بالبيت، وفيها السعي بين الصفا والمروة، فهي عمرة لهم وإن كانوا من أهل مكة، وليس له زيارة؛ لأنهم قريبون من مكة إذا خرجوا إلى التنعيم، ليسوا بعيدين، وليس سفرًا، فلا تتحقق في حقهم أنها زيارة، لكن فيها العمل الصالح، فيها الطواف والسعي، ولكنها تسمى زيارة بالنسبة إلى الغرباء. وقد اعتمرت عائشة من مكة -رضي الله عنها- لما حلت من حجها، أعمرها النبي ﷺ إلى التنعيم، وهي في هذه الحال مكية مقيمة في مكة، ومع هذا اعتمرت من التنعيم -رضي الله عنها- بدلًا من عمرتها التي دخلت بها إلى مكة من المدينة، لأنها دخلت مكة وهي حائض، فلم تطف، ولم تسع قبل الحج، وأحرمت بالحج مع العمرة، صارت قارنة، فقال لها النبي ﷺ: طوافك بالبيت وبين الصفا والمروة يكفيك لحجك وعمرتك لأنها صارت قارنة، فطلبت منه عمرة مستقلة، فوافق على ذلك -عليه الصلاة والسلام- وأمر أخاها عبدالرحمن أن يعمرها من التنعيم عمرة مستقلة كصواحباتها من أزواج النبي ﷺ. فإنهم اعتمروا عمرة مستقلة، دخلوا بها مكة من المدينة، فطافوا، وسعوا، وقصروا، وحلوا، فأحبت أن تفعل مثلهم .. عمرة مستقلة، فأقرها النبي ﷺ وأمر أخاها عبدالرحمن أن يذهب بها إلى التنعيم؛ فاعتمرت بعد الحج. فدل ذلك على أنه لا بأس بخروج المكي إلى التنعيم، أو غيره من الحل لأخذ العمرة، فالعمرة عمل صالح، وقربة إلى الله  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14941/صفة-العمرة-لمن-كان-من-اهل-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80710.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":16456,"question":"سؤاله الثاني يقول يا سماحة الشيخ: حجيت في أحد الأعوام الماضية أنا وزوجتي وفي اليوم العاشر، والحادي عشر رجمت، ورجمت زوجتي معي، ثم وكلت عن اليوم الثاني عشر عني وعن زوجتي، وقمت بطواف الوداع في اليوم الحادي عشر، وخرجت من مكة قبل الغروب، وذلك السبب؛ لأنه كان معي طفلة صغيرة، وقد تعبت تعبًا شديدًا من الحر، ولم تأكل، ولم ترضع، وكانت تبكي كثيرًا مما اضطررنا لفعل ذلك، ماذا يجب علينا؟","title":"حكم من طاف للوداع يوم الحادي عشر وخرج من مكة","answer":"الجواب: يجب عليك أنت ثلاث ذبائح؛ إحداها عن ترك الرمي؛ لأنه ليس لك التوكيل، والثانية عن ترك طواف الوداع؛ لأنك لم تطف للوداع، والثالثة عن ترك المبيت ليلة اثنا عشر، وإن لم تذبح لليلة اثنا عشر، وتصدقت؛ كفى -إن شاء الله- لكن ذبيحة أفضل تكون ثالثة، الأولى عن ترك الرمي؛ لأن ليس لك عذر، ترك الرمي في الثاني عشر، والطفل تحفظه أمه، تولاه أمه، وعليك الذبيحة الثانية عن ترك الوداع؛ لأن الوداع يكون بعد الرمي، بعد مضي أيام منى، بعد الرمي كله، وإذا ذبحت ذبيحة ثالثة عن ترك ليلة الثاني عشر، عن ترك المبيت ليلة اثني عشر؛ كان أفضل وأحوط. أما هي فعليها ذبيحة واحدة عن ترك الوداع، وتوكيلها صحيح؛ لأن لها عذرًا في الطفل الذي يشغلها عن الرمي، ولا يمكنها الرمي مع وجود الطفل، لكن عليها ذبيحة عن ترك الوداع، وعن ترك المبيت، ذبيحة ثانية أفضل؛ لأنها لم تبت في الليلة الثانية عشر، لو ذبحت عنها يكون أفضل، وإن تصدقت بشيء؛ كفى والحمد لله -نسأل الله للجميع التوفيق- نعم، والذبيحة تكون في مكة، تذبح الذبائح في مكة للفقراء. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15164/حكم-من-طاف-للوداع-يوم-الحادي-عشر-وخرج-من-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58205.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":16724,"question":"يقول هذا السائل: يعتقد كثير من الحجاج يا سماحة الشيخ أن من تمام الحج وكماله زيارة المسجد النبوي الشريف، وإن لم يزره؛ لم يكن قد حجًا.","title":"ما حكم زيارة الحاج للمسجد النبوي؟","answer":"الجواب: هذا غلط، ليس من شرط الحج، ولا من واجباته، ولا سنته زيارة المدينة، المدينة مستقلة، زيارة المدينة سنة مستقلة، يستحب زيارة المدينة، والمسجد النبوي، والسلام على النبي ﷺ من بلده رأسًا إلى المدينة ولو ما جاء للحج إذا كان قد حج. المقصود: أن زيارة المسجد النبوي ليس مربوطًا زيارته بالحج، لكن الغالب على أن الناس إذا جاؤوا للحج؛ سهل عليهم زيارة المسجد النبوي، وإلا فليس شرطًا، لو حج وذهب إلى وطنه فلا نقص عليه والحمد لله، لكن إذا زار المسجد النبوي يكون أفضل؛ لأن الرسول ﷺ قال: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى. فالسنة زيارة المسجد النبوي إذا تيسر ذلك، وإذا زار المسجد؛ صلى فيه وسلم على النبي ﷺ وعلى صاحبيه -رضي الله عنهما- وسلم على أهل البقيع، وعلى الشهداء، واستحب له أن يزور مسجد قباء أيضًا، ويصلي فيه، كل هذا سنة، لكن ما هو بشرط في الحج، لو في غير الحج، لو جاء بشهر مستقل، وإذا جاء للحج، ثم زار المدينة خير إلى خير. المقدم: حفظكم الله، سماحة الشيخ! لكن ألا ترون أن بعض العلماء الذين صنفوا في كتب المناسك يختمون، أو يكتبون بفضل زيارة المسجد النبوي، ألا ترون يا سماحة الشيخ أن هذا من أسباب فهم الحجاج..؟ الشيخ: لأن هذا أسهل على الناس، إذا جاؤوا للحج من الشام أو من اليمن، أو من جهات بعيدة أسهل عليهم يزورون المدينة؛ لأن قصد المدينة بسفر مستقل قد لا يتيسر لهم، لكن إذا جاؤوا إلى الحج كانت زيارة المسجد النبوي أيسر، ولهذا ذكر العلماء الزيارة في الحج في أبواب الحج في كتاب الحج، لأجل أن الزيارة أسهل على الحجاج، إذا جاؤوا إلى مكة ما بقي عليهم إلا مسافة قصيرة، ويأتون إلى المسجد النبوي، هذا السبب، وإلا ما هو ليس مربوطًا بالحج، زيارة المسجد النبوي غير مربوطة بالحج، لو زار زيارة مستقلة ليس مع الحج فهو سنة مستقلة، نعم. أما حديث: \"من حج فلم يزرني فقد جفاني\" حديث ضعيف غير صحيح، موضوع، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15468/ما-حكم-زيارة-الحاج-للمسجد-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58427.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":16898,"question":"من بريدة في القصيم، المستمع حمد بن أحمد العياف رسالة، وضمنها جمعًا من الأسئلة في أحد أسئلته، يقول: أديت فريضة الحج، وأكملت الحج تمامًا -ولله الحمد- وعند عودتي شعرت بأني لم أكمل الحج في الوجه المطلوب؛ علمًا بأني أديت مناسك الحج، والعمرة بالشكل المطلوب، وجهوني حول هذه الخواطر، جزاكم الله خيرًا.","title":"حكم الشك في العبادة بعد الفراغ منها","answer":"الجواب: هذه الخواطر من الشيطان فلا تلتفت إليها، والشكوك التي تقع بعد الفراغ من العبادة لا يعول عليها، ولا يلتفت إليها، وأنت -بحمد الله- قد أديت ما عليك، وقد عرفت ذلك، فهذه الشكوك والأوهام كلها من الشيطان، فالواجب اطراحها، وعدم الالتفات إليها، والتعوذ بالله من الشيطان الرجيم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15655/حكم-الشك-في-العبادة-بعد-الفراغ-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76513.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":16930,"question":"بعض الحجاج يرى أن على المسلم أن يحج على الأنساك الثلاثة، بمعنى: أن يحج مرةً متمتعًا، ومرةً قارنًا، ومرةً مفردًا، ما حكم هذا المعتقد؟","title":"حكم اعتقاد بأن على المسلم الحج بالأنساك الثلاثة","answer":"الجواب: لا أصل له، بل الصواب أن يحج متمتعًا دائمًا، هذا هو الأفضل، الأفضل أن يكون متمتعًا دائمًا كما أمر به النبي ﷺ الصحابة  وأرضاهم، ولما فيه من زيادة العمل والعبادة فيه الطواف، والسعي للعمرة، وفي الطواف السعي للحج، فيه التقصير للعمرة، وفيه التقصير للحج، أو الحلق، فهو أكثر عملًا، وهو الموافق لما أمر به النبي ﷺ أصحابه  وأرضاهم. لكن الأنساك، النسكان الآخران جائزان، الإفراد والقران جائزان، لكن القران تركه أفضل، إلا لمن ساق الهدي. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15731/حكم-اعتقاد-بان-على-المسلم-الحج-بالانساك-الثلاثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_827/nour_82708.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":16932,"question":"ننتقل إلى سؤال آخر من أسئلة أخينا (ع. ف. غ) يقول: يدور على ألسنة بعض المسلمين حديث يروونه عن الرسول ﷺ وهو: \"من حج، ولم يزرني؛ فقد جفاني\" ما صحة هذا الحديث؟ وما علاقة الزيارة بالحج؟ وما هي آداب الزيارة؟","title":"ما صحة: \"من حج ولم يزرني فقد جفاني\"، وما آداب الزيارة؟","answer":"الجواب: الحديث هذا موضوع عند أهل العلم كما نبه عليه شيخ الإسلام ابن تيمية -رحمه الله- والحافظ ابن عبدالهادي في كتابه الصارم المنكي في الرد على السبكي، فهو حديث باطل لا صحة له، وليست الزيارة واجبة إلى المدينة، ولا إلى النبي ﷺ حتى يكون من تركها جافيًا، لا، الزيارة للمسجد النبوي مستحبة إذا شد الرحل إلى المسجد، وصلى فيه، وصلى على النبي ﷺ وسلم عليه؛ هذا مستحب، وليس بواجب، ومن ترك هذا لا يسمى جافيًا. والزيارة الشرعية أن يشد الرحل إلى المسجد للصلاة فيه، والقراءة، والاعتكاف.. مما يشرع في المسجد، وإذا زار المدينة؛ سلم على النبي ﷺ على صاحبيه، مستحب له ذلك، وسلم على أهل البقيع، وعلى الشهداء في أحد كل هذا سنة، لكن لا يشد الرحل لأجل ذلك، شد الرحل لأجل زيارة المسجد، وهكذا يستحب له أن يزور مسجد قباء، ويصلي فيه ركعتين، كما كان النبي يزوره، عليه الصلاة والسلام. وهذه الزيارة ليس لها تعلق بالحج، بل يستحب زيارة المسجد مطلقًا للحاج، وغير الحاج، قبل الحج، وبعده سنة مستقلة، وظن بعض الحجاج أن لها صلة بالحج، لا أصل له، ولكن بعض الناس يأتي من مكان بعيد، لا يتيسر له الزيارة إلا مع الحج، فإذا جاء إلى الحج؛ زار المسجد؛ لأنه أيسر عليه من تجديد سفر جديد من بلاده، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15715/ما-صحة-من-حج-ولم-يزرني-فقد-جفاني-وما-اداب-الزيارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_827/nour_82702.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":16960,"question":"ما حكم تلقين الدعاء للناس في الطواف والسعي، وفي عرفة، والمزدلفة، وعند الجمرات، ولاسيما إذا كانوا في حاجة إلى ذلك؟","title":"ما حكم تلقين الناس الدعاء في المشاعر؟","answer":"الجواب: لا حرج في ذلك، كونه يلقن الدعاء طيب، لا حرج في ذلك، لكن إذا استطاع الإنسان أن يدعو بنفسه، ويذكر الله بنفسه، فهذا أكمل، وأخشع لقلبه، نعم. المقدم: ما حكم ما إذا دعا إنسان بالأدعية الصحيحة الواردة، ودعا الناس بدعائه، وهذا تلقين لهم؟ الشيخ: لا مانع من ذلك، لكن لا يكون بتحري صوتٍ واحد، لا، ولكن هذا يدعو، وهذا يدعو، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15753/ما-حكم-تلقين-الناس-الدعاء-في-المشاعر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82814.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":16971,"question":"هذا سائل يقول: سماحة الشيخ ما هي صفة حجة النبي ﷺ مختصرة؟ وما هي الكتب التي ترشدوننا بقراءتها في هذا المجال؟","title":"صفة حج النبي ﷺ","answer":"الجواب: قد بيناها، وبينها العلماء في كتب المناسك، وبيناها في كتابنا التحقيق والإيضاح، وهو كتاب مختصر، بينا فيه حجة النبي ﷺ من حين خرج من المدينة -عليه الصلاة والسلام- خرج من المدينة، وأحرم من الميقات -عليه الصلاة والسلام- ذي الحليفة بحج وعمرة، وقد ساق الهدي مائة من الإبل ثلاثة وستين من المدينة، وسبعة وثلاثين جاءت من اليمن، ولم يزل يلبي لما أحرم من ذي الحليفة، لم يزل يلبي: لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد، والنعمة لك والملك، لا شريك لك، في الطريق حتى وصل مكة. ثم طاف سبعة أشواط، وبدأ بالحجر الأسود، وقبله، واستلمه بيده، وقال: الله أكبر، وطاف سبعة أشواط -عليه الصلاة والسلام- ورمل في الثلاثة الأولى، يعني خب فيها، ومشى في الأربعة الأخيرة، ثم صلى ركعتين خلف المقام، ثم مر الحجر، واستلمه.  ثم ذهب إلى الصفا، وسعى سبعة أشواط يصعد الصفا، ويرفع يديه، ويوحد الله، ويكبره، ويدعو ثلاث مرات يكررها، ثم ينزل، ويمشي، فإذا جاء بطن الوادي سعى، رمل في بطن الوادي بين العلمين حتى يخرج من الوادي، ثم يمشي حتى يصعد المروة، فيكبر، ويذكر الله، ويهلل، ويدعو ثلاث مرات كما فعل على الصفا سبعة أشواط. ثم بقي على إحرامه؛ لأنه معه الهدي لم يحل، وأمر الناس أن يحلوا أن يقصروا، ويحل الذين ما معهم هدي، فطافوا، وسعوا، وقصروا، وحلوا بأمر النبي ﷺ أما الذين معهم هدي فأمرهم أن يبقوا على إحرامهم حتى حلوا يوم النحر. وبقيت حجة النبي ﷺ معروفة، من أرادها يراجع كتب أهل العلم، ومن ذلك كتابنا \" التحقيق والإيضاح \" فهو مختصر، ومفيد في هذا الباب. المقدم: أحسن الله إليكم، ونفع الله بعلمكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15745/صفة-حج-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58620.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":17281,"question":"المستمع عبد الكريم حبيب من السودان يقول: أنا مقيم في الرياض، وأريد أن أؤدي فريضة الحج في العام القادم -إن شاء الله- لكني لا أعرف كيف أبدأ، وجهوني إلى الصواب، وهل من إرشاد إلى كتاب معين يفيدني في أن أؤدي فريضة الحج على الطريق الصحيح؟ جزاكم الله خيرًا.","title":"ما يفعل من أراد الحج والعمرة؟","answer":"الجواب: نعم، يوجد كتاب مختصر كتبناه في مناسك الحج أسميناه \"التحقيق والإيضاح لكثير من مسائل الحج والعمرة والزيارة على ضوء الكتاب والسنة\" تراجع المكتب في الرياض، ويعطونك نسخة منه، أو أكثر لتستفيد، ولك أن تبدأ بالعمرة، فتعتمر في رمضان، أو في غيره. والعمرة أن تتوجه إلى مكة، فإذا وصلت الميقات تقول: اللهم لبيك عمرة، تغتسل وتتوضأ الوضوء الشرعي، وتصلي ركعتين سنة الوضوء، ثم تقول: (اللهم لبيك عمرة) في الميقات، ميقات الرياض إن كنت من طريق الرياض وهو السيل، وإن كنت في المدينة من ميقات المدينة، وإن كنت في الجنوب ميقات اليمن يلملم، الميقات الذي تمر عليه تحرم منه بالعمرة، تقول: اللهم لبيك عمرة، تنويها بقلبك، تنوي بقلبك العمرة، وتقول: اللهم لبيك عمرة، وتلبس الإزار، والرداء قبل الإحرام، قبل أن تقول: لبيك عمرة، قبل النية بالقلب، والأفضل لك أن تغتسل، وتتوضأ، وتصلي ركعتين سنة الوضوء، ثم تستمر، تقول: لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك هذه التلبية الشرعية، وهي التلبية التي لباها النبي -عليه الصلاة والسلام- حتى تصل مكة وأنت تلبي، لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك. وإن ذكرت الله، وسبحت الله، واستغفرت الله بين ذلك كله طيب، أو قرأت القرآن كله طيب، فإذا جئت المسجد الحرام تطوف سبعة أشواط بالكعبة، تبدأ من الحجر الأسود إليه في كل شوط، تذكر الله في أشواطك، وتدعوه، ولا بأس أن تقرأ القرآن، كله طيب، تبدأ بالتكبير: الله أكبر، عندما تبدأ الطواف، من الحجر وتستلمه بيدك وتقبله، ثم تجعل البيت عن يسارك وتطوف سبعة أشواط، كلما وازنت الحجر قبلته، واستلمته، وكبرت. وهكذا عند الركن اليماني تستلمه بيمينك، الركن اليماني، وتقول: باسم الله، والله أكبر، وتقول في آخر كل شوط: رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ [البقرة:201] في آخر كل شوط من السبعة، ثم تصلي ركعتين خلف مقام إبراهيم، أو في أي مكان من المسجد، والأفضل خلف مقام إبراهيم، ركعتين تقرأ فيهما الفاتحة وقل يا أيها الكافرون في الأولى، وقل هو الله أحد في الثانية، هذا هو الأفضل كما فعله النبي -عليه الصلاة والسلام- ثم تسعى بين الصفا والمروة سبعة أشواط. المقدم: إذًا هذا الموضوع ذو شقين: الأول تفضلتم بتوضيح ما يجب على أخينا أن يفعله إذا ما أرد العمرة، والثاني: إذا أراد أن يستفيد من هذا الكتاب؛ فعليه مراجعة الرئاسة العامة لإدارات البحوث العلمية والإفتاء والدعوة والإرشاد في الرياض ليستلم نسخة من هذا الكتاب. الشيخ: نعم نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16127/ما-يفعل-من-اراد-الحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_768/nour_76815.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":17334,"question":"هل صحيح أن الحاج يقصر من صلاته الرباعية، أيام حجه بما فيها أيام التشريق الثلاث؟","title":"حكم قصر الصلاة للحجاج من أهل مكة","answer":"الجواب: الحاج نعم يقصر في عرفة، وفي مزدلفة، وفي منى مثل ما فعل النبي ﷺ ولم يقل: يا أهل مكة أتموا، فقصر معه الناس في عرفة، صلوا الظهر ثنتين، والعصر ثنتين، وفي مزدلفة صلوا معه المغرب ثلاثًا، والعشاء ثنتين، ولم يقل: يا أهل مكة أتموا، فدل على أن الحجاج يفعلون مثلما يفعل غيرهم، يقصرون في منى، وفي عرفة، وفي مزدلفة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16186/حكم-قصر-الصلاة-للحجاج-من-اهل-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_769/nour_76908.mp3","categories":["أحكام الجمع","مسائل متفرقة في الحج والعمرة"]},{"id":17559,"question":"يقول هذا السائل: اتفق شخص مع آخر على إقامة مشروع تجاري على أن يقوم الشخص الأول بدفع رأس المال - مال المشروع - ويقوم الشخص الثاني بالإدارة فقط، وتقسم الأرباح مناصفة بينهم، وطلب الشخص الثاني من الشخص الأول مبلغًا من المال يخصم من نصيبه من الأرباح بعد إقامة المشروع، وذهب لأداء فريضة الحج هو وزوجته، وبعد رجوعه من الحج رجع الشخص الأول في كلامه، ورفض إقامة المشروع، فهل يجب أن يرد الشخص الثاني ما أخذه من مال، وهل يجب عليه أن يعيد الحج هو وزوجته؛ لأنه لم يرد المال؟ وجزاكم الله خيرًا.","title":"حكم رد مال الشريك في مشروع لم يكتمل","answer":"الجواب: هذه مسألة خصومة يرجع فيها إلى المحكمة، أما الحج فهو صحيح والحمد لله، إذا كان أداه على الوجه المشروع حجه صحيح، أما الخصومة بينهما في المشروع فهذا يرجع فيه إلى المحكمة. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16471/حكم-رد-مال-الشريك-في-مشروع-لم-يكتمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77516.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":17582,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (ن. ص. ق) أخونا يسأل مجموعة من الأسئلة من بينها أسئلة تصادف موسمًا مباركًا من أوسم الخير والبركة، ذلكم هو موسم الحج، أخونا يقول: حدثونا عن أنواع الحج؟ جزاكم الله خيرًا.","title":"صفة مناسك الحج الثلاثة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفأنساك الحج ثلاثة:\nالأول: الإحرام بالعمرة وحدها.\nالثاني: الإحرام بالحج وحده.\nالثالث: الإحرام بهما جميعًا.\nوصفة كل واحد؛ أما العمرة فيقول: اللهم لبيك عمرة، أو يقول: اللهم إني أوجبت عمرة، فهذا يقال له: عمرة، ويقال له: عمرة مفردة، سواء في أشهر الحج أو في غيره، هذه يحرم بها من الميقات الذي يمر عليه، من طريق المدينة ميقات المدينة، من طريق مصر والشام.. من طريق الساحل يحرم من الجحفة رابغ، من طريق اليمن يلملم، من طريق العراق ذات عرق (الضريبة)، من طريق نجد قرن المنازل (وادي قرن)، ويسميه الناس: السيل، على من أراد الحج أو العمرة أن يحرم من هذه المواقيت إذا مر على واحد منها، فإن كان بالعمرة يقول: اللهم لبيك عمرة، أو اللهم إني قد أوجبت عمرة، وإن زاد: متمتعًا بها إلى الحج، إذا كان في أشهر الحج شوال وذي القعدة وأول ذي الحجة فلا بأس، وإن لم يزدها فلا بأس، إذا قال: لبيك عمرة وهو نيته الحج وحج فإنه يسمى متمتعًا، وإن زاد فوقها: متمتعًا بها إلى الحج فلا بأس أيضًا، وإن قال: فإن حبسني حابس فمحلي حيث حبستني، كذلك لا حرج، ولا سيما إذا كان يخشى حادثًا من مرض أو غيره، فيطوف و يسعى ويقصر من عموم شعر رأسه.. من مجموع الشعر، الجوانب والوسط، يعم الشعر، ثم يحل، وبهذا تمت العمرة، وإن شاء حلق الرأس حلقًا بالموسى وبالمكينة التي تأتي على أصله، فهذه أنساك العمرة: طواف وسعي وتقصير أو حلق بعد الإحرام من الميقات.\nوالإحرام بالنية.. بالقلب،كونه ينوي بقلبه الدخول في العمرة مثلًا، ثم يلبي يقول: اللهم لبيك عمرة، ينوي بقلبه في الميقات الذي يمر عليه أنه يريد العمرة وهي زيارة البيت العتيق، وتسمى هذه النية إحرام، بالنية في القلب، ويشرع له التلبية فيقول: اللهم لبيك عمرة، ويستحب له أن يغتسل إذا تيسر، يغتسل ويقلم أظفاره إن كان فيها طول أو قص شاربه هذا أفضل، وإن لم يفعل فلا حرج، وأحرم بدون اغتسال وبدون قص أظفار ولا قص شارب لا حرج، ويلبس إزارًا ورداء، الرجل، إزار ورداء أبيضين الأفضل، كونه أبيض أفضل، وإن كانت من نوع آخر كالأحمر والأسود فلا حرج، لكن الأبيض أفضل؛ لقوله ﷺ: البسوا من ثيابكم البياض فإنها من خير ثيابكم، وكفنوا فيها موتاكم، وقد ثبت عنه ﷺ أنه دخل عام الفتح وعليه عمامة سوداء، وثبت عنه ﷺ أنه طاف مضطبعًا ببرد أخضر، فالألوان الأخرى جائزة، ولكن البياض هو الأفضل.\nأما المرأة فإنها تحرم فيما تيسر لها من اللباس العادي للنساء، أحمر أو أسود أو أخضر أو غيره، لكن تترك الثياب التي فيها زينة؛ لأنها قد تعرض لفتنة في الطواف والسعي، تكون ملابس عادية ليست فيها فتنة، هذا هو الأفضل، ولكن لا تلبس القفازين في اليدين ولا تنتقب النقاب للوجه حال إحرامها لا في العمرة ولا في الحج، والنقاب شيء يصنع للوجه، تلبسه المرأة في وجهها، ينقب فيه نقبان أو نقب واحد للعينين، هذا النبي ﷺ نهى عنه قال: لا تنتقب المرأة، والقفازان: غشاءان يجعلان في اليدين، غشاءان تجعل اليدان فيهما، أيضًا ممنوعة منهما المحرمة، ولكن تغطي وجهها بغير النقاب، تغطي وجهها بالجلباب، بالشيلة، تغطي يديها بجلبابها بعباءتها ما يخالف.\nالمقدم: هذا في حالة وجود الأجانب؟\nالشيخ: في حال الإحرام، لا تلبسها في حال الإحرام مطلقًا ولو ما عندها أحد، لا تلبس النقاب ولا القفازين، لكن عند وجود الأجنبي تغطي وجهها ويديها بشيء غير النقاب وغير القفازين، تقول عائشة رضي الله عنها: \"كنا مع النبي ﷺ في حجة الوداع، فإذا دنا منا الرجال سدلت إحدانا خمارها على وجهها من رأسها، فإذا بعدوا كشفنا\".\nوالنوع الثاني: الحج نكمل: النوع الثاني الحج، وهو أن ينوي الإنسان الحج فقط بقلبه، نية الحج فقط، من الميقات، سواء كان رجل أو امرأة، هذا يسمى الإفراد إفراد الحج، فيحرم بالحج بقلبه، ينوي الحج بقلبه ويلبي ويقول: اللهم لبيك حجًا، أو: اللهم إني أوجبت حجة أو حجًا، من الميقات الذي يمر عليه، وإن كان في مكة كذلك قال: لبيك حجًا، أو حول مكة من الميقات من محله اللي ينشئ منه الإحرام، ... في جدة، يقول: لبيك حجًا أو عمرة كما تقدم، أو اللي في الشرايع أو كان في ... أو أم السلم، المقصود من كان دون المواقيت يحرم بالعمرة إذا شاء مفردة أو بالحج مفردًا: اللهم لبيك حجًا، من محله اللي ينشئ منه الإحرام، وإن كان قبل المواقيت أحرم من الميقات كما تقدم، ويقول: لبيك حجًا، هذا يسمى حجًا مفردًا.\nفإذا وصل مكة شرع له أن يجعلها عمرة، إن كان الوقت واسعًا شرع له أن يجعلها عمرة، يفسخه إلى عمرة، كما أمر النبي ﷺ أصحابه بذلك .....، يطوف ويسعى ويقصر ويجعلها عمرة، أما إن كان الوقت ضيق قصد عرفات وحج مع الناس بحج مفرد، ولكن إذا تيسر له دخول مكة والطواف والسعي ويقصر ويجعلها عمرة فهذا يكون هو الأفضل، ويسمى فسخ الحج إلى العمرة، فإن بقي على إحرامه وحج مع الناس بحج مفرد فلا بأس، يطوف ويسعى عند قدومه، ثم يبقى على إحرامه حتى يحج مع الناس، أو يبقى على إحرامه ولا يطوف ولا يسعى إلا بعد الحج في يوم النحر أو ما بعده، كله جائز، ولكن الأفضل أنه يبدأ بالطواف والسعي قبل الحج، يطوف ويسعى ويبقى على إحرامه حتى ينتهي من عرفات، فإذا جاء يوم العيد طاف وسعى كما فعل النبي ﷺ، فإنه حج قارنًا وطاف وسعى عند قدومه ولم يحل؛ لأنه كان معه الهدي ﷺ.\nأما الذين أحرموا بالحج وليس معهم هدي أمرهم النبي ﷺ أن يجعلوها عمرة، أمرهم ﷺ أن يجعلوها عمرة، فطافوا وسعوا وقصروا وحلوا بأمره عليه الصلاة والسلام، فهذا يسمى نسك الإفراد .. الإفراد في الحج.\nوهناك نسك ثالث يسمى القران، فينوي بقلبه عمرة وحجًا جميعًا من الميقات، أو من محله اللي هو فيه كجدة أو أم السلم، من الميقات ينوي بقلبه حجًا وعمرة، ثم يلبي ويقول: اللهم لبيك عمرة وحجًا، هذا يسمى القران، وأعماله مثل أعمال الإفراد، يطوف ويسعى أول ما يقدم مكة، ويبقى على إحرامه حتى يفرغ من حجه، فإذا فرغ من حجه من عرفات طاف يوم العيد طواف الإفاضة فقط وأجزأه السعي السابق، ويسمى قارنًا بين الحج والعمرة، وأعماله كأعمال المفرد، لكن الأفضل له والسنة له أن يفسخ كالمفرد، يفسخ حجه إلى العمرة، يطوف ويسعى ويقصر ويحل. إذا كان ما معه هدي، ليس معه هدي فالسنة له أنه يطوف ويسعى ويقصر ويتحلل، كالذي أحرم بالحج مفردًا، يطوف ويسعى ويقصر ويجعلها عمرة؛ لأن الرسول ﷺ أمر أصحابه الذين أحرموا بالحج مفردًا أو بالحج والعمرة جميعًا وليس معهم هدي أمرهم أن يجعلوها عمرة، فطافوا وسعوا وقصروا وحلوا، وأما من كان معه الهدي فإنه يبقى على إحرامه، والأفضل له أن يلبي بحج وعمرة جميعًا، إذا كان معه الهدي، كما فعله النبي ﷺ فإنه أحرم بالحج والعمرة جميعًا وكان معه هدي، كان معه ثلاثة وستين بدنة، ثلاثة وستين من الإبل أتى بها من المدينة، وجاء علي من اليمن بسبع وثلاثين، صار الجميع مائة، نحرها يوم النحر عليه الصلاة والسلام، فمن كان معه هدي ولو ناقة واحدة ولو شاة واحدة أتى بها هذا يبقى على إحرامه ويلبي بالحج والعمرة جميعًا، ومن ليس معه هدي فإنه يلبي بالعمرة ويطوف ويسعى ويقصر ويحل، وإن لبى بالحج مفردًا أو بالحج والعمرة جميعًا فإنه يفسخ، يطوف ويسعى ويقصر ويجعلها عمرة كما أمر به النبي ﷺ الصحابة الذين حجوا معه وليس معهم هدي، هذا هو الصواب عند المحققين من أهل العلم.\nوأعمال القارن وأعمال المفرد شيء واحد، طواف وسعي، إن فعلهما عند القدوم أجزأه السعي ويبقى عليه الطواف يوم العيد أو بعده، وإن لم يسع مع طواف القدوم سعى مع طواف الإفاضة بعد عرفات يوم العيد أو بعده، سعي واحد يجزي المفرد ويجزي القارن، سعي واحد فقط أما المتمتع الذي طاف وسعى وقصر من عمرته وحل، هذا عليه سعي ثاني مع طوافه للحج يوم العيد أو بعده للحج، وذاك السعي الأول للعمرة التي خلص منها وطاف وسعى لها وقصر منها. نعم.\nالمقدم: جزاكم الله خيرًا، وأنتم تتفضلون بالحديث عن أنواع الحج جزاكم الله خيرًا، ذكرتم أيضًا صفة الحج، هل من إضافة لتكميل صفة الحج؟\nالشيخ: صفة الحج مثلما تقدم؛ إذا أحرم به من مكة إنسان من أهل مكة أو محل بها يتوجه إلى منى يوم الثامن، وهكذا لو كان قادمًا من بلده يوم الثامن وأحرم بالحج مفردًا أو بالحج والعمرة جميعًا فإنه يتوجه إلى منى ويصلي بها الظهر ركعتين والعصر ركعتين، كل واحدة في وقتها أفضل، والمغرب ثلاث في وقتها، والعشاء ثنتين في وقتها، والفجر ثنتين في وقتها، هكذا فعل النبي ﷺ، لما توجه من مكة إلى منى يوم الثامن صلى بها الظهر والعصر والمغرب والعشاء والفجر كل واحدة في وقتها قصرًا، من دون جمع، الظهر ثنتين والعصر ثنتين كل واحدة في وقتها، والمغرب كذلك في وقتها، والعشاء ثنتين في وقتها، والفجر ثنتين في وقتها مع سنتها، بأذان وإقامة، هذا هو الأفضل وهذا هو السنة.\nوفي صباح العيد يتوجه إلى عرفات وهو في خروجه من مكة ملبي بالحج، يقول: لبيك حجًا، ويقول: (لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك لا شريك لك)، وهكذا اللي أحرم من الميقات يلبي بهذا، يلبي بالحج مفرد الأول في الميقات بعدما يتهيأ، بعدما يغتسل إذا تيسر، ويلبس إزاره ورداءه، وبعدما يتطيب يركب الدابة أو السيارة، ثم يلبي ناويًا بقلبه الدخول في الحج أو في العمرة إن كان أراد عمرة مفردة، ثم إذا ركب يقول: اللهم لبيك عمرة، إن كان عمرة، أو اللهم لبيك حج، إن كان حج؛ لأن النبي ﷺ لبى بعدما ركب، بعدما ركب دابته لبى عليه الصلاة والسلام، هذا هو الأفضل بعد الركوب، يتهيأ وهو في الأرض بالغسل ويصلي ركعتين سنة الوضوء ثم يلبس إزاره ورداءه، وينوي بقلبه الدخول في النسك بعدما يركب الدابة أو السيارة، ينوي بقلبه الدخول في النسك ويلبي: اللهم لبيك حجاً، إن كان مفرد، أو: اللهم لبيك عمرة، إن كان عمرة مفردة، أو: حجاً وعمرة، إن كان قارناً إذا كان معه الهدي، يلبي بهما جميعًا إذا كان معه هدي، ناقة أو بقرة أو شاة أو أكثر.\nوالأفضل لمن لبى من الميقات أنه يدخل مكة أول، ولو كان في يوم الثامن، الأفضل يدخل مكة ويطوف ويسعى؛ لأن الرسول ﷺ دخلها ..بدأ بها ﷺ، يطوف ويسعى للحج إن كان مفردًا، أو لعمرة إن كان معتمر، يطوف ويسعى ويقصر ويحل إن كان معتمر، وفي يوم الثامن يلبي بالحج، يخرج إلى منى، كما فعله النبي ﷺ فإنه لبى يوم الثامن خارجًا إلى منى، والصحابة أمرهم أن يلبوا بالحج يوم الثامن الذين حلوا، أمرهم أن يلبوا بالحج من مكة من منازلهم، ثم يتوجهون إلى منى ملبين بالحج، يوم الثامن، هذا هو الأفضل.\nوفي يوم التاسع يتوجهون إلى عرفات بعد طلوع الشمس ملبين بالحج، ومن كبر أو هلل فلا بأس، والأفضل التلبية في طريقه إلى عرفات.\nفإذا وصل عرفات نزل في غربيها محل يقال له: نمرة، يصلي فيه الظهر والعصر جمعًا وقصرًا، هذا هو الأفضل إذا تيسر؛ لأن الرسول فعل ذلك عليه الصلاة والسلام، بأذان واحد وإقامتين، الظهر ثنتين والعصر ثنتين، وهكذا الحجاج كلهم، الأفضل لهم يجمعون ويقصرون، الظهر ثنتين والعصر ثنتين بأذان واحد وإقامتين، وإذا صلوا مع الإمام أو نائبه يكون أفضل في مسجد نمرة، يكون أفضل إذا تيسر ذلك، ثم بعد الصلاة يقصد كل واحد محله من عرفات، يقصد محله من عرفات، في خيمته أو في سيارته يستقبل القبلة ويدعو الله ويهلل ويكبر ويلبي حتى تغيب الشمس، سوء .. في الخيمة أو في غير ذلك من الأمكنة، أو في السيارة، الأمر واسع بحمد الله، والنبي ﷺ ، جلس على الدابة واستقبل القبلة وجعل يدعو ويهلل ويكبر حتى غابت الشمس عليه الصلاة والسلام، والحجاج هكذا، كل واحد منهم بعد صلاة الجمع يتوجه إلى عرفات ويستقبل القبلة وكلها موقف كل عرفة موقف، كما قاله النبي ﷺ، لما وقف عند الصخرات واستقبل القبلة قال: وقفت هاهنا وعرفة كلها موقف. فالإنسان يقف يوم عرفة في أي مكان كان منها، تحت الشجر، أو تحت الخيمة أو في سيارته، يجلس فيها ويدعو الله ويهلل ويكبر مستقبل القبلة هذا هو الأفضل، مستقبل القبلة، حتى تغيب الشمس، ويرفع يديه بالدعاء ويلح في الدعاء حتى تغيب الشمس لفعله ﷺ، وهو يوم عظيم يوم عرفة، يوم عظيم، يقول النبي ﷺ: ما من يوم أكثر عتيقًا من النار من يوم عرفة، وإن الله سبحانه يدنو فيباهي بأهله الملائكة، فهو يوم عظيم، يدنو الله من أهله ويباهي بهم الملائكة، وليس في الدنيا يوم أكثر عتقاء من النار من يوم عرفة. فينبغي للحاج أن يجتهد في الدعاء في هذا اليوم العظيم، ويحضر قلبه بين يدي الله ويبكي من خشية الله ويجتهد في الدعاء ويلح ويكرر، ويكثر من التلبية ومن قول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت وهو على كل شيء قدير، سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، سبحان الله وبحمده، سبحان الله العظيم، ويستغفر الله ويكثر من الدعاء في هذا اليوم العظيم، حتى تغيب الشمس. نعم.\nالمقدم: بعد أن تغرب الشمس؟\nالشيخ: ينصرف الناس إلى مزدلفة، إذا غابت الشمس ينصرف الناس إلى مزدلفة ملبين مهللين مكبرين حتى يصلوا مزدلفة، بهدوء وسكينة، النبي عليه السلام يقول لهم: السكينة السكينة، حتى لا يضر أحد أحدًا، وهو ملبي، حتى يصل مزدلفة فيصلي بها المغرب والعشاء جمعًا وقصرًا من حين يصل، ولو في وقت المغرب، المغرب ثلاثًا والعشاء ثنتين، بأذان وإقامتين، كل صلاة لها إقامة، لكن لا يصلي بينهما شيئًا، النبي ما صلى بينهما عليه الصلاة والسلام، ولا بعدهما، هذا هو الأفضل. ثم بعد ذلك يحط الناس الرحال، يصلون قبل حط الرحال، ثم بعد هذا يحطون رحالهم مع أمتعتهم اللي يبي يتعشى واللي ينام، النبي ﷺ لما صلى نام عليه الصلاة والسلام، والناس بالخيار من شاء نام ومن شاء تناول الطعام أو اشتغل بشيء آخر، والأفضل أن ينام حتى يتقوى على طاعة الله في يوم العيد.\nفإذا طلع الفجر صلى الحجاج الفجر بأذان وإقامة، يصلي سنة الفجر ثنتين والفريضة ثنتين كما فعله النبي ﷺ، ثم يشتغلون بالذكر والدعاء في مزدلفة مع رفع اليدين، حتى يسفروا، ثم ينصرفون قبل طلوع الشمس إلى منى كما فعله النبي ﷺ، فإنه أسفر جدًا ثم انصرف قبل طلوع الشمس إلى منى عليه الصلاة والسلام، فهذا هو السنة للحجيج.\nلكن لا مانع من تعجيل الضعفة من مزدلفة قبل الفجر، النبي ﷺ أمر الضعفة من النساء والصبيان ونحوهم ممن يكون معهم أن ينصرفوا إلى منى في آخر الليل قبل حطمة الناس قبل الزحمة، هذا أفضل، وإن جلسوا فلا حرج، وإذا انصرفوا في آخر الليل قبل زحمة الناس فلا حرج عليهم، ولهم الرمي في آخر الليل هم ومن معهم، أو تأخير الرمي إلى الضحى، كل ذلك جائز لهم، ومن تقدم ورمى وذهب إلى البيت وطاف فلا حرج، فإن أم سلمة رضي الله عنها رمت قبل الفجر ثم مضت وأفاضت إلى مكة، ولكن الأفضل أنه يرمي أولًا ثم ينحر الهدي بعد طلوع الشمس إن كان عنده هدي، ثم يحلق الرجل أو يقصر، والمرأة تقصر، ويحصل التحلل بذلك، التحلل مما حرم على المحرم ما عدا النساء، ثم الطواف بعد ذلك. فإذا طاف بعد الرمي والحلق أو التقصير حل له كل شيء حتى النساء، مما حرم عليه بالإحرام، وإن كان متمتعًا سعى مع طواف الإفاضة سعيًا آخر للحج، أما إن كان مفردًا أو قارنًا فإنه يكفيه السعي الأول اللي فعله مع طواف القدوم، إذا كان ما تحلل، بقي على إحرامه حتى حل، وإن كان ما سعى مع طواف القدوم سعى مع طواف الحج، فعليه سعي لا بد منه، إما أيام الحج أو يقدمه مع طواف القدوم، وهذه أعمال الحج يوم العيد، إذا انصرفوا من منى بعد إسفارهم، وهكذا الضعفة إذا انصرفوا من منى في آخر الليل. المشروع لهم بعد ذلك أربعة أمور: الرمي، ثم النحر، ثم الحلق أو التقصير، ثم الطواف والسعي إن كان عليه سعي، هذه تكون في يوم العيد، والأفضل بعد طلوع الشمس، يرمي أولًا الجمرة بسبع حصيات يكبر مع كل حصاة، ويقطع التلبية، عند الرمي يقطع التلبية، انتهت التلبية، ثم بعد الرمي ينحر إن كان عنده ذبح، ثم بعد الذبح يحلق أو يقصر والحلق أفضل؛ لأن الرسول ﷺ دعا للمحلقين ثلاث مرات بالمغفرة والرحمة وللمقصرين مرة واحدة فالحلق أفضل، إلا النساء فليس عليهن حلق، ولكن يقصرن، النساء عليهن التقصير من مجموع الرأس، من كل عميلة قليل، وإن كان منقوض من أطراف الشعر كله للرجل والمرأة، ثم يحصل التحلل، يعني: التحلل الأول، يجوز له أن يطيب، يقلم أظفاره، يقص شاربه، يلبس المخيط، يغطي رأسه، هذا التحلل الأول، ويحصل بالرمي، لكن كونه يضيف إليه الحلق أو التقصير يكون أفضل وأحوط، وإلا التحلل الأول يحصل بالرمي، لكن إضافة الحلق والتقصير إليه أفضل خروج من خلاف العلماء، ولما روي عن عائشة رضي الله عنها عن النبي ﷺ أنه قال: إذا رميتم وحلقتم فقد حل لكم الطيب واللباس وكل شيء إلا النساء، ويبقى عليه تحريم النساء، فإذا طاف بالبيت وسعى حل له كل شيء حتى النساء مما حرم عليه بالإحرام للمرأة والرجل، إذا طافت وسعت إن كان عليها سعي حل لها زوجها، وهكذا الرجل إذا طاف وسعى إن كان عليه سعي حلت له زوجته بعد الرمي والحلق أو التقصير.\nثم يبقى على الجميع أيام منى، الرمي أيام منى، وطواف الوداع بعد الفراغ من كل شيء.\nوالترتيب ليس بواجب، لو أنه قدم النحر على الرمي أو الحلق على الرمي أو على النحر أو الطواف لا حرج الحمد لله، لو طاف قبل أن يرمي أو قبل أن ينحر أو قبل أن يحلق لا حرج، أو نحر قبل أن يرمي أو حلق قبل أن يذبح لا حرج، النبي سئل عن هذا يوم العيد فقال: لا حرج لا حرج عليه الصلاة والسلام، لكن الأفضل الذي فعله النبي ﷺ أنه يرمي أول ثم ينحر إن كان عنده ذبح ثم يحلق أو يقصر هذا هو الأفضل، ثم يتحلل، ثم يكون الطواف بعد ذلك يوم العيد إن تيسر أو بعد العيد، وهكذا السعي يكون بعد الطواف إن كان عليه سعي، إن كان متمتع يسعى مع طواف الحج، وهكذا القارن والمفرد الذي لم يحل عليه السعي، إن كان سعى مع طواف القدوم أجزأه وإلا سعى مع طواف الإفاضة. نعم.\nالمقدم: جزاكم الله خيرًا، سماحة الشيخ! وأنتم تتفضلون بهذا البيان الشافي الكافي للصفة الصحيحة للحج لمن أراد أن يحج على الطريقة المتبعة المشروعة والتي سنها الرسول عليه أفضل الصلاة والسلام، لا شك أن هناك بعض الأمور قد تخطر ببال السادة المستمعين، أو أمور وقع فيها بعض الحجاج ويسألون عنها، أستميحكم العذر في عرضها في حلقة قادمة إن شاء الله تعالى، ذلكم أن الوقت المخصص لهذه الحلقة شارف على الانتهاء.\nالشيخ: لا بأس.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16511/صفة-مناسك-الحج-الثلاثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_840/nour_84001.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":17657,"question":"(س. س. س) هذا السائل رمز لاسمه من مكة المكرمة، السائلة (س. س. س) تقول: ذهبت امرأة لتأدية مناسك العمرة، وطافت بالبيت وسعت وقصرت شعرها وهي حائض، ما الحكم؟ وماذا عليها مأجورين؟","title":"ما حكم من اعتمرت وهي حائض؟","answer":"الجواب: عليها أن تعيد الطواف إذا طافت وهي حائض عليها أن تعيد، أما السعي يجزي، فعليها أن تعيد الطواف، وتعيد التقصير، تقصر من رأسها بعد الطواف، والسعي يكفيها، يعني الطواف من الحائض غير صحيح لابد من الطهارة، فعليها أن ترجع إلى مكة وليس لزوجها قربانها حتى تطوف إذا كان لها زوج، ترجع وتطوف والحمد لله، ثم تـفضي إلى تقصير من جميع رأسها وتمت عمرتها. فإن كان زوجها قد وطئها؛ فعليها فدية ذبيحة تذبح في مكة للفقراء، وعليها أن تكمل العمرة وتأتي بعمرة جديدة من الميقات بدل العمرة التي أفسدتها بالجماع، تطوف لعمرتها السابقة، وتقصر، ثم تأتي بعمرة جديدة إذا كان قد جامعها الزوج، وعليها ذبيحة تذبح في مكة للفقراء.\nالمقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16586/ما-حكم-من-اعتمرت-وهي-حاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59427.mp3","categories":["مسائل متفرقة في الحج والعمرة","الحيض والنفاس","قضايا المرأة"]},{"id":17686,"question":"إذا حاضت المرأة قبل أن تبدأ بالعمرة يا شيخ فماذا تعمل بعد أن أحرمت يقول؟","title":"ما حكم من حاضت بعد إحرامها للعمرة؟","answer":"الجواب: تبقى في مكة حتى تطهر ثم تطوف وتسعى وتقصر، فإن دعت الحاجة إلى سفرها إلى الطائف أو جدة أو غيرهما سافرت وهي على إحرامها ثم ترجع حتى تؤدي طواف العمرة وسعيها، إلا أن كانت شرطت: إن حبسني حابس ثم أصابها الحيض؛ فلها التحلل إذا أرادت يعني أصابها عذر حبسني حابس يعني: عذر كالحيض، فإنها تحل ولا شيء عليها، أو أصابها مرض. نعم.","link":"https://binbaz.org.sa/fatwas/16625/ما-حكم-من-حاضت-بعد-احرامها-للعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59515.mp3","categories":["مسائل متفرقة في الحج والعمرة","الحيض والنفاس","قضايا المرأة"]},{"id":18086,"question":"أحد الإخوة المستمعين سمى نفسه: يوسف عثمان يوسف، بعث برسالة، يقول في أحد أسئلتها: إذا أدى الإنسان فريضة الحج على أكمل وجه، ولم يزر قبر الرسول ﷺ ولم يذهب إلى المدينة المنورة، هل عليه إثمٌ في ذلك؟","title":"حكم من حج ولم يزر المدينة ولا قبر النبي ﷺ","answer":"الجواب: ليس عليه إثم، الحج مستقل، والزيارة مستقلة، فليس من شرط الحج الزيارة، ولا من أركانه، ولا من واجباته، فإذا حج ولم يزر المدينة، ولم يزر النبي ﷺ فلا شيء عليه، حجه تام، ولكن يستحب أن يزور المدينة، وأن يصلي في مسجد النبي ﷺ في أي وقت، يزور المدينة؛ لأن الرسول عليه السلام قال: صلاةٌ في مسجدي هذا، خيرٌ من ألف صلاة فيما سواه، إلا المسجد الحرام، وقال ﷺ: لا تشد الرحال إلا إلى ثلاث مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى. فيستحب له أن يزور المسجد النبوي، ويسلم على النبي ﷺ وعلى صاحبيه: الصديق و عمر ، ويزور قباء، يصلي فيه ركعتين، مسجد قباء، يزور البقيع، ويسلم على أهل القبور، وهكذا الشهداء في أحد، يسلم عليهم، كل هذا سنة، لكن شد الرحل يكون للمسجد، يكون شد الرحل بالنية للمسجد، ثم إذا وصل المدينة؛ سلم عليه وعلى صاحبيه، وزار مسجد قباء، وسلم على المقبورين في البقيع، وفي أحد، هذا هو السنة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17121/حكم-من-حج-ولم-يزر-المدينة-ولا-قبر-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73010.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":18548,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: أخوكم في الله سليمان مصري ومقيم في المدينة المنورة، يقول: إنني قمت بأداء فريضة الحج والحمد لله رب العالمين، ولكن أثناء ارتداء الإحرام، وفي منى قبل يوم عرفة، كنت جالسًا تحت شجرة مزروعة، ومن اشتداد الحرارة وضعت الشمسية عليها، وقمت بكسر أحد فروعها الصغيرة ناسيًا ومتجاهلًا أنني محرم؛ وذلك من شدة الحرارة، فهل علي شيء؟ مع أنني سألت أحد الإخوان فقال لي: ما دامت الشجرة مزروعة من أحد الأفراد، ولم تخرج من نفسها نابتة فليس عليك شيء؟وجهوني جزاكم الله خيرًا.","title":"حكم كسر أغصان الشجر في الحرم","answer":"الجواب: المحرم إذا استظل بالشجر أو بالشمسية أو بالجبل أو بالخيمة، لا حرج عليه، الحمد لله، الصواب ليس عليك شيء، سواء كانت الشجرة نابتة من نفسها، أو أنبتها غيرها، سواء غرسها إنسان، أو أنبتت بفعل الله  من دون غراس. فالحاصل: أن كون المحرم يستظل بالشجرة أو بالخيمة أو بالشمسية، أو ما أشبه ذلك؛ لا حرج في هذا، نعم. المقدم: جزاكم الله خيرًا، إذا كسر من شجرة مزروعة كسر منها غصنًا، فهل يعد منتهكًا لحرمة الحرم شيخ عبد العزيز؟ الشيخ: نعم، إذا كانت في الحرم لا يكسر شيء، ولا يتعدى حتى الشوك لا يقطعه، نعم. المقدم: وإذا كانت مزروعة كما قيل له؟ الشيخ: مزروعة لا بأس من زرع الآدمي لا بأس. المقدم: الحمد لله، إذًا ليس عليه كفارة والحال هذه؟ الشيخ: إذا كانت من زرع آدمي لا، ليس عليه شيء. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17650/حكم-كسر-اغصان-الشجر-في-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73321.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":19348,"question":"إحدى الأخوات المستمعات تقول: أختكم أم فيصل من أبها بعثت برسالة تقول فيها: إنني وزوجي وأولادي وبناتي ذهبنا نريد العمرة وزيارة ولدي في مدينة الطائف، ولقد وصلنا إلى الطائف وبقينا يومين ننتظر أن تطهر البنات فنذهب إلى العمرة، ولكن لم يحصل هذا، ثم انتظرنا نصف يوم أيضاً ولم يطهرن، ولنا ولد في جدة جاء وأخذنا إلى جدة، وأشار علينا بالإحرام من الطائف، ولكننا لم نفعل، ونزلنا معه إلى جدة، وبقينا ثلاثة أيام، ثم فكرنا بالعمرة من جديد فقال ولدي: لا بد أن نرجع إلى الميقات، ونحرم من هناك خصوصًا وأن الجميع جاهزين للإحرام، ونذبح كذلك فدية عن كل واحد أراد العمرة من أبها، فازدحمت علينا الأمور، ولم يجتمع بنا الرأي؛ فأخذنا متاعنا، وذهبنا إلى أبها بدون عمرة، ولا أدري ما العمل، و هل علينا شيء فيما فعلنا، وهل علينا قضاء تلك العمرة، وماذا بشأن من هو دون سن البلوغ، أفتونا جزاكم الله خيرًا.","title":"حكم من نوى العمرة وعزم عليها ثم بدا له ترك ذلك","answer":"الجواب:\n\nليس عليكم شي ء؛ لأن العمرة إنما تجب مرة في العمر على المكلفين كالحج، وأنتم ذهبتم إلى جدة، ولم تنووا العمرة، ثم ترددتم في العمرة بعد ذلك، فليس عليكم شيء، ولو فرضنا أنكم ذهبتم إلى جدة بنية العمرة إذا فرغتم من شغلكم ثم رأيتم الترك فلا بأس بذلك، العمرة إنما تجب بعد الشروع فيها؛ لقول الله سبحانه: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ[البقرة:196].\n\nفإذا أتى الإنسان إلى الميقات، ولم يشرع في العمرة، وهون عن عزمه ورجع عن عزمه فلا بأس، أو أتى جدة ناويًا العمرة ثم هون ولم يحرم بالعمرة فلا بأس، حتى ولو أتى مكة، لو أتى مكة ولا يريد أن يأخذ العمرة بل دخلها لحاجة للتجارة، أو لزيارة بعض الأقارب بغير نية العمرة فلا شيء عليه؛ لقول النبي ﷺ لما وقت المواقيت: هن لهن ولمن أتى عليهن من غير أهلهن ممن أراد الحج والعمرة فلم يوجب العمرة والحج إلا على من أراد ذلك إذا مر بالميقات، فمن مر بالميقات، ولم يرد الحج، ولا العمرة، وإنما أراد تجارة في مكة، أو زيارة بعض أقاربه، أو أصدقائه، أو أراد غرضًا آخر؛ فليس عليه شيء.\n\nأما إذا أراد العمرة وصمم عليها فإنه يحرم من الميقات الذي مر عليه، إذا كان من طريق الطائف، أو من طريق نجد يحرم من السيل، وادي قرن، وإذا كان من طريق المدينة أحرم من ميقات المدينة، وإذا كان من طريق اليمن أحرم من ميقات اليمن يلملم، وإذا كان من طريق الساحل الغربي أحرم من رابغ الجحفة، ولو تردد أتى جدة مترددًا هل يعتمر أو ما يعتمر ما عنده جزم فإنه يحرم من جدة إذا عزم، ولا يحتاج يعود إلى الميقات، حتى إذا أتى إلى جدة من المدينة، أو من اليمن، أو من أبها، أو من غير ذلك ما عنده جزم عنده تردد هل يحرم أو ما يحرم؛ فإنه إذا أراد العمرة وعزم عليها أو الحج يحرم من مكانه لقوله ﷺ: ومن كان دون ذلك - يعني: دون المواقيت - فمهله من حيث أنشأ يعني: من حيث أنشأ النية.\n\nفأنتم لما هونتم عن العمرة، وذهبتم من الطائف إلى جدة من دون نية العمرة، لو أحرمتم من جدة فلا حرج عليكم ويكفي، أما لو نويتم العمرة، وأنتم في الطائف، وجزمتم عليها، وذهبتم لجدة مع نية العمرة؛ فأنتم يلزمكم العودة إلى الميقات، وتحرموا من الميقات إذا أردتم العمرة، وعزمتم عليها، فإن لم تفعلوا فعليكم دم.\n\nأما والحال ما ذكرتم ذهبتم إلى جدة مترددين، ثم عزمتم على الترك لا بأس عليكم، ولو ذهبتم إلى جدة ناوين العمرة ثم هونتم ما عليكم شيء؛ لأن ما عليكم شيء؛ لأنكم لم تشرعوا بها.\n\nالمقدم: جزاكم الله خيرًا. وهذا الحكم الذي تفضلتم به سماحة الشيخ يشمل جميع أفراد الأسرة؟\n\nالشيخ: نعم كلهم، أما الذي ما بلغ ما يلزمه شيء، الذي ما بلغ ما يلزمه إحرام، لكن إذا أحرم فهو أفضل، إذا أحرم مع أهله إذا كان ابن سبع فأكثر يعلمونه، ويحرم مع أهله أفضل، لكن لا يلزمه الإحرام إلا إذا بلغ الحلم.\n\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18558/حكم-من-نوى-العمرة-وعزم-عليها-ثم-بدا-له-ترك-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_941/nour_94112.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":19353,"question":"أسمع بعضًا من المنتسبين إلى الإسلام يرفعون شعارات معينة في الحج ويقولون: إنهم ينددون بأعداء الإسلام، وقد غيروا صورة الحج في أذهان الناس، ما هو توجيهكم سماحة الشيخ حول هذه القضية؟ جزاكم الله خيرًا.","title":"حكم رفع شعارات في الحج للتنديد بأعداء الإسلام","answer":"الجواب: المشروع للحجيج أن يشتغلوا بذكر الله وطاعة الله في أيام الحج، وفي وقت التلبية يلبون: \"لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك لا شريك لك\" وقت الإحرام إلى أن يبدأ في رمي الجمرة يوم العيد، وفي العمرة إلى أن يبدأ في الطواف، أما قبل البدء في الطواف في العمرة فيلبي، وفي الحج كذلك يلبي من حين يحرم بالحج إلى أن يبدأ في رمي جمرة العقبة فيشتغل بالتكبير، وعليه مع هذا الإكثار من ذكر الله، ومن الصلاة على النبي ﷺ. أما اتخاذ شعارات أخرى بزعمهم أنها مشروعة، كالتنديد بالأمريكان أو بـاليهود، أو بغيرهم من الناس شعارات يعلنونها؛ فهذا لا وجه له، ولا أساس، ولا أصل لهذا، النبي ﷺ إنما أمر في سنة تسع من الهجرة، أمر بإظهار البراءة من المشركين من أهل العهود، وأن تنبذ إليهم عهودهم، سنة تسع، وأن يعلم الناس أن الواجب عليهم الدخول في الإسلام، وإلا فليس لهم الحج، لقوله : يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْمُشْرِكُونَ نَجَسٌ فَلا يَقْرَبُوا الْمَسْجِدَ الْحَرَامَ بَعْدَ عَامِهِمْ هَذَا [التوبة:28]. فالنبي ﷺ نبذ إليهم عهودهم، الذين لهم عهود نبذ إليهم عهودهم المطلقة، والذين لهم عهد محدد نبذ إليهم عهدهم إلى مدته، يبقى إلى مدته ثم ينتهي إلا أن يدخلوا في الإسلام، وبين لهم ﷺ أنهم ليس لهم دخول الحرم وهم مشركون، كان هذا في عام تسع، بعث الصديق  وجماعة معه من الصحابة وبعث علي  ينادي ببراءة عام تسع؛ حتى يعلم الناس أن الحج إنما هو خاص بالمسلمين، وحتى يعلموا أن الرسول ﷺ برئ من عهودهم، فعليهم الدخول في الإسلام وترك ما هم عليه من الشرك وإلا فليمتنعوا من الحج ولا يحجوا وهم مشركون. وفي عام عشر لما حج حجة الوداع ترك هذه البراءة ولم يعلن شيئًا من ذلك، إنما كان هذا في عام تسع حتى يعلم من له عهد عند النبي ﷺ أنه على عهده إذا كان محددًا، وإن كان عهدًا مطلقًا فإنه نبذ إليه حتى يستعد للدخول في الإسلام أو يعرف أنه عدو فيحارب ويجاهد. أما ما يتخذه الرافضة أتباع الخميني في أيام الحج من المسيرات، وإعلان البراءة من أمريكا أو من اليهود هذا شيء من كيسهم هذا بدعة مالها أصل، هذه بدعة باطلة لا يجوز فعلها، ويجب على الدولة منعهم من ذلك، يجب على الدولة -وفقها الله- أن تمنعهم من هذا الهراء ومن هذا الفساد؛ لأنه يشوش على الحجيج ويؤذي الحجيج، وربما أفضى إلى فتنة كما وقع في العام الماضي في اليوم السادس من ذي الحجة، لما قاموا بمسيراتهم الصاخبة الخبيثة وإعلاناتهم انصدموا مع الناس وصار بلاء عظيم، وشر كثير، وقتل فئام من الناس وجرح جم غفير، كل هذا من أسباب باطلهم ومسيراتهم الباطلة، فالواجب على ولاة الأمور منعهم من ذلك ومنع غيرهم أيضًا لو أراد غيرهم يمنع، فمن جاء إلى الحج فليعمل بأعمال الحج، وليكن عليه الوقار والسكينة كما قال الله جل وعلا: الْحَجُّ أَشْهُرٌ مَعْلُومَاتٌ فَمَنْ فَرَضَ فِيهِنَّ الْحَجَّ فَلا رَفَثَ وَلا فُسُوقَ وَلا جِدَالَ فِي الْحَجِّ [البقرة:197]. فالحج ليس محل الرفث، وهو الجماع للمرأة قبل الحل، وهكذا القول السيئ والفعل السيئ يسمى رفث، وهكذا المعاصي كلها تسمى فسوق، وهكذا الجدال والمراء في الحج كله ممنوع، فالواجب على الحجيج أن يلتزموا بشرع الله في أرض الحرمين، وأن يستقيموا على دين الله، وأن يلزموا الواجب ويحذروا ما حرم الله من الرفث والفسوق والعصيان وسائر أنواع الشر، وهكذا إيذاء المؤمنين بهتافات، أو بمسيرات تؤذيهم في طرقهم كل هذا يجب منعه منعًا باتًا، سواء كان من الرافضة أو من غير الرافضة . المقدم: بارك الله فيكم، الواقع سماحة الشيخ تتطرقون إلى موضوع هام شغل بال المسلمين في هذه الأزمنة، ذلكم هو تلكم الشعارات التي يقوم بها بعض الحجاج المنتسبين إلى إيران، ومما ارتكبوه كما أشرتم وتفضلتم سد الطرقات وحرق السيارات.. وما إلى ذلك، بل لقد أدى بهم الحال إلى جلب المتفجرات ضمن أمتعتهم، لعل لسماحتكم توجيه للمسلمين عمومًا إذا ما لاحظوا شيئًا من ذلك كيف يتصرفون؟ الشيخ: نشرنا فيما مضى في موسم الحج الماضي عام ألف وأربعمائة وسبعة قرارًا من مجلس هيئة كبار العلماء بالتنديد بهذا الأمر وإنكاره، وأن المجلس يشجب هذا ويرى أنه باطل ويرى أن على الدولة منع ذلك منعًا باتًا؛ لما فيه من التشويش وإيذاء المسلمين، وهكذا المسلمون في كل مكان؛ في الهند والباكستان وفي أندونيسيا وفي مصر وفي أفريقيا وفي كل مكان أعلنوا تنديدهم بهذا العمل وإنكارهم لهذا العمل وأنه منكر، وأن الواجب تركه والحذر منه، وأن الواجب على الدولة منع ذلك، وأن الدول الإسلامية تؤيدها فيما ذهبت إليه من القضاء على هذا المنكر والحرص على تأمين الحجيج، ودفع الأذى عنهم سواء من الشيعة أو غير الشيعة، هذا واجب الدولة أن تحرص على أمن الحجيج وأن يؤدوا مناسكهم بطمأنينة وأمن وعافية، وأن تأخذ على أيدي السفهاء من الشيعة وغير الشيعة وتمنعهم من الباطل ومن الأذى ومن المسيرات. وإذا كان هناك تفجيرات صار الأمر أكبر وأخطر، ولكن الدولة -وفقها الله- قد تسامحت كثيرًا فيما مضى، ولكن الواجب عليها أن لا تتسامح في هذا؛ لأن هذا خطره عظيم، وقد وجد في كثير من الأشياء التي مع حجاج إيران وجد معهم أشياء من المتفجرات قد صفحت عنها الدولة في العام عام ألف وأربعمائة وستة وقالت: لعلهم يرجعون عن هذا العمل ويتركون ما يؤذي المسلمين ويؤذي الحجيج ولكنهم لم ينفع فيهم هذا الصفح وهذا الستر وهذا العمل الطيب حتى وقع ما وقع في عام ألف وأربعمائة وسبعة. فالمقصود أن ما وجد منهم من المتفجرات في عام ألف وأربعمائة وستة في جملة ما معهم من الأثاث الذي حملوه فإن هذا لاشك أنه يدل على خبث شديد وفساد كبير ونيات فاسدة وقصد سيئ للحجيج وإيذائهم نسأل الله السلامة؛ ولهذا وجب على الدولة أن تنكر هذا وأن تمنع هذا منعًا باتًا، والحقائب يجب أن تفتش لا حقائبهم ولا حقائب غيرهم؛ لأن الحقائب قد يكون فيها من المتفجرات ومن الأذى ما يضر المسلمين كما وقع في عام ألف وأربعمائة وستة، فالدولة وفقها الله واجب عليها أن تحرص على أمن الحجيج وأمن الحرمين بكل وسيلة ممكنة لا من جهة التفتيش عند نزولهم من الطائرات أو من الباخرات أو السفن أو السيارات يجب التفتيش حتى يحصل الأمن والسلامة إن شاء الله للمسلمين. المقدم: بارك الله فيكم. سماحة الشيخ! استخدم أولئك ضعاف النفوس كما استخدموا النساء والأطفال أيضًا في أغراضهم وفي تهريب الأسلحة والمتفجرات، هل من توجيه شيخ عبد العزيز ؟\nالجواب: نعم، لا يجوز لأحد أن يساعد في هذا، لا يجوز لأي مسلم أن يساعد الشيعة أو غير الشيعة في مساعدتهم بسكين أو عصا أو حجر أو متفجر كل ذلك منكر لا يجوز أن يساعدوا؛ لأن الله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2]. فالذي يساعدهم فيما يضر المسلمين شريك لهم في الإثم ويجب الأخذ على يديه وعقوبته إذا عرف، فلا يساعد من أراد الإلحاد في حرم الله أو إيذاء حجاج الله لا يجوز أن يساعد لا بحجر ولا بسكين ولا بغير هذا مما يؤذي المسلمين، سواء كان ذلك المجرم من الشيعة أو من غير الشيعة، هذا البلد محل أمن، ومن دخله كان آمنًا يعني يجب تأمينه، فلا يجوز أن يؤذى الحجيج ولا المعتمرون لا في المسجد الحرام ولا في مسجد النبي ﷺ والمدينة، بل يجب أن يؤمنوا ويحرص على سلامتهم حتى يرجعوا إلى بلادهم، وواجب الدولة القيام بهذا الأمر بغاية العناية وبأكمل العناية والضرب بيد من حديد على هؤلاء المجرمين الذين يفسدون في الأرض أو يريدون أن يفسدوا في الأرض ويؤذوا الحجيج ويخلوا بالأمن لا من حجاج إيران ولا من غيرهم هذا واجب الدولة، والمسلمون كلهم يؤيدون ذلك وفوق ذلك الكتاب والسنة يؤيدهم في ذلك، الكتاب والسنة يؤيد ما تفعله الدولة من الأخذ على يد السفهاء والمجرمين والعناية بأمن الحجيج والدفاع عنهم وكف الأذى عنهم وأن يؤدوا مناسكهم في غاية من الطمأنينة والسلامة والأمن والعافية. المقدم: جزاكم الله خيرًا ونفع بعلمكم. شيخ عبد العزيز فيما إذا أصر أولئك على تكرار ما أقدموا عليه فيما مضى هل تجيز الشريعة منعهم من دخول الحرم ؟ الشيخ: نعم، ما هو بتجيز بس توجب.\nالمقدم: توجب؟\nالشيخ: نعم، إذا وجد أنهم لم يرتدعوا وأنهم يأتون بما يضر الناس وجب أن يمنعوا منعًا باتًا من أي جنس كان سواء كانوا من إيران أو من غير إيران، من أي بلد ومن أي دولة إذا عرف أنهم يأتون للأذى لأذى الحجيج والإخلال بالأمن وجب على الدولة بكل قوة أن تمنعهم وهي معذورة في ذلك ومشكورة ومأجورة وليس مجرد جواز بل يجب وجوب أن تمنعهم من ذلك. نعم. المقدم: بارك الله فيكم. إعلامهم يقول هذا شيخ عبد العزيز ، إعلامهم يقول: إنهم إذا أتوا فسيكونون بنفس الغرض؟ الشيخ: يجب أن يمنعوا حتى يذعنوا للحق وحتى يقبلوا أن يكونوا كالمسلمين بقية المسلمين بأن يأتوا لأداء الحج بطمأنينة وإخلاص لله وكف للأذى، فإذا لم يفعلوا هذا وجب أن يمنعوا ويردعوا، وسوف يعين الله الدولة عليهم وعلى غيرهم ممن يريد الإجرام والأذى. المقدم: وهو كفيل.\nالشيخ: وهو الناصر سبحانه، يقول سبحانه: وَلَيَنصُرَنَّ اللَّهُ مَنْ يَنصُرُهُ إِنَّ اللَّهَ لَقَوِيٌّ عَزِيزٌ ۝ الَّذِينَ إِنْ مَكَّنَّاهُمْ فِي الأَرْضِ أَقَامُوا الصَّلاةَ وَآتَوْا الزَّكَاةَ وَأَمَرُوا بِالْمَعْرُوفِ وَنَهَوْا عَنْ الْمُنْكَرِ وَلِلَّهِ عَاقِبَةُ الأُمُورِ [الحج:40-41] ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تَنصُرُوا اللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ [محمد:7]. فكل من أراد الإسلام بسوء سواء في بلد الله الحرام أو في غير بلد الله الحرام فالواجب منعه من ذلك الواجب التنكيل به والأخذ على يديه بكل طريق يوصل إلى ذلك مما شرع الله  ولاسيما في أمن الحرمين فإن أمرهما أمر عظيم وهو لا يخص السعودية بل يعم جميع حجاج المسلمين. نعم. المقدم: إذًا على هذا طالما أنه يخص جميع المسلمين يجب أن تكون كلمة المسلمين واحدة تجاه هذا؟ الشيخ: يجب على المسلمين جميعًا أن يكونوا ضد من أراد الأذى من إيران وغير إيران، يجب على المسلمين جميعًا في أي مكان وفي أي دولة أن يكونوا شيئًا واحدًا ويدًا واحدة في محاربة من أبى إلا الأذى للمسلمين، وأن يكونوا ضد أعداء الله وضد من أراد إيذاء المؤمنين في مناسك الحج أو في غير ذلك، المسلمون شيء واحد، يجب أن يكونوا متكاتفين متعاونين ضد من أراد الأذى بالمسلمين كما قال الله : وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ [التوبة:71] وقال سبحانه: وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعاً وَلا تَفَرَّقُوا [آل عمران:103]. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18568/حكم-رفع-شعارات-في-الحج-للتنديد-باعداء-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_900/nour_90005.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":19424,"question":"إذا كنت أقيم بمنطقة جبلية وأريد أن أحج، فأي الكتب تنصحوني بقراءتها كي أحج على بصيرة؟ جزاكم الله خيرًا.","title":"كتب ينصح بقراءتها لمن أراد الحج والعمرة","answer":"الجواب: ننصحك بقراءة الكتب التي بينت أحكام الحج، مثل عمدة الحديث للشيخ عبد الغني المقدسي، مثل بلوغ المرام، مثل المنتقى هذه موجودة، وهناك مناسك فيها كفاية وبركة، إذا قرأتها استفدت منها، منها منسك كتبناه في هذا وسميناه: التحقيق والإيضاح لكثير من مسائل الحج والعمرة والزيارة وهو جيد ونافع ومفيد، وهناك مناسك أخرى لغيري من المشايخ والإخوان، مثل منسك الشيخ عبد الله بن جاسم منسك جيد ومفيد، فإذا استعملت شيئًا منه واستفدت منه طيب. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18659/كتب-ينصح-بقراءتها-لمن-اراد-الحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73614.mp3","categories":["مسائل متفرقة في الحج والعمرة","العالم والمتعلم","نصائح وتوجيهات"]},{"id":19425,"question":"يسأل فيقول: لي إخوة كثيرون، هل يجوز أن أعتمر عمرة واحدة وأهب ثوابها لهم جميعًا، علمًا بأن بعضهم لا يحافظ كثيرًا على الصلاة؟","title":"حكم من اعتمر عمرة واحدة عن عدة أفراد","answer":"الجواب: العمرة لا تكون إلا عن واحد، والحج لا يكون إلا عن واحد، فليس لك أن تحج عن جماعة، ولا أن تعتمر عن جماعة، وإنما الحج يكون عن واحد فقط والعمرة عن واحد فقط، إذا كان المحجوج عنه ميتًا، وهكذا المعتمر عنه ميتًا أو عاجزًا لمرض لا يرجى برؤه، أو لكبر سنه وعجزه عن الحج والعمرة؛ فلا بأس أن تحج عنه أو تعتمر عن شخص واحد. نعم. وإن أعطاك مالاً -وليه أو هو نفسه- إذا كان عاجز؛ لتحج عنه، فلا بأس إذا أخذته لله لا لقصد الدنيا. نعم. المقدم: سماحة الشيخ! جزاكم الله خيرًا، يذكر أنهم لا يحافظون على الصلاة؟ الشيخ: الذي لا يحافظ على الصلاة لا يحج عنه، إذا كان الشخص الميت أو العاجز عن الحج لكبر سنه أو مرض لا يرجى برؤه، لا يصلي أو عنده ما يكفره غير ترك الصلاة؛ لا يحج عنه، وترك الصلاة كفر أكبر، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18655/حكم-من-اعتمر-عمرة-واحدة-عن-عدة-افراد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74013.mp3","categories":["مسائل متفرقة في الحج والعمرة"]},{"id":19526,"question":"يقول هذا السائل: ما هي أركان الحج؟ وما هي أركان العمرة يا فضيلة الشيخ؟","title":"أركان الحج والعمرة","answer":"الجواب: أركان الحج أربعة: الإحرام، والطواف، والسعي، والوقوف بعرفة، كونه ينوي الإحرام بالحج، لا بد من نية، مع الوقوف بعرفة، مع الطواف والسعي، لا بد من هذا. والعمرة: إحرام، وطواف، وسعي، ثلاث، الله المستعان. نعم. المقدم: الله المستعان، حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18773/اركان-الحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94616.mp3","categories":["مسائل متفرقة في الحج والعمرة"]}]
